struct UserMacroArtifactTypecheck;

impl UserMacroArtifactTypecheck {
    // Evaluator-artifact construction can run in a singleflight winner;
    // nested Rayon work could starve while sibling workers wait for that winner.
    const EXECUTION: crate::pass::typecheck_core::TypecheckExecution =
        crate::pass::typecheck_core::TypecheckExecution::Sequential;

    fn discharge_deferred<'m>(
        elaborations: &mut Elaborations,
        env: &ModuleEnv<'m>,
    ) -> Result<(), Error> {
        elaborations.discharge_deferred_with_execution(env, Self::EXECUTION)
    }

    #[cfg(test)]
    fn check_package(
        package: &Package,
        type_interner: std::sync::Arc<crate::pass::typecheck_core::TypeInterner<Lowered>>,
    ) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
        Self::check_package_with_primitives(package, type_interner, None)
    }

    fn check_package_with_primitives(
        package: &Package,
        type_interner: std::sync::Arc<crate::pass::typecheck_core::TypeInterner<Lowered>>,
        primitives: Option<&crate::normalization::EvalPrimitiveEnv>,
    ) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
        let normalized = crate::pass::alpha_normalize::normalize_transformed_package(package);
        let typecheck_scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                type_interner,
            );
        let typecheck_scope = match primitives {
            Some(primitives) => typecheck_scope.with_evaluator_primitives(primitives),
            None => typecheck_scope,
        };
        check_normalized_package_with_scope_and_execution(
            normalized,
            typecheck_scope,
            Self::EXECUTION,
        )
    }
}

const USER_MACRO_REFLECTION_INFER_MESSAGE: &str =
    "`_` cannot be reflected by a user macro; write the type explicitly";

// `TyperPhase` and the `Typer<P>` dispatch trait live in
// `crate::pass::typecheck_core`; the Prime implementation lives in
// `crate::prime::typer`. The Lowered impl below ties this
// binary's `Elaborations` table to the trait -- it must stay here
// because `Elaborations` lives in this module -- and provides the
// `LoweredTyper` shim that wires the trait's two dispatch methods
// to the elaboration-aware `synth_expr` / `check_value_against`
// defined further down in this file.

/// Lowered's `Typer<Lowered>` implementation. A unit struct whose
/// only job is to wire the trait's static dispatch methods through
/// to the existing elaboration-aware functions in this module —
/// `synth_expr` (whose surface elaboration arms are inhabited) and
/// `check_value_against` (with its Lowered-only elaboration cases).
///
/// The shared helpers in `typecheck_core` (`synth_let`, `synth_fn`,
/// `synth_call`, …, as they migrate) call back into the trait via
/// `<P::Typer as Typer<P>>::synth_expr(...)`, so at Lowered the
/// recursion always lands here.
pub struct LoweredTyper;

pub(crate) fn resolved_nominal_type_binder(
    kind: crate::pass::typecheck_core::NominalTypeBinderKind,
    declaring_module_path: &str,
    name: &str,
) -> ResolvedBinder {
    use crate::pass::typecheck_core::NominalTypeBinderKind;

    match kind {
        NominalTypeBinderKind::TypeAlias => ResolvedBinder::TypeAlias {
            module_path: declaring_module_path.to_owned(),
            name: name.to_owned(),
        },
        NominalTypeBinderKind::Newtype => ResolvedBinder::Newtype {
            module_path: declaring_module_path.to_owned(),
            name: name.to_owned(),
        },
        NominalTypeBinderKind::HostType => ResolvedBinder::HostType {
            module_path: declaring_module_path.to_owned(),
            name: name.to_owned(),
        },
    }
}

pub(crate) fn resolved_binder_for_position<'m>(
    kind: crate::pass::typecheck_core::ResolvedBinderKind,
    name: &str,
    parent: Option<&str>,
    qualifier: Option<&str>,
    tcx: &crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
) -> ResolvedBinder {
    use crate::pass::typecheck_core::ResolvedBinderKind as Kind;

    let module_path = tcx.env.module_path.clone();
    let module_key = |module: &crate::ast::Module<Lowered>| {
        crate::pass::typecheck_core::module_path_key(module, None)
    };
    let qualified_owner = |alias: &str| {
        tcx.env
            .qualified_imports
            .get(alias)
            .map(|module| module_key(module))
    };
    let nominal_identity = |visible_name: &str| {
        let segment = PathSegment::new(visible_name.to_owned(), Span::new(0, 0));
        tcx.env.nominal_ref_identity(std::slice::from_ref(&segment))
    };
    match kind {
        Kind::Local => ResolvedBinder::Local {
            name: name.to_owned(),
            decl_span: tcx.value_decl_span(name),
        },
        Kind::TypeParam => ResolvedBinder::TypeParam {
            name: name.to_owned(),
            decl_span: tcx.type_param_decl_span(name),
        },
        Kind::Fn => ResolvedBinder::Fn {
            module_path,
            name: name.to_owned(),
        },
        Kind::CrossModuleFn => ResolvedBinder::Fn {
            module_path: tcx
                .env
                .cross_module_fn_def_modules
                .get(name)
                .map(|module| module_key(module))
                .unwrap_or(module_path),
            name: tcx
                .env
                .cross_module_fn_defs
                .get(name)
                .map_or(name, |definition| definition.name.as_str())
                .to_owned(),
        },
        Kind::HostEnvFn => ResolvedBinder::HostEnvFn {
            module_path: parent
                .and_then(qualified_owner)
                .or_else(|| {
                    tcx.env
                        .cross_module_env_fn_modules
                        .get(name)
                        .map(|module| module_key(module))
                })
                .unwrap_or(module_path),
            name: if parent.is_none() {
                tcx.env
                    .env_fn_defs
                    .get(name)
                    .map_or(name, |definition| definition.name.as_str())
            } else {
                name
            }
            .to_owned(),
        },
        Kind::Intrinsic => ResolvedBinder::Intrinsic {
            name: name.to_owned(),
        },
        Kind::Newtype => ResolvedBinder::Newtype {
            module_path: parent.and_then(qualified_owner).unwrap_or(module_path),
            name: name.to_owned(),
        },
        Kind::CrossModuleNewtype => {
            let (module_path, source) =
                nominal_identity(name).unwrap_or((module_path, name.to_owned()));
            ResolvedBinder::Newtype {
                module_path,
                name: source,
            }
        }
        Kind::NewtypeMember => {
            let (owner, source) = qualifier
                .and_then(qualified_owner)
                .map(|owner| (owner, parent.unwrap_or("").to_owned()))
                .or_else(|| parent.and_then(nominal_identity))
                .unwrap_or((module_path, parent.unwrap_or("").to_owned()));
            ResolvedBinder::NewtypeMember {
                module_path: owner,
                newtype: source,
                member: name.to_owned(),
            }
        }
        Kind::QualifiedImport => ResolvedBinder::QualifiedImport {
            alias: name.to_owned(),
        },
        Kind::QualifiedImportMember => ResolvedBinder::Fn {
            module_path: parent.and_then(qualified_owner).unwrap_or(module_path),
            name: name.to_owned(),
        },
    }
}

impl crate::pass::typecheck_core::Typer<Lowered> for LoweredTyper {
    // Surface Kio's call rule locally infers omitted universal type
    // arguments from value arguments and the expected return type.
    const ALLOW_ELIDED_UNIVERSAL_CALL_TYPE_ARGS: bool = true;

    // Kio surface accepts the multi-layer flat-call form per
    // `specs/language.md` § Type parameters — `foo(T1, v1, T2, v2)` against
    // `Forall([A], Function(A, Forall([B], Function(B, Unit))))`
    // walks both curry layers in one application.

    fn synth_expr<'m>(
        e: &'m Expr,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) -> Result<crate::pass::typecheck_core::Synth<Lowered>, Error> {
        let synth = synth_expr(e, tcx)?;
        // Record the synthesized type at the expression's span in the
        // position-keyed index for the LSP's hover, goto-definition,
        // and references queries. The post-macro synthesized type is what
        // hover should show, so the recording sits at the dispatch
        // boundary after every `synth_expr` arm has resolved the
        // expression's type (including the elaboration-bearing arms,
        // which set `synth.ty` to the post-elaboration target).
        Self::record_position_type(e.span(), synth.ty.clone(), tcx);
        Ok(synth)
    }

    fn check_value_against_interned<'m>(
        e: &'m Expr,
        expected: &InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) -> Result<(), Error> {
        check_value_against(e, expected, tcx)
    }

    fn check_user_macro_item<'m>(
        macro_def: &'m crate::ast::UserMacroDef<Lowered>,
        item_index: usize,
        env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
        elaborations: &mut Elaborations,
    ) -> Result<(), Error> {
        check_user_macro_item(macro_def, item_index, env, elaborations)
    }

    fn record_type_resolution<'m>(
        call_site: crate::ast::ExpressionSite,
        slot_index: usize,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_type_resolution(&mp, call_site.id, slot_index, resolved);
    }

    fn record_call_split<'m>(
        call_site: crate::ast::ExpressionSite,
        split_after_slot: usize,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_call_split(&mp, call_site.id, split_after_slot);
    }

    fn record_call_implicit_unit<'m>(
        call_site: crate::ast::ExpressionSite,
        slot_index: usize,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_call_implicit_unit_slot(&mp, call_site.id, slot_index);
    }

    fn record_literal_resolution<'m>(
        literal_site: crate::ast::ExpressionSite,
        resolved: crate::pass::typecheck_core::LiteralResolution<Lowered>,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        let (annotation, imports, aliases) =
            prepare_literal_annotation(literal_site, &resolved.ty, tcx);
        record_prime_bindings(tcx, &imports, &aliases);
        tcx.elaborations.record_literal_resolution(
            &mp,
            literal_site.id,
            annotation,
            resolved.numeric_value,
        );
    }

    fn record_fn_param_type<'m>(
        fn_site: crate::ast::ExpressionSite,
        value_param_index: usize,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_fn_param_type(&mp, fn_site.id, value_param_index, resolved);
    }

    fn record_proof_fn_body_type<'m>(
        fn_site: crate::ast::ExpressionSite,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        tcx.elaborations
            .record_proof_fn_body_type(&mp, fn_site.id, resolved);
    }

    fn record_newtype_member_binder_at<'m>(
        segment_span: crate::span::Span,
        declaring_module_path: &str,
        newtype: &str,
        member: &str,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let consumer_module = tcx.env.module_path.clone();
        tcx.elaborations.record_position_binder(
            &consumer_module,
            segment_span,
            ResolvedBinder::NewtypeMember {
                module_path: declaring_module_path.to_owned(),
                newtype: newtype.to_owned(),
                member: member.to_owned(),
            },
        );
    }

    fn record_position_type<'m>(
        expr_span: crate::span::Span,
        resolved: InternedType,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let mp = tcx.env.module_path.clone();
        let binders = tcx.in_scope_type_param_presentation();
        tcx.elaborations
            .record_position_type(&mp, expr_span, resolved, binders);
    }

    fn record_inlay_let_type<'m>(
        name_span: crate::span::Span,
        name: &str,
        resolved: Type,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        if name == "_" {
            return;
        }
        let mp = tcx.env.module_path.clone();
        tcx.elaborations.record_inlay_let_type(
            &mp,
            name_span,
            resolved,
            tcx.in_scope_type_param_presentation(),
        );
    }

    fn record_inlay_type_args<'m>(
        call_site: crate::ast::ExpressionSite,
        callee_span: crate::span::Span,
        slot_offset: usize,
        resolved: Vec<Type>,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        if resolved.is_empty() {
            return;
        }
        let mp = tcx.env.module_path.clone();
        let callee_end = crate::span::Span::new(callee_span.end, callee_span.end);
        tcx.elaborations.record_inlay_type_args(
            &mp,
            call_site,
            callee_end,
            slot_offset,
            resolved,
            tcx.in_scope_type_param_presentation(),
        );
    }

    fn discharge_module_deferrals(
        env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
        elaborations: &mut Elaborations,
    ) -> Result<(), Error> {
        elaborations.discharge_deferred(env)
    }
}

fn refl_type(name: &str, span: Span) -> Type {
    ty_path(name, span)
}

fn checked_term_type(span: Span) -> Type {
    refl_type("__Checked_term__", span)
}

fn comptime_proof_type(span: Span) -> Type {
    refl_type("__Comptime__", span)
}

fn fill_ctx_type(span: Span) -> Type {
    refl_type("__Fill_ctx__", span)
}

#[derive(Clone)]
enum UserMacroSignatureSlot {
    Type {
        param: TypeParam,
    },
    Value {
        ty: InternedType,
        layer: usize,
        expanded_start: usize,
        expanded_width: usize,
    },
}

#[derive(Clone)]
struct UserMacroSignatureLayout {
    slots: Vec<UserMacroSignatureSlot>,
    layers: Vec<UserMacroSignatureLayer>,
    result_ty: InternedType,
}

#[derive(Clone)]
struct UserMacroSignatureLayer {
    type_params: Vec<TypeParam>,
    value_param: Option<InternedType>,
    value_abi_arity: usize,
}

/// Goal-free output of the ordinary application frontier.  The source index
/// is stable across successive callable layers; `expanded_*` describes the
/// semantic right-spine slots occupied by the one source expression.
pub(crate) struct TypedUserMacroCall {
    pub(crate) layers: Vec<TypedUserMacroCallLayer>,
    pub(crate) result_ty: Option<InternedType>,
}

pub(crate) struct TypedUserMacroCallLayer {
    pub(crate) type_slots: Vec<TypedUserMacroTypeSlot>,
    pub(crate) sources: Vec<TypedUserMacroCallSource>,
    pub(crate) value_layer_consumed: bool,
}

pub(crate) struct TypedUserMacroTypeSlot {
    pub(crate) resolved: Option<InternedType>,
    pub(crate) occurrence: Option<InternedType>,
}

pub(crate) struct TypedUserMacroCallSource {
    pub(crate) source_index: usize,
    pub(crate) source: Expr,
    pub(crate) expanded_start: usize,
    pub(crate) expanded_width: usize,
    pub(crate) expected: InternedType,
}

/// Definition-side facts for one user-macro call before the shared
/// application frontier closes its type slots.  Reflection and evaluator work
/// deliberately stay out of this state: the consuming `into_ready` transition
/// is the only point at which goal-free types become ABI values.
pub(crate) struct PreparedUserMacroAction<'m> {
    node_id: NodeId,
    name: String,
    macro_def: &'m crate::ast::UserMacroDef<Lowered>,
    macro_module: Option<&'m Module>,
    call_ty: InternedType,
    args: Vec<CallArgRef<'m, Lowered>>,
    stages: &'m [crate::ast::CallStage<Lowered>],
    layout: UserMacroSignatureLayout,
    type_slot_modes: Vec<UserMacroTypeSlotMode>,
    span: Span,
    result_span: Span,
}

pub(crate) enum ProjectedUserMacroSlot {
    Type {
        layer: usize,
        slot: usize,
        result_focus: bool,
        natural_result: bool,
        required_result: bool,
        residual: Option<ProjectedResidualTypeInput>,
    },
    Value {
        layer: usize,
        expanded_start: usize,
        expanded_width: usize,
        implicit_unit: bool,
        residual: Option<ProjectedResidualValueInput>,
    },
}

pub(crate) struct ProjectedResidualTypeInput {
    pub(crate) ty: InternedType,
    pub(crate) lexical_binders: Vec<FrozenResidualTypeBinder>,
}

pub(crate) struct ProjectedResidualValueInput {
    pub(crate) name: String,
    pub(crate) ty: InternedType,
    pub(crate) lexical_binders: Vec<FrozenResidualTypeBinder>,
}

impl ProjectedResidualTypeInput {
    pub(crate) fn lexical_type_params(&self) -> Vec<TypeParam> {
        self.lexical_binders
            .iter()
            .map(|binder| binder.param.clone())
            .collect()
    }

    pub(crate) fn reflection_bindings(
        &self,
    ) -> impl Iterator<Item = (String, crate::normalization::ReflectedVariable)> + '_ {
        self.lexical_binders
            .iter()
            .map(|binder| (binder.param.name.clone(), binder.binding.clone()))
    }
}

impl ProjectedResidualValueInput {
    pub(crate) fn lexical_type_params(&self) -> Vec<TypeParam> {
        self.lexical_binders
            .iter()
            .map(|binder| binder.param.clone())
            .collect()
    }

    pub(crate) fn reflection_bindings(
        &self,
    ) -> impl Iterator<Item = (String, crate::normalization::ReflectedVariable)> + '_ {
        self.lexical_binders
            .iter()
            .map(|binder| (binder.param.name.clone(), binder.binding.clone()))
    }
}

pub(crate) struct ProjectedUserMacroCallShape {
    pub(crate) layers: Vec<ProjectedUserMacroCallLayerShape>,
    pub(crate) observed_types: Vec<InternedType>,
}

pub(crate) struct ProjectedUserMacroCallLayerShape {
    pub(crate) type_slots: Vec<Option<InternedType>>,
    pub(crate) value_layer_consumed: bool,
    pub(crate) expanded_value_slots: usize,
    pub(crate) has_value_sources: bool,
}

#[derive(Clone)]
pub(crate) struct FrozenResidualTypeBinder {
    pub(crate) param: TypeParam,
    pub(crate) binding: crate::normalization::ReflectedVariable,
}

impl FrozenResidualTypeBinder {
    fn new(param: TypeParam) -> Self {
        let binding = crate::normalization::ReflectedVariable::live(
            param.name.clone(),
            param.effective_kind().arity(),
        );
        Self { param, binding }
    }
}

#[derive(Clone)]
pub(crate) struct FrozenProjectedResidualAbi {
    generated_type_params: Vec<Option<FrozenResidualTypeBinder>>,
    bound_value_names: Vec<Option<String>>,
}

impl FrozenProjectedResidualAbi {
    fn has_residual_abstraction(&self) -> bool {
        self.generated_type_params.iter().any(Option::is_some)
            || self.bound_value_names.iter().any(Option::is_some)
    }
}

pub(crate) struct ProjectedUserMacroAbiPlan {
    pub(crate) slots: Vec<ProjectedUserMacroSlot>,
    pub(crate) frozen_residual: FrozenProjectedResidualAbi,
    pub(crate) terminal_result: ProjectedResidualTypeInput,
}

impl<'m> PreparedUserMacroAction<'m> {
    pub(crate) fn node_id(&self) -> NodeId {
        self.node_id
    }

    pub(crate) fn span(&self) -> Span {
        self.span
    }

    pub(crate) fn call_ty(&self) -> &InternedType {
        &self.call_ty
    }

    pub(crate) fn stages(&self) -> &'m [crate::ast::CallStage<Lowered>] {
        self.stages
    }

    pub(crate) fn result_span(&self) -> Span {
        self.result_span
    }

    pub(crate) fn take_output_stages(&mut self) -> &'m [crate::ast::CallStage<Lowered>] {
        let mut consumed = 0;
        for layer in &self.layout.layers {
            for _ in &layer.type_params {
                if self.stages.get(consumed).is_some_and(|stage| {
                    stage.args.iter().all(|arg| matches!(arg, CallArg::Type(_)))
                }) {
                    consumed += 1;
                } else {
                    break;
                }
            }
            if layer.value_param.is_some() {
                if self.stages.get(consumed).is_some_and(|stage| {
                    stage
                        .args
                        .iter()
                        .any(|arg| matches!(arg, CallArg::Value(_)))
                }) {
                    consumed += 1;
                } else {
                    return &[];
                }
            }
        }
        let (inputs, output) = self.stages.split_at(consumed);
        if !output.is_empty() {
            self.result_span = inputs.last().map_or(self.span, |stage| stage.meta.span);
            self.stages = inputs;
            self.args = inputs
                .iter()
                .flat_map(|stage| call_arg_refs(&stage.args))
                .collect();
        }
        output
    }

    pub(crate) fn public_layer_count(&self) -> usize {
        self.layout.layers.len()
    }

    pub(crate) fn schedule(&self) -> crate::ast::MacroSchedule {
        self.macro_def.schedule
    }

    pub(crate) fn terminal_type_only_layer(&self) -> Option<(usize, &[TypeParam])> {
        let terminal = self.layout.layers.last()?;
        if terminal.value_param.is_some() || terminal.type_params.is_empty() {
            return None;
        }
        Some((self.layout.layers.len() - 1, &terminal.type_params))
    }

    pub(crate) fn type_slot_is_natural(&self, layer: usize, slot: usize) -> bool {
        let preceding_slots = self
            .layout
            .layers
            .iter()
            .take(layer)
            .map(|layer| layer.type_params.len())
            .sum::<usize>();
        assert!(
            slot < self.layout.layers[layer].type_params.len(),
            "a macro transcript type slot exceeded its declaration layer"
        );
        matches!(
            self.type_slot_modes[preceding_slots + slot],
            UserMacroTypeSlotMode::NaturalResult
        )
    }

    pub(crate) fn has_natural_result(&self) -> bool {
        self.type_slot_modes
            .contains(&UserMacroTypeSlotMode::NaturalResult)
    }

    pub(crate) fn type_slot_param(&self, layer: usize, slot: usize) -> &TypeParam {
        &self.layout.layers[layer].type_params[slot]
    }

    pub(crate) fn value_layer_forces_unrequested_source(&self, layer: usize) -> bool {
        self.layout.layers[layer].value_abi_arity == 0
    }

    pub(crate) fn projected_abi_plan(
        &self,
        call: &ProjectedUserMacroCallShape,
        tcx: &TypeCtx<'_, '_>,
    ) -> ProjectedUserMacroAbiPlan {
        let mut slots = Vec::with_capacity(self.layout.slots.len());
        let mut substitutions = HashMap::new();
        let mut lexical_binders = Vec::new();
        let mut reserved =
            generated_macro_type_names_projected(&self.layout, &call.observed_types, tcx);
        let type_count = self
            .layout
            .layers
            .iter()
            .map(|layer| layer.type_params.len())
            .sum();
        let value_count = self
            .layout
            .slots
            .iter()
            .filter(|slot| matches!(slot, UserMacroSignatureSlot::Value { .. }))
            .count();
        let mut generated_type_params = Vec::with_capacity(type_count);
        let mut bound_value_names = Vec::with_capacity(value_count);
        let mut value_index = 0usize;
        for (layer_index, layer) in self.layout.layers.iter().enumerate() {
            let call_layer = call.layers.get(layer_index);
            let consumed_type_slots = call_layer.map_or(0, |layer| layer.type_slots.len());
            for (layer_slot, param) in layer.type_params.iter().enumerate() {
                let shadowed = self.layout.layers.iter().enumerate().skip(layer_index).any(
                    |(index, later)| {
                        let later = if index == layer_index {
                            &later.type_params[layer_slot + 1..]
                        } else {
                            &later.type_params
                        };
                        later.iter().any(|later| later.name == param.name)
                    },
                );
                let residual = if layer_slot < consumed_type_slots {
                    let resolved = call_layer
                        .and_then(|layer| layer.type_slots[layer_slot].as_ref())
                        .unwrap_or_else(|| {
                            unreachable!(
                                "a fills projected type slot was absent at action readiness"
                            )
                        });
                    substitutions.insert(param.name.clone(), resolved.clone_type());
                    generated_type_params.push(None);
                    None
                } else {
                    let generated = FrozenResidualTypeBinder::new(generated_macro_type_param(
                        param,
                        &mut reserved,
                    ));
                    let generated_ty = InternedType::fresh_canonical(Type::Path {
                        segments: vec![PathSegment::new(generated.param.name.clone(), self.span)],
                        args: Vec::new(),
                        meta: Meta::new(self.span),
                    });
                    substitutions.insert(param.name.clone(), generated_ty.clone_type());
                    lexical_binders.push(generated.clone());
                    generated_type_params.push(Some(generated));
                    Some(ProjectedResidualTypeInput {
                        ty: generated_ty,
                        lexical_binders: lexical_binders.clone(),
                    })
                };
                let mode = self.type_slot_modes[generated_type_params.len() - 1];
                slots.push(ProjectedUserMacroSlot::Type {
                    layer: layer_index,
                    slot: layer_slot,
                    natural_result: mode == UserMacroTypeSlotMode::NaturalResult,
                    required_result: mode == UserMacroTypeSlotMode::RequiredResult,
                    result_focus: mode != UserMacroTypeSlotMode::NaturalResult
                        && !shadowed
                        && type_mentions_free_param(self.layout.result_ty.as_type(), &param.name),
                    residual,
                });
            }
            let final_value_slot = self.layout.slots.iter().rposition(
                |slot| matches!(slot, UserMacroSignatureSlot::Value { layer, .. } if *layer == layer_index),
            );
            slots.extend(
                self.layout
                    .slots
                    .iter()
                    .enumerate()
                    .filter_map(|(slot_index, slot)| match slot {
                        UserMacroSignatureSlot::Value {
                            ty,
                            layer,
                            expanded_start,
                            expanded_width,
                        } if *layer == layer_index => {
                            let consumed =
                                call_layer.is_some_and(|layer| layer.value_layer_consumed);
                            let (ty, expanded_start, expanded_width) =
                                projected_user_macro_value_slot(
                                    ty,
                                    &substitutions,
                                    *expanded_start,
                                    *expanded_width,
                                    (consumed && Some(slot_index) == final_value_slot).then(|| {
                                        call_layer
                                            .expect("a consumed projected layer has a call shape")
                                            .expanded_value_slots
                                    }),
                                );
                            let implicit_unit = consumed
                                && call_layer.is_some_and(|layer| {
                                    !layer.has_value_sources && layer.expanded_value_slots == 1
                                })
                                && matches!(
                                    crate::pass::typecheck_core::canonicalize_for_comparison(
                                        ty.as_type(),
                                        &tcx.env.alias_ctx(),
                                        ty.identity_is_canonical(),
                                    )
                                    .0,
                                    Type::Unit { .. }
                                );
                            let residual = (!consumed).then(|| {
                                let name =
                                    format!("__ct_macro_value{layer_index}_i{value_index}__");
                                ProjectedResidualValueInput {
                                    name,
                                    ty: ty.clone(),
                                    lexical_binders: lexical_binders.clone(),
                                }
                            });
                            bound_value_names
                                .push(residual.as_ref().map(|residual| residual.name.clone()));
                            value_index += 1;
                            Some(ProjectedUserMacroSlot::Value {
                                layer: *layer,
                                expanded_start,
                                expanded_width,
                                implicit_unit,
                                residual,
                            })
                        }
                        UserMacroSignatureSlot::Type { .. }
                        | UserMacroSignatureSlot::Value { .. } => None,
                    }),
            );
        }
        assert_eq!(slots.len(), self.layout.slots.len());
        assert_eq!(generated_type_params.len(), type_count);
        assert_eq!(bound_value_names.len(), value_count);
        let terminal_result = ProjectedResidualTypeInput {
            ty: InternedType::fresh_with_identity(
                subst_type(self.layout.result_ty.as_type(), &substitutions),
                self.layout.result_ty.identity_is_canonical(),
            ),
            lexical_binders,
        };
        ProjectedUserMacroAbiPlan {
            slots,
            frozen_residual: FrozenProjectedResidualAbi {
                generated_type_params,
                bound_value_names,
            },
            terminal_result,
        }
    }

    /// Whether this private ABI slot may be absent when an already-selected
    /// public call becomes an executable action. This is an action-readiness
    /// fact only; the shared call planner never consults it.
    pub(crate) fn natural_type_slot_can_be_absent(&self, layer: usize, slot: usize) -> bool {
        self.type_slot_is_natural(layer, slot)
    }

    pub(crate) fn into_ready(
        self,
        typed: TypedUserMacroCall,
        tcx: &mut TypeCtx<'m, '_>,
    ) -> Result<ReadyUserMacroAction, Error> {
        let captures =
            resolve_user_macro_captures_for_call(self.macro_def, tcx, self.macro_module)?;
        self.into_ready_with_captures(typed, captures, None, tcx)
    }

    fn into_ready_with_captures(
        self,
        typed: TypedUserMacroCall,
        captures: ResolvedUserMacroCaptures,
        frozen_residual: Option<&FrozenProjectedResidualAbi>,
        tcx: &mut TypeCtx<'m, '_>,
    ) -> Result<ReadyUserMacroAction, Error> {
        let completed = complete_user_macro_abi(
            &self.layout,
            &self.type_slot_modes,
            &typed,
            frozen_residual,
            tcx,
            self.span,
        )?;
        let mut abi_inputs = vec![UserMacroTemplateInput::ComptimeProof];
        abi_inputs.extend(captures.inputs);
        abi_inputs.extend(completed.inputs);
        let mut input_keys = user_macro_input_keys(&abi_inputs);
        if let Some(result_ty) = &typed.result_ty {
            input_keys.push(UserMacroTemplateInputKey::ResidualShape(
                crate::ast::convert_type::<Lowered, UncheckedPrime>(result_ty.as_type()),
            ));
        }
        Ok(ReadyUserMacroAction {
            result_span: self.result_span,
            schedule: self.macro_def.schedule,
            node_id: self.node_id,
            name: self.name,
            macro_module_path: self.macro_module.map(module_path_string),
            values: completed.values,
            abi_inputs,
            input_keys,
            capture_imports: captures.imports,
            value_adapter: completed.value_adapter,
            residual_abstraction: completed.residual_abstraction,
            ambient_type_names: completed.ambient_type_names,
            residual_reflection_bindings: completed.residual_reflection_bindings,
            terminal_result_ty: completed.terminal_result_ty,
            span: self.span,
        })
    }

    pub(crate) fn into_projected_ready(
        self,
        declared_inputs: Vec<crate::normalization::Value>,
        frozen_residual: FrozenProjectedResidualAbi,
        proof: crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
        fills: crate::pass::typecheck_core::apply::fills::FillContext,
        tcx: &mut TypeCtx<'m, '_>,
    ) -> Result<ReadyProjectedUserMacroAction<'m>, Error> {
        assert_eq!(self.macro_def.schedule, crate::ast::MacroSchedule::Fills);
        assert!(fills.matches_proof(&proof));
        assert_eq!(declared_inputs.len(), self.layout.slots.len());
        let mut modes = self.type_slot_modes.iter();
        for (slot, value) in self.layout.slots.iter().zip(&declared_inputs) {
            match slot {
                UserMacroSignatureSlot::Type { .. } => {
                    if *modes.next().expect("every type slot has a mode")
                        == UserMacroTypeSlotMode::NaturalResult
                    {
                        assert!(matches!(value, crate::normalization::Value::Unit));
                        continue;
                    }
                    let projected = crate::normalization::projected_value_from_value(value)
                        .expect("a projected macro type slot retained an ordinary value");
                    assert!(projected.is_type() && projected.matches_proof(&proof));
                }
                UserMacroSignatureSlot::Value { .. } => match value {
                    crate::normalization::Value::CheckedTerm(_) => {}
                    crate::normalization::Value::Projected(projected) => {
                        assert!(!projected.is_type() && projected.matches_proof(&proof));
                    }
                    _ => unreachable!("a projected macro value slot changed handle class"),
                },
            }
        }
        let captures =
            resolve_user_macro_captures_for_call(self.macro_def, tcx, self.macro_module)?;
        Ok(ReadyProjectedUserMacroAction {
            action: self,
            captures,
            declared_inputs,
            frozen_residual,
            proof,
            fills,
        })
    }
}

pub(crate) struct ReadyProjectedUserMacroAction<'m> {
    action: PreparedUserMacroAction<'m>,
    captures: ResolvedUserMacroCaptures,
    declared_inputs: Vec<crate::normalization::Value>,
    frozen_residual: FrozenProjectedResidualAbi,
    proof: crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    fills: crate::pass::typecheck_core::apply::fills::FillContext,
}

impl ReadyProjectedUserMacroAction<'_> {
    pub(crate) fn result_span(&self) -> Span {
        self.action.result_span()
    }

    /// Exact declaration-order binders shared by residual input scopes and the
    /// eventual eta plan; recipe closure must not reconstruct them from names.
    pub(crate) fn residual_type_binders(&self) -> impl Iterator<Item = &FrozenResidualTypeBinder> {
        self.frozen_residual.generated_type_params.iter().flatten()
    }

    pub(crate) fn residual_reflection_bindings(
        &self,
    ) -> impl Iterator<Item = (String, crate::normalization::ReflectedVariable)> + '_ {
        self.frozen_residual
            .generated_type_params
            .iter()
            .flatten()
            .map(|binder| (binder.param.name.clone(), binder.binding.clone()))
    }

    /// Whether materialization would wrap the evaluator recipe in a callable
    /// layer. A lifted recursive callback cannot cross that escaping boundary.
    pub(crate) fn has_residual_abstraction(&self) -> bool {
        self.frozen_residual.has_residual_abstraction()
    }

    pub(crate) fn eval_packet(&self) -> crate::normalization::Value {
        let (proof, fills) =
            crate::normalization::fills_capability_values(self.proof.clone(), self.fills.clone());
        let mut values =
            Vec::with_capacity(2 + self.captures.inputs.len() + self.declared_inputs.len());
        values.push(proof);
        values.push(fills);
        values.extend(
            self.captures
                .inputs
                .iter()
                .map(user_macro_template_input_value),
        );
        values.extend(self.declared_inputs.iter().cloned());
        crate::normalization::right_fold_product_values(values)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UserMacroTypeSlotMode {
    Input,
    RequiredResult,
    NaturalResult,
}

#[derive(Clone, Debug)]
enum UserMacroTemplateInput {
    ComptimeProof,
    Type(ReflectableType),
    NaturalResult,
    Term {
        value_index: usize,
        value_ty: ReflectableType,
    },
    BoundTerm {
        name: String,
        value_ty: ReflectableType,
    },
    CapturedTerm {
        term: crate::normalization::EvalRef<crate::normalization::CheckedTerm>,
    },
}

#[derive(Clone, Debug)]
enum UserMacroTemplateInputKey {
    ComptimeProof,
    Type(ReflectableType),
    NaturalResult,
    Term(ReflectableType),
    ResidualShape(crate::ast::Type<UncheckedPrime>),
    CapturedTerm(crate::normalization::EvalRef<crate::normalization::CheckedTerm>),
}

#[derive(Clone)]
struct ResolvedUserMacroCaptures {
    inputs: Vec<UserMacroTemplateInput>,
    imports: Vec<UserMacroTemplateGeneratedImport>,
}

impl ResolvedUserMacroCaptures {
    fn empty() -> Self {
        Self {
            inputs: Vec::new(),
            imports: Vec::new(),
        }
    }
}

struct ResolvedCaptureTermPath {
    /// The exact owner of the declaration named by the written path. This is
    /// distinct from `owner_module_path` for an identity alias: lexical order
    /// and alias visibility belong to the source alias, while replay targets
    /// the terminal newtype member.
    source_owner_module_path: Option<String>,
    /// The exact owner used when replaying the captured term.
    owner_module_path: Option<String>,
    visibility_edges: Vec<ResolvedCaptureVisibilityEdge>,
    replay_tail: Vec<String>,
}

#[derive(Debug, PartialEq, Eq)]
struct ResolvedCaptureVisibilityEdge {
    owner_module_path: Option<String>,
    visibility: crate::ast::Visibility,
    target: String,
}

fn user_macro_signature_layout(
    call_ty: &InternedType,
    alias_ctx: &AliasCtx<'_, '_>,
) -> UserMacroSignatureLayout {
    let mut slots = Vec::new();
    let mut layers = Vec::new();
    let mut cur = call_ty.clone();
    let mut bound = alias_ctx.binder_local_names();
    loop {
        let layer = layers.len();
        let mut type_params = Vec::new();
        loop {
            let scoped_aliases = AliasCtx {
                binder_locals: Some(&bound),
                ..*alias_ctx
            };
            let (head, canonical) = crate::pass::typecheck_core::canonicalize_for_comparison(
                cur.as_type(),
                &scoped_aliases,
                cur.identity_is_canonical(),
            );
            cur = InternedType::fresh_with_identity(head, canonical);
            let Type::Forall { param, body, .. } = cur.clone_type() else {
                break;
            };
            slots.push(UserMacroSignatureSlot::Type {
                param: param.clone(),
            });
            bound.insert(param.name.clone());
            type_params.push(param);
            cur = InternedType::fresh_with_identity(*body, cur.identity_is_canonical());
        }
        let identity_canonical = cur.identity_is_canonical();
        let Type::Function {
            param,
            ret,
            abi_arity,
            ..
        } = cur.clone_type()
        else {
            if !type_params.is_empty() {
                layers.push(UserMacroSignatureLayer {
                    type_params,
                    value_param: None,
                    value_abi_arity: 0,
                });
            }
            return UserMacroSignatureLayout {
                slots,
                layers,
                result_ty: cur,
            };
        };
        let value_param = InternedType::fresh_with_identity(*param, identity_canonical);
        let expanded_value_slots = user_macro_expanded_value_slot_count(&value_param, alias_ctx);
        let mut expanded_start = 0usize;
        for ty in user_macro_value_slot_types(&value_param, abi_arity) {
            let expanded_width = user_macro_expanded_value_slot_count(&ty, alias_ctx).max(1);
            slots.push(UserMacroSignatureSlot::Value {
                ty,
                layer,
                expanded_start,
                expanded_width,
            });
            expanded_start += expanded_width;
        }
        debug_assert!(
            abi_arity == 0 || expanded_start == expanded_value_slots,
            "the macro ABI view must cover the semantic value packet"
        );
        layers.push(UserMacroSignatureLayer {
            type_params,
            value_param: Some(value_param),
            value_abi_arity: abi_arity,
        });
        cur = InternedType::fresh_with_identity(*ret, identity_canonical);
    }
}

#[derive(Debug)]
pub(crate) struct TrailingProjectionCheck {
    has_final_prefix: bool,
    blocks: Vec<(crate::ast::BlockExposure, Error)>,
    binders: HashSet<String>,
}

impl TrailingProjectionCheck {
    pub(crate) fn validate(
        self,
        expected: InternedType,
        tcx: &TypeCtx<'_, '_>,
    ) -> Result<(), Error> {
        let aliases = tcx.binder_alias_ctx(&self.binders);
        let (packet_ty, identity_canonical) =
            crate::pass::typecheck_core::canonicalize_deep_for_comparison(
                expected.as_type(),
                &aliases,
                expected.identity_is_canonical(),
            );
        let mut remaining = &packet_ty;
        if self.has_final_prefix {
            let Type::Product { right, .. } = remaining else {
                unreachable!("ordinary checking validates the prefix-and-block product")
            };
            remaining = right;
        }
        // These paths come from projection syntax. The final block retains its
        // whole type, including any product belonging to the block itself.
        let block_count = self.blocks.len();
        for (index, (exposure, error)) in self.blocks.into_iter().enumerate() {
            let block_ty = if index + 1 == block_count {
                remaining
            } else {
                let Type::Product { left, right, .. } = remaining else {
                    unreachable!("ordinary checking validates the projected block product")
                };
                remaining = right;
                left
            };
            let valid = match exposure {
                crate::ast::BlockExposure::Product => true,
                crate::ast::BlockExposure::Thunk => {
                    matches!(block_ty, Type::Function { param, .. } if matches!(param.as_ref(), Type::Unit { .. }))
                }
                crate::ast::BlockExposure::Sequence => sequence_slot_type(
                    &InternedType::fresh_with_identity(block_ty.clone(), identity_canonical),
                    &aliases,
                ),
            };
            if !valid {
                return Err(error);
            }
        }
        Ok(())
    }
}

pub(crate) fn trailing_projection_check(
    original: &Expr,
    candidate: &Expr,
    tcx: &TypeCtx<'_, '_>,
) -> Result<Option<TrailingProjectionCheck>, Error> {
    let Expr::UserMacro {
        name,
        stages,
        form: crate::ast::UserMacroCallForm::TrailingBlocks { has_final_prefix },
        ..
    } = original
    else {
        return Ok(None);
    };
    let [CallArg::Value(packet)] = stages
        .last()
        .expect("block projection creates a final value stage")
        .args
        .as_slice()
    else {
        unreachable!("block projection packs its final stage as one value")
    };
    if packet.site().id != candidate.site().id {
        return Ok(None);
    }
    let (macro_def, macro_module) = resolve_user_macro_for_call(name, original.span(), tcx)?;
    if macro_def
        .trailing_blocks
        .iter()
        .all(|block| block.exposure == crate::ast::BlockExposure::Product)
    {
        return Ok(None);
    }
    let blocks = macro_def
        .trailing_blocks
        .iter()
        .map(|descriptor| {
            let message = match descriptor.exposure {
                crate::ast::BlockExposure::Thunk => {
                    "a thunk block requires an ordinary `. -> R` value slot"
                }
                crate::ast::BlockExposure::Sequence => {
                    "a sequence block requires an ordinary `Bind[F] -> F[R]` value slot"
                }
                crate::ast::BlockExposure::Product => {
                    "a product block requires an ordinary value slot"
                }
            };
            (
                descriptor.exposure,
                trailing_block_declaration_error(
                    packet.span(),
                    message,
                    macro_def,
                    macro_module,
                    tcx,
                ),
            )
        })
        .collect();
    Ok(Some(TrailingProjectionCheck {
        has_final_prefix: *has_final_prefix,
        blocks,
        binders: tcx.in_scope_type_param_binders(),
    }))
}

fn trailing_block_declaration_error(
    span: Span,
    message: &str,
    macro_def: &crate::ast::UserMacroDef<Lowered>,
    module: Option<&Module>,
    tcx: &TypeCtx<'_, '_>,
) -> Error {
    let error = Error::type_(span, message);
    match module {
        Some(module) if !std::ptr::eq(module, tcx.env.module) => {
            let entry = tcx
                .env
                .package
                .and_then(|package| package.module(&module_path_string(module)))
                .expect("a resolved imported macro has a package module entry");
            error.with_secondary_in_file(
                entry.file_path.clone(),
                macro_def.name_span,
                "trailing blocks declared here",
            )
        }
        _ => error.with_secondary(macro_def.name_span, "trailing blocks declared here"),
    }
}

fn sequence_slot_type(ty: &InternedType, aliases: &AliasCtx<'_, '_>) -> bool {
    let (ty, _) = crate::pass::typecheck_core::canonicalize_deep_for_comparison(
        ty.as_type(),
        aliases,
        ty.identity_is_canonical(),
    );
    let Type::Function {
        param: bind,
        ret: result,
        ..
    } = ty
    else {
        return false;
    };
    let Type::Forall { param: a, body, .. } = *bind else {
        return false;
    };
    let Type::Forall { param: b, body, .. } = *body else {
        return false;
    };
    if a.effective_kind() != crate::ast::Kind::Star
        || b.effective_kind() != crate::ast::Kind::Star
        || a.name == b.name
    {
        return false;
    }
    let Type::Function { param, ret, .. } = *body else {
        return false;
    };
    let Type::Product {
        left: fa,
        right: continuation,
        ..
    } = *param
    else {
        return false;
    };
    let Type::Function {
        param: input,
        ret: fb,
        ..
    } = *continuation
    else {
        return false;
    };
    if type_mentions_free_param(&fa, &b.name) {
        return false;
    }
    let mut bound = aliases.binder_local_names();
    bound.insert(a.name.clone());
    bound.insert(b.name.clone());
    let aliases = AliasCtx {
        binder_locals: Some(&bound),
        ..*aliases
    };
    let a_ty = Type::synth_path(vec![a.name.clone()], Vec::new(), a.span);
    let b_ty = Type::synth_path(vec![b.name.clone()], Vec::new(), b.span);
    let expected_fb = subst_type(&fa, &HashMap::from([(a.name.clone(), b_ty)]));
    let same = |left: &Type, right: &Type| {
        crate::pass::typecheck_core::require_type_equiv_state(
            left, right, a.span, &aliases, true, true,
        )
        .is_ok()
    };
    if !same(&input, &a_ty) || !same(&fb, &expected_fb) || !same(&ret, &expected_fb) {
        return false;
    }
    // Reuse ordinary closed-type matching to establish the same carrier at R;
    // no equation is added to the caller's inference domain by this validation.
    crate::pass::typecheck_core::unify_pattern_with_holes_state(
        &fa,
        &result,
        &HashSet::from([a.name]),
        &HashSet::new(),
        &mut HashMap::new(),
        a.span,
        &aliases,
        true,
        true,
    )
    .is_ok()
}

fn user_macro_value_slot_types(param: &InternedType, abi_arity: usize) -> Vec<InternedType> {
    Type::right_spine_take(param.as_type(), abi_arity)
        .into_iter()
        .map(|ty| InternedType::fresh_with_identity(ty.clone(), param.identity_is_canonical()))
        .collect()
}

fn user_macro_expanded_value_slot_count(
    param: &InternedType,
    alias_ctx: &AliasCtx<'_, '_>,
) -> usize {
    let mut count = 0usize;
    let mut current = param.clone();
    loop {
        let (unfolded, identity_canonical) =
            crate::pass::typecheck_core::canonicalize_for_comparison(
                current.as_type(),
                alias_ctx,
                current.identity_is_canonical(),
            );
        match unfolded {
            Type::Product { right, .. } => {
                count += 1;
                current = InternedType::fresh_with_identity(*right, identity_canonical);
            }
            // Unit is one explicit semantic packet even though the stable host
            // ABI has arity zero for it.
            Type::Unit { .. } => return count + 1,
            _ => return count + 1,
        }
    }
}

fn projected_user_macro_value_slot(
    ty: &InternedType,
    substitutions: &HashMap<String, Type>,
    expanded_start: usize,
    declared_expanded_width: usize,
    frozen_layer_width: Option<usize>,
) -> (InternedType, usize, usize) {
    let ty = InternedType::fresh_with_identity(
        subst_type(ty.as_type(), substitutions),
        ty.identity_is_canonical(),
    );
    // The public call freezes semantic source coordinates when its layer opens.
    // A later-solved type argument may expose a wider product, but the final
    // private ABI slot owns the already-selected remaining spine.
    let expanded_width = frozen_layer_width.map_or(declared_expanded_width, |layer_width| {
        layer_width
            .checked_sub(expanded_start)
            .filter(|width| *width != 0)
            .expect("a projected macro value slot exceeded its frozen call layer")
    });
    (ty, expanded_start, expanded_width)
}

struct CompletedUserMacroAbi {
    inputs: Vec<UserMacroTemplateInput>,
    values: Vec<Expr>,
    value_adapter: crate::normalization::CheckedTermTemplateValueAdapter,
    residual_abstraction: crate::pass::substitute::EtaPlan<UncheckedPrime>,
    /// Enclosing source binders complete the replay allocator's namespace but
    /// do not affect the reusable macro template or its memo key.
    ambient_type_names: HashSet<String>,
    residual_reflection_bindings: Vec<(String, crate::normalization::ReflectedVariable)>,
    terminal_result_ty: Option<InternedType>,
}

fn typed_source_slot_types(
    source: &TypedUserMacroCallSource,
    tcx: &TypeCtx<'_, '_>,
) -> Vec<InternedType> {
    if source.expanded_width == 1 {
        return vec![source.expected.clone()];
    }
    let (unfolded, identity_canonical) = crate::pass::typecheck_core::canonicalize_for_comparison(
        source.expected.as_type(),
        &tcx.env.alias_ctx(),
        source.expected.identity_is_canonical(),
    );
    let slots = Type::right_spine_take(&unfolded, source.expanded_width);
    assert_eq!(
        slots.len(),
        source.expanded_width,
        "a typed source width must match its expected product spine"
    );
    slots
        .into_iter()
        .map(|ty| InternedType::fresh_with_identity(ty.clone(), identity_canonical))
        .collect()
}

fn reserve_module_nominal_type_names(module: &Module, reserved: &mut HashSet<String>) {
    for item in &module.items {
        crate::pass::resolve::for_each_item_declaration(item, |declaration| {
            let name = declaration
                .type_alias()
                .map(|alias| alias.name.as_str())
                .or_else(|| declaration.newtype().map(|newtype| newtype.name.as_str()))
                .or_else(|| declaration.host_type().map(|host| host.name.as_str()));
            if let Some(name) = name {
                reserved.insert(name.to_owned());
            }
        });
    }
}

fn generated_macro_scope_type_names(tcx: &TypeCtx<'_, '_>) -> HashSet<String> {
    let mut reserved = tcx.in_scope_type_param_binders();
    reserve_module_nominal_type_names(tcx.env.module, &mut reserved);
    for usage in &tcx.env.module.imports {
        if let ImportKind::Selective { items, .. } = &usage.kind {
            reserved.extend(
                items
                    .iter()
                    .filter_map(crate::ast::ImportItem::as_local_name)
                    .filter(|name| crate::naming::is_type_name(name))
                    .map(str::to_owned),
            );
        }
    }
    reserved
}

fn generated_macro_type_names(
    layout: &UserMacroSignatureLayout,
    typed: &TypedUserMacroCall,
    tcx: &TypeCtx<'_, '_>,
) -> HashSet<String> {
    let mut reserved = generated_macro_scope_type_names(tcx);

    collect_free_type_vars(layout.result_ty.as_type(), &mut reserved);
    for layer in &layout.layers {
        for param in &layer.type_params {
            reserved.insert(param.name.clone());
        }
        if let Some(value_param) = &layer.value_param {
            collect_free_type_vars(value_param.as_type(), &mut reserved);
        }
    }
    for layer in &typed.layers {
        for slot in &layer.type_slots {
            if let Some(resolved) = &slot.resolved {
                collect_free_type_vars(resolved.as_type(), &mut reserved);
            }
            if let Some(occurrence) = &slot.occurrence {
                collect_free_type_vars(occurrence.as_type(), &mut reserved);
            }
        }
        for source in &layer.sources {
            collect_free_type_vars(source.expected.as_type(), &mut reserved);
        }
    }
    if let Some(result_ty) = &typed.result_ty {
        collect_free_type_vars(result_ty.as_type(), &mut reserved);
    }
    reserved
}

fn generated_macro_type_names_projected(
    layout: &UserMacroSignatureLayout,
    observed_types: &[InternedType],
    tcx: &TypeCtx<'_, '_>,
) -> HashSet<String> {
    let mut reserved = generated_macro_scope_type_names(tcx);
    collect_free_type_vars(layout.result_ty.as_type(), &mut reserved);
    for layer in &layout.layers {
        for param in &layer.type_params {
            reserved.insert(param.name.clone());
        }
        if let Some(value_param) = &layer.value_param {
            collect_free_type_vars(value_param.as_type(), &mut reserved);
        }
    }
    for ty in observed_types {
        collect_free_type_vars(ty.as_type(), &mut reserved);
    }
    reserved
}

fn generated_macro_type_param(original: &TypeParam, reserved: &mut HashSet<String>) -> TypeParam {
    // Declaration binders are reserved before allocation, so the generated
    // name always differs from the source binder while retaining its legal
    // TypeParam spelling and exact kind.
    let name = fresh_type_var(&original.name, reserved);
    assert!(
        reserved.insert(name.clone()),
        "a generated macro type binder must be fresh"
    );
    original.renamed(name)
}

fn type_mentions_free_param(ty: &Type, name: &str) -> bool {
    let mut free = HashSet::new();
    collect_free_type_vars(ty, &mut free);
    free.contains(name)
}

fn type_slot_occurs_only_in_result(
    layout: &UserMacroSignatureLayout,
    layer_index: usize,
    layer_slot: usize,
    aliases: &AliasCtx<'_, '_>,
) -> bool {
    // A later same-spelled binder shadows this one, so any result occurrence
    // after that boundary belongs to the later binder rather than this slot.
    let name = &layout.layers[layer_index].type_params[layer_slot].name;
    for (index, layer) in layout.layers.iter().enumerate().skip(layer_index) {
        let later_params = if index == layer_index {
            &layer.type_params[layer_slot + 1..]
        } else {
            &layer.type_params[..]
        };
        if later_params.iter().any(|param| param.name == *name) {
            return false;
        }
        if layer.value_param.as_ref().is_some_and(|value| {
            let mut binders = aliases.binder_local_names();
            for prior in &layout.layers[..=index] {
                binders.extend(prior.type_params.iter().map(|param| param.name.clone()));
            }
            let aliases = AliasCtx {
                binder_locals: Some(&binders),
                ..*aliases
            };
            let semantic = crate::pass::typecheck_core::materialize_aliases_in_scope(
                value.as_type(),
                aliases.source_module,
                aliases.package,
                Some(&binders),
                value.identity_is_canonical(),
            );
            type_mentions_free_param(&semantic, name)
        }) {
            return false;
        }
    }
    let mut binders = aliases.binder_local_names();
    binders.extend(
        layout
            .layers
            .iter()
            .flat_map(|layer| layer.type_params.iter().map(|param| param.name.clone())),
    );
    let aliases = AliasCtx {
        binder_locals: Some(&binders),
        ..*aliases
    };
    let result = crate::pass::typecheck_core::materialize_aliases_in_scope(
        layout.result_ty.as_type(),
        aliases.source_module,
        aliases.package,
        Some(&binders),
        layout.result_ty.identity_is_canonical(),
    );
    type_mentions_free_param(&result, name)
}

#[allow(clippy::too_many_arguments)]
fn complete_user_macro_abi(
    layout: &UserMacroSignatureLayout,
    type_slot_modes: &[UserMacroTypeSlotMode],
    typed: &TypedUserMacroCall,
    frozen_residual: Option<&FrozenProjectedResidualAbi>,
    tcx: &TypeCtx<'_, '_>,
    span: Span,
) -> Result<CompletedUserMacroAbi, Error> {
    assert!(
        typed.layers.len() <= layout.layers.len(),
        "the shared call transcript exceeded the macro declaration"
    );
    let source_count = typed
        .layers
        .iter()
        .flat_map(|layer| layer.sources.iter().map(|source| source.source_index + 1))
        .max()
        .unwrap_or(0);
    let mut adapter_sources = vec![None; source_count];
    let mut values = vec![None; source_count];
    for (layer_index, layer) in typed.layers.iter().enumerate() {
        for source in &layer.sources {
            let reflected = reflect_macro_interned_type(&source.expected, tcx)?;
            let replacement = crate::normalization::CheckedTermTemplateSource {
                ty: reflected,
                force_if_unused: layout.layers[layer_index].value_abi_arity == 0,
            };
            assert!(
                adapter_sources[source.source_index]
                    .replace(replacement)
                    .is_none(),
                "one source expression appeared twice in the call transcript"
            );
            assert!(
                values[source.source_index]
                    .replace(source.source.clone())
                    .is_none(),
                "one source expression appeared twice in the call transcript"
            );
        }
    }
    let mut adapter_sources = adapter_sources
        .into_iter()
        .map(|source| source.expect("source indices in a call transcript are contiguous"))
        .collect::<Vec<_>>();
    let mut values = values
        .into_iter()
        .map(|source| source.expect("source indices in a call transcript are contiguous"))
        .collect::<Vec<_>>();

    let mut substitutions = HashMap::new();
    let mut inputs = Vec::new();
    let mut adapter_slots = Vec::new();
    let mut residual_layers = Vec::new();
    let mut residual_prefix_type_params = Vec::new();
    let mut residual_reflection_binders = Vec::new();
    let mut generated_type_names = generated_macro_type_names(layout, typed, tcx);
    let mut type_mode_index = 0usize;
    let mut abi_value_index = 0usize;

    for (layer_index, layer) in layout.layers.iter().enumerate() {
        let typed_layer = typed.layers.get(layer_index);
        let consumed_type_slots = typed_layer.map_or(0, |layer| layer.type_slots.len());
        assert!(
            consumed_type_slots <= layer.type_params.len(),
            "the call transcript consumed too many declaration type slots"
        );
        let value_layer_consumed = typed_layer.is_some_and(|layer| layer.value_layer_consumed);
        let mut residual_type_params = Vec::new();

        for (layer_slot, param) in layer.type_params.iter().enumerate() {
            let frozen_type_index = type_mode_index;
            let mode = type_slot_modes[type_mode_index];
            type_mode_index += 1;
            let resolved = if layer_slot < consumed_type_slots {
                let slot = &typed_layer
                    .expect("a consumed type slot has a transcript layer")
                    .type_slots[layer_slot];
                match slot.resolved.clone() {
                    Some(resolved) => {
                        substitutions.insert(
                            param.name.clone(),
                            slot.occurrence.as_ref().unwrap_or(&resolved).clone_type(),
                        );
                        resolved
                    }
                    None => {
                        if !matches!(mode, UserMacroTypeSlotMode::NaturalResult) {
                            return Err(Error::type_(
                                span,
                                format!(
                                    "cannot infer type argument `[{}]` of this macro call",
                                    param.name
                                ),
                            ));
                        }
                        if let Some(occurrence) = &slot.occurrence {
                            substitutions.insert(param.name.clone(), occurrence.clone_type());
                        }
                        inputs.push(UserMacroTemplateInput::NaturalResult);
                        continue;
                    }
                }
            } else {
                let generated = frozen_residual
                    .and_then(|frozen| frozen.generated_type_params[frozen_type_index].as_ref())
                    .cloned()
                    .unwrap_or_else(|| {
                        FrozenResidualTypeBinder::new(generated_macro_type_param(
                            param,
                            &mut generated_type_names,
                        ))
                    });
                let generated_ty = Type::Path {
                    segments: vec![PathSegment::new(generated.param.name.clone(), span)],
                    args: Vec::new(),
                    meta: Meta::new(span),
                };
                residual_type_params.push(generated.param.clone());
                residual_reflection_binders.push(generated);
                InternedType::fresh_canonical(generated_ty)
            };
            substitutions
                .entry(param.name.clone())
                .or_insert_with(|| resolved.clone_type());
            if mode == UserMacroTypeSlotMode::NaturalResult {
                inputs.push(UserMacroTemplateInput::NaturalResult);
            } else {
                let reflected = reflect_macro_interned_type_with_binders(
                    &resolved,
                    tcx,
                    &residual_reflection_binders,
                )?;
                inputs.push(UserMacroTemplateInput::Type(reflected));
            }
        }

        let source_slots = typed_layer
            .map(|typed_layer| {
                typed_layer
                    .sources
                    .iter()
                    .map(|source| (source, typed_source_slot_types(source, tcx)))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let mut residual_values = Vec::new();
        for slot in layout.slots.iter().filter(|slot| {
            matches!(slot, UserMacroSignatureSlot::Value { layer, .. } if *layer == layer_index)
        }) {
            let UserMacroSignatureSlot::Value {
                ty,
                expanded_start,
                expanded_width,
                ..
            } = slot
            else {
                unreachable!()
            };
            let resolved = InternedType::fresh_with_identity(
                subst_type(ty.as_type(), &substitutions),
                ty.identity_is_canonical(),
            );
            let reflected = reflect_macro_interned_type_with_binders(
                &resolved,
                tcx,
                &residual_reflection_binders,
            )?;
            if value_layer_consumed {
                let mut pieces = Vec::with_capacity(*expanded_width);
                for expanded_slot in *expanded_start..(*expanded_start + *expanded_width) {
                    let source_piece = source_slots
                        .iter()
                        .find(|(source, _)| {
                            expanded_slot >= source.expanded_start
                                && expanded_slot < source.expanded_start + source.expanded_width
                        });
                    if let Some((source, slot_tys)) = source_piece {
                        pieces.push(crate::normalization::CheckedTermTemplatePiece {
                            source_index: source.source_index,
                            source_slot: expanded_slot - source.expanded_start,
                            source_slot_tys: slot_tys
                                .iter()
                                .map(|ty| reflect_macro_interned_type(ty, tcx))
                                .collect::<Result<_, _>>()?,
                        });
                        continue;
                    }

                    let (unfolded, _) =
                        crate::pass::typecheck_core::canonicalize_for_comparison(
                            resolved.as_type(),
                            &tcx.env.alias_ctx(),
                            resolved.identity_is_canonical(),
                        );
                    assert!(
                        source_slots.is_empty()
                            && *expanded_width == 1
                            && matches!(unfolded, Type::Unit { .. }),
                        "only a source-empty implicit Unit may omit a macro source"
                    );
                    let source_index = values.len();
                    let source_ty = reflected.clone();
                    values.push(Expr::Unit {
                        source_trivia: Default::default(), occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
                        meta: Meta::new(span),
                    });
                    adapter_sources.push(crate::normalization::CheckedTermTemplateSource {
                        ty: source_ty.clone(),
                        force_if_unused: false,
                    });
                    pieces.push(crate::normalization::CheckedTermTemplatePiece {
                        source_index,
                        source_slot: 0,
                        source_slot_tys: vec![source_ty],
                    });
                }
                inputs.push(UserMacroTemplateInput::Term {
                    value_index: abi_value_index,
                    value_ty: reflected,
                });
                adapter_slots.push(crate::normalization::CheckedTermTemplateSlot { pieces });
            } else {
                let name = frozen_residual
                    .and_then(|frozen| frozen.bound_value_names[abi_value_index].as_ref())
                    .cloned()
                    .unwrap_or_else(|| {
                        format!("__ct_macro_value{layer_index}_i{abi_value_index}__")
                    });
                inputs.push(UserMacroTemplateInput::BoundTerm {
                    name: name.clone(),
                    value_ty: reflected.clone(),
                });
                residual_values.push(crate::pass::substitute::EtaValueParam {
                    name,
                    ty: reflected.as_type().clone(),
                });
            }
            abi_value_index += 1;
        }

        if !value_layer_consumed {
            if layer.value_param.is_some() {
                let mut type_params = std::mem::take(&mut residual_prefix_type_params);
                type_params.extend(residual_type_params);
                residual_layers.push(crate::pass::substitute::EtaLayer {
                    type_params,
                    value_params: residual_values,
                    has_value_layer: true,
                });
            } else {
                residual_prefix_type_params.extend(residual_type_params);
            }
        } else {
            assert!(
                residual_type_params.is_empty(),
                "a consumed value layer cannot retain declaration binders"
            );
        }
    }
    if !residual_prefix_type_params.is_empty() {
        residual_layers.push(crate::pass::substitute::EtaLayer {
            type_params: residual_prefix_type_params,
            value_params: Vec::new(),
            has_value_layer: false,
        });
    }
    assert_eq!(
        type_mode_index,
        type_slot_modes.len(),
        "the macro type-mode ABI drifted from its callable layout"
    );
    let terminal_result_ty = if residual_layers.is_empty() {
        typed.result_ty.clone()
    } else {
        // Ordinary typing observes the residual callable scheme, while the
        // evaluator produces only the body placed beneath the EtaPlan. Keep
        // its coherence target at that terminal boundary.
        Some(InternedType::fresh_with_identity(
            subst_type(layout.result_ty.as_type(), &substitutions),
            layout.result_ty.identity_is_canonical(),
        ))
    };
    Ok(CompletedUserMacroAbi {
        inputs,
        values,
        value_adapter: crate::normalization::CheckedTermTemplateValueAdapter {
            sources: adapter_sources,
            slots: adapter_slots,
        },
        residual_abstraction: crate::pass::substitute::EtaPlan {
            layers: residual_layers,
        },
        ambient_type_names: tcx.in_scope_type_param_binders(),
        residual_reflection_bindings: residual_reflection_binders
            .into_iter()
            .map(|binder| (binder.param.name, binder.binding))
            .collect(),
        terminal_result_ty,
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum UserMacroCaptureSpelling {
    Type,
    Value,
    Member,
}

fn classify_user_macro_capture(
    capture: &crate::ast::UserMacroCapture,
) -> Result<UserMacroCaptureSpelling, Error> {
    let Some(first) = capture.segments.first() else {
        return Err(Error::type_(capture.span, "empty macro capture"));
    };
    let Some(last) = capture.segments.last() else {
        return Err(Error::type_(capture.span, "empty macro capture"));
    };
    if capture.segments.len() == 1 && crate::naming::is_type_name(first.as_str()) {
        return Ok(UserMacroCaptureSpelling::Type);
    }
    if capture.segments.len() == 1 && crate::naming::is_value_name(first.as_str()) {
        return Ok(UserMacroCaptureSpelling::Value);
    }
    if capture.segments.len() > 1 && crate::naming::is_value_name(last.as_str()) {
        return Ok(UserMacroCaptureSpelling::Member);
    }
    Err(Error::type_(
        capture.span,
        "macro captures must be a type name, a value name, or a dotted path ending in a \
         value member name",
    ))
}

fn capture_path_segments(names: impl IntoIterator<Item = String>, span: Span) -> Vec<PathSegment> {
    names
        .into_iter()
        .map(|name| PathSegment::new(name, span))
        .collect()
}

fn type_from_capture_path(names: impl IntoIterator<Item = String>, span: Span) -> Type {
    crate::ast::Type::synth_path(names.into_iter().collect(), Vec::new(), span)
}

fn expr_from_capture_path(names: impl IntoIterator<Item = String>, span: Span) -> Expr {
    Expr::Path {
        occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
        segments: capture_path_segments(names, span),
        meta: Meta::new(span),
        ext: (),
    }
}

fn module_path_for_capture_owner<'m>(
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> String {
    env.module_path.clone()
}

#[cfg(all(test, feature = "surface"))]
fn reset_capture_type_owner_item_visits() {
    crate::pass::resolve::reset_nominal_provider_work();
}

#[cfg(all(test, feature = "surface"))]
fn capture_type_owner_item_visits() -> usize {
    crate::pass::resolve::nominal_provider_work().declaration_items_indexed
}

fn find_fn_owner<'m>(
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    f: &'m crate::ast::FnDef<Lowered>,
) -> Option<String> {
    if let Some(package) = env.package {
        for (path, entry) in package.modules() {
            for item in &entry.module.items {
                if let crate::ast::Item::FnDef(candidate) = item
                    && std::ptr::eq(candidate, f)
                {
                    return Some((*path).to_owned());
                }
            }
        }
    }
    if env
        .fn_defs
        .get(f.name.as_str())
        .is_some_and(|candidate| std::ptr::eq(*candidate, f))
    {
        return Some(module_path_for_capture_owner(env));
    }
    None
}

fn env_owner<'m>(env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>) -> String {
    env.module_path
        .split('/')
        .next()
        .filter(|root| !root.is_empty())
        .unwrap_or(env.module_path.as_str())
        .to_owned()
}

fn resolve_capture_type_owner_with_provider<'m>(
    capture: &crate::ast::UserMacroCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    provider: &NominalProvider<'m, Lowered>,
) -> Result<(String, crate::ast::Visibility), Error> {
    let name = capture.segments[0].as_str();
    if let Some(owner) = resolve_type_name_owner_with_provider(name, env, provider) {
        return Ok(owner);
    }
    Err(Error::name_res(
        capture.span,
        format!("macro capture `{name}` does not resolve to a type in this module"),
    ))
}

#[cfg(all(test, feature = "surface"))]
fn resolve_type_name_owner<'m>(
    name: &str,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Option<(String, crate::ast::Visibility)> {
    let provider = NominalProvider::new(Some(env.module), env.package);
    resolve_type_name_owner_with_provider(name, env, &provider)
}

fn resolve_type_name_owner_with_provider<'m>(
    name: &str,
    _env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    provider: &NominalProvider<'m, Lowered>,
) -> Option<(String, crate::ast::Visibility)> {
    let segments = [PathSegment::new(name.to_owned(), Span::new(0, 0))];
    let NominalSelection::Selected(declaration) =
        provider.select(provider.root(), &segments, false)
    else {
        return None;
    };
    let visibility = if let Some(newtype) = declaration.declaration.newtype() {
        newtype.vis.clone()
    } else {
        let alias = declaration.declaration.type_alias()?;
        alias.vis.clone()
    };
    Some((module_path_string(declaration.owner.module()?), visibility))
}

fn resolve_capture_fn_owner<'m>(
    capture: &crate::ast::UserMacroCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Result<ResolvedCaptureTermPath, Error> {
    let name = capture.segments[0].as_str();
    if let Some(f) = env
        .fn_defs
        .get(name)
        .copied()
        .or_else(|| env.cross_module_fn_defs.get(name).copied())
    {
        let owner = find_fn_owner(env, f).unwrap_or_else(|| env.module_path.clone());
        return Ok(ResolvedCaptureTermPath {
            source_owner_module_path: Some(owner.clone()),
            owner_module_path: Some(owner.clone()),
            visibility_edges: vec![ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(owner),
                visibility: f.vis.clone(),
                target: format!("captured function `{name}`"),
            }],
            replay_tail: vec![name.to_owned()],
        });
    }
    if env.env_fn_defs.contains_key(name) {
        let owner = env_owner(env);
        return Ok(ResolvedCaptureTermPath {
            source_owner_module_path: Some(owner.clone()),
            owner_module_path: Some(owner.clone()),
            visibility_edges: vec![ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(owner),
                visibility: crate::ast::Visibility::Public,
                target: format!("captured function `{name}`"),
            }],
            replay_tail: vec![name.to_owned()],
        });
    }
    Err(Error::name_res(
        capture.span,
        format!("macro capture `{name}` does not resolve to a function in this module"),
    ))
}

#[cfg(all(test, feature = "surface"))]
fn resolve_capture_member_owner<'m>(
    capture: &crate::ast::UserMacroCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Result<ResolvedCaptureTermPath, Error> {
    let nominal_provider = NominalProvider::new(Some(env.module), env.package);
    resolve_capture_member_owner_with_provider(capture, env, &nominal_provider)
}

fn resolve_capture_member_owner_with_provider<'m>(
    capture: &crate::ast::UserMacroCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    _nominal_provider: &NominalProvider<'m, Lowered>,
) -> Result<ResolvedCaptureTermPath, Error> {
    if capture.segments.len() == 2 {
        let type_name = capture.segments[0].as_str();
        let member = capture.segments[1].as_str();
        let type_segments = &capture.segments[..1];
        if let Some(resolved) =
            resolve_capture_newtype_member(capture, env, type_segments, type_name, member)?
        {
            return Ok(resolved);
        }
    }
    if capture.segments.len() == 2 {
        let alias = capture.segments[0].as_str();
        let member = capture.segments[1].as_str();
        if let Some(module) = env.qualified_imports.get(alias) {
            for item in &module.items {
                if let crate::ast::Item::FnDef(f) = item
                    && f.name == member
                {
                    let owner = env
                        .package
                        .and_then(|package| {
                            package.modules().find_map(|(path, entry)| {
                                std::ptr::eq(&entry.module, *module).then(|| (*path).to_owned())
                            })
                        })
                        .unwrap_or_else(|| env.module_path.clone());
                    return Ok(ResolvedCaptureTermPath {
                        source_owner_module_path: Some(owner.clone()),
                        owner_module_path: Some(owner.clone()),
                        visibility_edges: vec![ResolvedCaptureVisibilityEdge {
                            owner_module_path: Some(owner),
                            visibility: f.vis.clone(),
                            target: format!("captured member `{alias}.{member}`"),
                        }],
                        replay_tail: vec![member.to_owned()],
                    });
                }
            }
        }
    }
    if capture.segments.len() == 3 {
        let type_name = capture.segments[1].as_str();
        let member = capture.segments[2].as_str();
        let type_segments = &capture.segments[..2];
        let display_name = format!("{}.{type_name}", capture.segments[0].as_str());
        if let Some(resolved) =
            resolve_capture_newtype_member(capture, env, type_segments, &display_name, member)?
        {
            return Ok(resolved);
        }
    }
    Err(Error::name_res(
        capture.span,
        format!(
            "macro capture `{}` does not resolve to a supported function or newtype member",
            capture
                .segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>()
                .join(".")
        ),
    ))
}

fn resolve_capture_newtype_member<'m>(
    capture: &crate::ast::UserMacroCapture,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    type_segments: &[PathSegment],
    display_name: &str,
    member: &str,
) -> Result<Option<ResolvedCaptureTermPath>, Error> {
    let Some(resolved) = env.resolve_member_newtype(type_segments) else {
        return Ok(None);
    };
    let member_vis = if member == resolved.newtype.constructor.name {
        resolved.newtype.constructor.vis.clone()
    } else if member == resolved.newtype.projector.name {
        resolved.newtype.projector.vis.clone()
    } else {
        return Err(Error::name_res(
            capture.span,
            format!("newtype `{display_name}` has no member `{member}`"),
        ));
    };
    let source_visibility = resolved.source.visibility();
    let source_owner = module_path_string(resolved.source_module);
    let terminal_owner = module_path_string(resolved.declaring_module);
    let source_kind = if resolved.source.type_alias().is_some() {
        "type alias"
    } else {
        "newtype"
    };
    Ok(Some(ResolvedCaptureTermPath {
        source_owner_module_path: Some(source_owner.clone()),
        owner_module_path: Some(terminal_owner.clone()),
        visibility_edges: vec![
            ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(source_owner),
                visibility: source_visibility,
                target: format!("captured {source_kind} `{display_name}`"),
            },
            ResolvedCaptureVisibilityEdge {
                owner_module_path: Some(terminal_owner),
                visibility: member_vis,
                target: format!("captured member `{display_name}.{member}`"),
            },
        ],
        replay_tail: vec![resolved.newtype.name.clone(), member.to_owned()],
    }))
}

fn validate_user_macro_capture_source_order<'m>(
    macro_def: &'m crate::ast::UserMacroDef<Lowered>,
    item_index: usize,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) -> Result<(), Error> {
    fn item_declares_type(item: &Item<Lowered>, name: &str) -> bool {
        match item {
            Item::TypeAlias(alias) => alias.name == name,
            Item::Newtype(newtype) => newtype.name == name,
            Item::TypeRecGroup(group) => group.members.iter().any(|member| match member {
                crate::ast::TypeRecMember::TypeAlias(alias) => alias.name == name,
                crate::ast::TypeRecMember::Newtype(newtype) => newtype.name == name,
                crate::ast::TypeRecMember::Labels(labels, _) => {
                    labels.type_alias_name.as_deref() == Some(name)
                }
            }),
            _ => false,
        }
    }

    let nominal_provider = NominalProvider::new(Some(env.module), env.package);
    let visible_items = env
        .module
        .items
        .get(..item_index)
        .expect("macro item index belongs to its module");
    for capture in &macro_def.captures {
        let in_scope = match classify_user_macro_capture(capture)? {
            UserMacroCaptureSpelling::Type => {
                let name = capture.segments[0].as_str();
                if env.env_type_names.contains(name) {
                    env.module
                        .items
                        .iter()
                        .position(|item| matches!(item, Item::HostType(host) if host.name == name))
                        .is_none_or(|declaration| declaration < item_index)
                } else {
                    let (owner, _) =
                        resolve_capture_type_owner_with_provider(capture, env, &nominal_provider)?;
                    owner != env.module_path
                        || visible_items
                            .iter()
                            .any(|item| item_declares_type(item, name))
                }
            }
            UserMacroCaptureSpelling::Value => {
                let name = capture.segments[0].as_str();
                if env.env_fn_defs.contains_key(name) {
                    env.module
                        .items
                        .iter()
                        .position(|item| matches!(item, Item::HostFn(host) if host.name == name))
                        .is_none_or(|declaration| declaration < item_index)
                } else {
                    let resolved = resolve_capture_fn_owner(capture, env)?;
                    resolved.owner_module_path.as_deref() != Some(env.module_path.as_str())
                        || visible_items.iter().any(
                            |item| matches!(item, Item::FnDef(function) if function.name == name),
                        )
                }
            }
            UserMacroCaptureSpelling::Member => {
                let qualifier = capture.segments[0].as_str();
                if let Some(target) = env.qualified_imports.get(qualifier) {
                    if module_path_string(target) != env.module_path {
                        true
                    } else {
                        match capture.segments.as_slice() {
                            [_, member] => visible_items.iter().any(
                                |item| matches!(item, Item::FnDef(function) if function.name == member.as_str()),
                            ),
                            [_, type_name, _] => visible_items
                                .iter()
                                .any(|item| item_declares_type(item, type_name.as_str())),
                            _ => true,
                        }
                    }
                } else {
                    let resolved = resolve_capture_member_owner_with_provider(
                        capture,
                        env,
                        &nominal_provider,
                    )?;
                    resolved.source_owner_module_path.as_deref() != Some(env.module_path.as_str())
                        || visible_items
                            .iter()
                            .any(|item| item_declares_type(item, qualifier))
                }
            }
        };
        if !in_scope {
            let rendered = capture
                .segments
                .iter()
                .map(PathSegment::as_str)
                .collect::<Vec<_>>()
                .join(".");
            return Err(Error::name_res(
                capture.span,
                format!(
                    "macro capture `{rendered}` is not in scope before macro `{}`",
                    macro_def.name
                ),
            )
            .with_help(format!(
                "move the declaration of `{rendered}` above macro `{}`",
                macro_def.name
            )));
        }
    }
    Ok(())
}

fn capture_import(
    imports: &mut Vec<UserMacroTemplateGeneratedImport>,
    owner_module_path: &str,
    module: &Module,
) -> UserMacroTemplateGeneratedImport {
    if let Some(import) = imports
        .iter()
        .find(|import| import.module_path == owner_module_path)
    {
        return import.clone();
    }
    let mut requalifier = crate::pass::typecheck_core::PrimeTypeRequalifier::new(module);
    for import in imports.iter() {
        requalifier.add_generated_import(&import.module_path, &import.alias);
    }
    let import = UserMacroTemplateGeneratedImport {
        module_path: owner_module_path.to_owned(),
        alias: requalifier.ensure_module_import(owner_module_path),
    };
    if !imports.iter().any(|existing| existing == &import) {
        imports.push(import.clone());
    }
    import
}

fn captured_term_for_replay(
    capture: &crate::ast::UserMacroCapture,
    resolved: &ResolvedCaptureTermPath,
    imports: &mut Vec<UserMacroTemplateGeneratedImport>,
    module: &Module,
) -> Expr {
    if let Some(owner_module_path) = &resolved.owner_module_path {
        let import = capture_import(imports, owner_module_path, module);
        expr_from_capture_path(
            std::iter::once(import.alias).chain(resolved.replay_tail.clone()),
            capture.span,
        )
    } else {
        expr_from_capture_path(resolved.replay_tail.clone(), capture.span)
    }
}

fn captured_type_for_term_replay<'m>(
    ty: &Type,
    owner_module_path: &str,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    nominal_provider: &NominalProvider<'m, Lowered>,
    imports: &mut Vec<UserMacroTemplateGeneratedImport>,
    identity_canonical: bool,
) -> Type {
    match ty {
        Type::Path {
            segments,
            args,
            meta,
        } => {
            let args = args
                .iter()
                .map(|arg| {
                    captured_type_for_term_replay(
                        arg,
                        owner_module_path,
                        env,
                        nominal_provider,
                        imports,
                        identity_canonical,
                    )
                })
                .collect();
            if identity_canonical
                && let Some((module_path, name)) = canonical_nominal_identity(segments)
            {
                let import = capture_import(imports, &module_path, env.module);
                return Type::synth_path(vec![import.alias, name], args, meta.span);
            }
            if segments.len() == 1
                && resolve_type_name_owner_with_provider(
                    segments[0].as_str(),
                    env,
                    nominal_provider,
                )
                .is_some_and(|(owner, _)| owner == owner_module_path)
            {
                let import = capture_import(imports, owner_module_path, env.module);
                return Type::synth_path(
                    vec![import.alias, segments[0].name.clone()],
                    args,
                    meta.span,
                );
            }
            Type::synth_path_segments(segments.clone(), args, meta.span)
        }
        Type::Product { left, right, meta } => Type::Product {
            left: Box::new(captured_type_for_term_replay(
                left,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            right: Box::new(captured_type_for_term_replay(
                right,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            meta: meta.clone(),
        },
        Type::Sum { left, right, meta } => Type::Sum {
            left: Box::new(captured_type_for_term_replay(
                left,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            right: Box::new(captured_type_for_term_replay(
                right,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            meta: meta.clone(),
        },
        Type::Function {
            param,
            ret,
            meta,
            abi_arity,
            caps,
        } => {
            let param = captured_type_for_term_replay(
                param,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            );
            Type::Function {
                param: Box::new(param),
                ret: Box::new(captured_type_for_term_replay(
                    ret,
                    owner_module_path,
                    env,
                    nominal_provider,
                    imports,
                    identity_canonical,
                )),
                meta: meta.clone(),
                abi_arity: *abi_arity,
                caps: *caps,
            }
        }
        Type::Forall { param, body, meta } => Type::Forall {
            param: param.clone(),
            body: Box::new(captured_type_for_term_replay(
                body,
                owner_module_path,
                env,
                nominal_provider,
                imports,
                identity_canonical,
            )),
            meta: meta.clone(),
        },
        Type::Unit { meta } => Type::Unit { meta: meta.clone() },
        Type::Bottom { meta } => Type::Bottom { meta: meta.clone() },
        Type::Infer { meta, ext } => Type::Infer {
            meta: meta.clone(),
            ext: *ext,
        },
        Type::Goal { .. } => unreachable!(
            "captured term replay requires a closed type; Type::Goal must be zonked first"
        ),
    }
}

fn captured_term_type_for_replay<'m>(
    ty: &InternedType,
    resolved: &ResolvedCaptureTermPath,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    nominal_provider: &NominalProvider<'m, Lowered>,
    imports: &mut Vec<UserMacroTemplateGeneratedImport>,
) -> Type {
    if ty.identity_is_canonical() {
        return captured_type_for_term_replay(
            ty.as_type(),
            "",
            env,
            nominal_provider,
            imports,
            true,
        );
    }
    if let Some(owner_module_path) = &resolved.owner_module_path {
        captured_type_for_term_replay(
            ty.as_type(),
            owner_module_path,
            env,
            nominal_provider,
            imports,
            false,
        )
    } else {
        ty.clone_type()
    }
}

fn canonicalize_captured_generated_imports<P>(
    ty: &crate::ast::Type<P>,
    imports: &[UserMacroTemplateGeneratedImport],
) -> crate::ast::Type<P>
where
    P: crate::ast::Phase + Clone,
{
    canonicalize_captured_generated_imports_with_bound(ty, imports, &HashSet::new())
}

fn canonicalize_captured_generated_imports_with_bound<P>(
    ty: &crate::ast::Type<P>,
    imports: &[UserMacroTemplateGeneratedImport],
    bound: &HashSet<String>,
) -> crate::ast::Type<P>
where
    P: crate::ast::Phase + Clone,
{
    match ty {
        crate::ast::Type::Path {
            segments,
            args,
            meta,
        } => {
            let args = args
                .iter()
                .map(|arg| canonicalize_captured_generated_imports_with_bound(arg, imports, bound))
                .collect();
            let segments = segments
                .first()
                .filter(|head| !bound.contains(head.as_str()))
                .and_then(|head| {
                    imports
                        .iter()
                        .rev()
                        .find(|import| import.alias == head.as_str())
                })
                .map(|import| {
                    import
                        .module_path
                        .split('/')
                        .filter(|segment| !segment.is_empty())
                        .map(|segment| PathSegment::new(segment.to_owned(), meta.span))
                        .chain(segments.iter().skip(1).cloned())
                        .collect()
                })
                .unwrap_or_else(|| segments.clone());
            crate::ast::Type::synth_path_segments(segments, args, meta.span)
        }
        crate::ast::Type::Product { left, right, meta } => crate::ast::Type::Product {
            left: Box::new(canonicalize_captured_generated_imports_with_bound(
                left, imports, bound,
            )),
            right: Box::new(canonicalize_captured_generated_imports_with_bound(
                right, imports, bound,
            )),
            meta: meta.clone(),
        },
        crate::ast::Type::Sum { left, right, meta } => crate::ast::Type::Sum {
            left: Box::new(canonicalize_captured_generated_imports_with_bound(
                left, imports, bound,
            )),
            right: Box::new(canonicalize_captured_generated_imports_with_bound(
                right, imports, bound,
            )),
            meta: meta.clone(),
        },
        crate::ast::Type::Function {
            param,
            ret,
            meta,
            abi_arity,
            caps,
        } => crate::ast::Type::Function {
            param: Box::new(canonicalize_captured_generated_imports_with_bound(
                param, imports, bound,
            )),
            ret: Box::new(canonicalize_captured_generated_imports_with_bound(
                ret, imports, bound,
            )),
            meta: meta.clone(),
            abi_arity: *abi_arity,
            caps: caps.clone(),
        },
        crate::ast::Type::Forall { param, body, meta } => {
            let mut nested = bound.clone();
            nested.insert(param.name.clone());
            crate::ast::Type::Forall {
                param: param.clone(),
                body: Box::new(canonicalize_captured_generated_imports_with_bound(
                    body, imports, &nested,
                )),
                meta: meta.clone(),
            }
        }
        crate::ast::Type::Unit { .. }
        | crate::ast::Type::Bottom { .. }
        | crate::ast::Type::Infer { .. } => ty.clone(),
        crate::ast::Type::Goal {
            goal,
            args,
            meta,
            ext,
        } => crate::ast::Type::Goal {
            goal: *goal,
            args: args
                .iter()
                .map(|arg| canonicalize_captured_generated_imports_with_bound(arg, imports, bound))
                .collect(),
            meta: meta.clone(),
            ext: ext.clone(),
        },
    }
}

fn visibility_owner_path(path: &str, span: Span) -> crate::ast::ModulePath {
    crate::ast::ModulePath {
        segments: path
            .split('/')
            .filter(|segment| !segment.is_empty())
            .map(|segment| PathSegment::new(segment.to_owned(), span))
            .collect(),
        span,
    }
}

fn require_macro_target_visibility(
    macro_def: &crate::ast::UserMacroDef<Lowered>,
    owner_module_path: Option<&str>,
    visibility: &crate::ast::Visibility,
    env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
    target: &str,
    span: Span,
) -> Result<(), Error> {
    let owner = owner_module_path
        .map(|path| visibility_owner_path(path, span))
        .unwrap_or_else(|| env.module.path.clone());
    if crate::pass::resolve::visibility_covers(visibility, &owner, &macro_def.vis, &env.module.path)
    {
        Ok(())
    } else {
        let error = Error::type_(
            span,
            format!(
                "{target} must be at least as visible as macro `{}`",
                macro_def.name
            ),
        );
        if owner.segments == env.module.path.segments {
            Err(error.with_help(format!(
                "give {target} visibility equal to or wider than macro `{}`",
                macro_def.name
            )))
        } else {
            Err(error)
        }
    }
}

fn validate_user_macro_implementation_binding<'m>(
    macro_def: &crate::ast::UserMacroDef<Lowered>,
    tcx: &TypeCtx<'m, '_>,
) -> Result<(), Error> {
    let segments = macro_def.implementation.segments();
    let Some(last) = segments.last() else {
        unreachable!("the parser emits a nonempty macro implementation path")
    };
    let rendered = segments
        .iter()
        .map(PathSegment::as_str)
        .collect::<Vec<_>>()
        .join(".");
    let is_unshadowed_comptime_value = segments.len() == 1
        && tcx.env.comptime_in_scope
        && !tcx.env.fn_defs.contains_key(last.as_str())
        && !tcx.env.cross_module_fn_defs.contains_key(last.as_str())
        && !tcx.env.env_fn_defs.contains_key(last.as_str())
        && crate::comptime::ComptimeBuiltin::from_public_name(last.as_str())
            .is_some_and(crate::comptime::ComptimeBuiltin::is_value_name);
    let binder = match tcx
        .elaborations
        .position_index()
        .binder_at(&tcx.env.module_path, last.span)
    {
        Some(binder) => binder,
        None if is_unshadowed_comptime_value => return Ok(()),
        None => unreachable!(
            "synthesized macro implementation path `{rendered}` did not record a binder"
        ),
    };
    if matches!(binder, ResolvedBinder::NewtypeMember { .. }) {
        return Err(Error::type_(
            macro_def.implementation.span(),
            format!(
                "newtype member `{rendered}` cannot implement macro `{}` because it does not have the macro ABI",
                macro_def.name
            ),
        )
        .with_help(
            "define a function that accepts the macro's reflected ABI inputs and returns `__Checked_term__`, then name that function after `impl`",
        ));
    }
    Ok(())
}

fn resolve_user_macro_captures<'m>(
    macro_def: &'m crate::ast::UserMacroDef<Lowered>,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<ResolvedUserMacroCaptures, Error> {
    if macro_def.captures.is_empty() {
        return Ok(ResolvedUserMacroCaptures::empty());
    }
    let nominal_provider = NominalProvider::new(Some(env.module), env.package);
    let mut inputs = Vec::new();
    let mut imports = Vec::new();
    for capture in &macro_def.captures {
        match classify_user_macro_capture(capture)? {
            UserMacroCaptureSpelling::Type => {
                let name = capture.segments[0].as_str();
                let host_capture = env.env_type_names.contains(name);
                let owner_visibility = if host_capture {
                    None
                } else {
                    Some(resolve_capture_type_owner_with_provider(
                        capture,
                        env,
                        &nominal_provider,
                    )?)
                };
                if let Some((owner, vis)) = &owner_visibility {
                    require_macro_target_visibility(
                        macro_def,
                        Some(owner),
                        vis,
                        env,
                        &format!("captured type `{name}`"),
                        capture.span,
                    )?;
                }
                let source_ty = type_from_capture_path([name.to_owned()], capture.span);
                compute_kind(&source_ty, capture.span, tcx)?;
                let replay_ty = if let Some((owner, _)) = owner_visibility {
                    captured_type_for_term_replay(
                        &source_ty,
                        &owner,
                        env,
                        &nominal_provider,
                        &mut imports,
                        false,
                    )
                } else {
                    source_ty
                };
                let replay_ty = canonicalize_captured_generated_imports(&replay_ty, &imports);
                let reflected =
                    reflect_macro_type_with_binders(replay_ty, tcx, &[], !host_capture)?;
                inputs.push(UserMacroTemplateInput::Type(reflected));
            }
            UserMacroCaptureSpelling::Value => {
                let resolved = resolve_capture_fn_owner(capture, env)?;
                for edge in &resolved.visibility_edges {
                    require_macro_target_visibility(
                        macro_def,
                        edge.owner_module_path.as_deref(),
                        &edge.visibility,
                        env,
                        &edge.target,
                        capture.span,
                    )?;
                }
                let synth = synth_path(&capture.segments, capture.span, tcx)?;
                let term_expr =
                    captured_term_for_replay(capture, &resolved, &mut imports, env.module);
                let replay_ty = captured_term_type_for_replay(
                    &synth.ty,
                    &resolved,
                    env,
                    &nominal_provider,
                    &mut imports,
                );
                let term_ty = canonicalize_captured_generated_imports(&replay_ty, &imports);
                let term_expr = substitute::substitute_expr_for_eval(
                    &term_expr,
                    tcx.elaborations,
                    &env.module_path,
                    env.package,
                    Some(env.module),
                );
                let term_ty = reflect_macro_type_with_binders(
                    term_ty,
                    tcx,
                    &[],
                    synth.ty.identity_is_canonical(),
                )?;
                let term = crate::normalization::CheckedTerm::new_reflected(term_expr, term_ty);
                inputs.push(UserMacroTemplateInput::CapturedTerm {
                    term: crate::normalization::EvalRef::new(term),
                });
            }
            UserMacroCaptureSpelling::Member => {
                let resolved =
                    resolve_capture_member_owner_with_provider(capture, env, &nominal_provider)?;
                for edge in &resolved.visibility_edges {
                    require_macro_target_visibility(
                        macro_def,
                        edge.owner_module_path.as_deref(),
                        &edge.visibility,
                        env,
                        &edge.target,
                        capture.span,
                    )?;
                }
                let synth = synth_path(&capture.segments, capture.span, tcx)?;
                let term_expr =
                    captured_term_for_replay(capture, &resolved, &mut imports, env.module);
                let replay_ty = captured_term_type_for_replay(
                    &synth.ty,
                    &resolved,
                    env,
                    &nominal_provider,
                    &mut imports,
                );
                let term_ty = canonicalize_captured_generated_imports(&replay_ty, &imports);
                let term_expr = substitute::substitute_expr_for_eval(
                    &term_expr,
                    tcx.elaborations,
                    &env.module_path,
                    env.package,
                    Some(env.module),
                );
                let term_ty = reflect_macro_type_with_binders(
                    term_ty,
                    tcx,
                    &[],
                    synth.ty.identity_is_canonical(),
                )?;
                let term = crate::normalization::CheckedTerm::new_reflected(term_expr, term_ty);
                inputs.push(UserMacroTemplateInput::CapturedTerm {
                    term: crate::normalization::EvalRef::new(term),
                });
            }
        }
    }
    Ok(ResolvedUserMacroCaptures { inputs, imports })
}

fn user_macro_semantic_function_type(
    ty: &InternedType,
    span: Span,
    alias_ctx: &AliasCtx<'_, '_>,
) -> Result<(Vec<InternedType>, InternedType), Error> {
    let (unfolded, identity_canonical) = crate::pass::typecheck_core::canonicalize_for_comparison(
        ty.as_type(),
        alias_ctx,
        ty.identity_is_canonical(),
    );
    match unfolded {
        Type::Function { param, ret, .. } => Ok((
            user_macro_semantic_value_slot_types(
                InternedType::fresh_with_identity(*param, identity_canonical),
                alias_ctx,
            ),
            InternedType::fresh_with_identity(*ret, identity_canonical),
        )),
        other => Err(Error::type_(
            span,
            format!(
                "user macro implementation must be a function, found `{}`",
                display_type(&other)
            ),
        )),
    }
}

fn user_macro_semantic_value_slot_types(
    mut param: InternedType,
    alias_ctx: &AliasCtx<'_, '_>,
) -> Vec<InternedType> {
    let mut slots = Vec::new();
    let mut at_root = true;
    loop {
        let (unfolded, identity_canonical) =
            crate::pass::typecheck_core::canonicalize_for_comparison(
                param.as_type(),
                alias_ctx,
                param.identity_is_canonical(),
            );
        match unfolded {
            Type::Unit { .. } if at_root => return slots,
            Type::Product { left, right, .. } => {
                slots.push(InternedType::fresh_with_identity(*left, identity_canonical));
                param = InternedType::fresh_with_identity(*right, identity_canonical);
                at_root = false;
            }
            terminal => {
                slots.push(InternedType::fresh_with_identity(
                    terminal,
                    identity_canonical,
                ));
                return slots;
            }
        }
    }
}

fn check_user_macro_param(
    actual: &InternedType,
    expected: &Type,
    span: Span,
    description: &str,
    alias_ctx: &AliasCtx<'_, '_>,
) -> Result<(), Error> {
    if crate::pass::typecheck_core::require_type_equiv_state(
        actual.as_type(),
        expected,
        span,
        alias_ctx,
        actual.identity_is_canonical(),
        false,
    )
    .is_ok()
    {
        Ok(())
    } else {
        Err(Error::type_(
            span,
            format!(
                "user macro implementation has `{}` for {description}, but the ABI expects \
                 `{}`",
                display_type(actual.as_type()),
                display_type(expected)
            ),
        ))
    }
}

fn user_macro_implementation_type_slot_modes<'m>(
    macro_def: &'m crate::ast::UserMacroDef<Lowered>,
    layout: &UserMacroSignatureLayout,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<Vec<UserMacroTypeSlotMode>, Error> {
    let span = macro_def.meta.span;
    let refl_type_ty = refl_type("__Type__", span);
    let checked_term_ty = checked_term_type(span);
    let natural_type_ty = Type::Unit {
        meta: Meta::new(span),
    };
    let alias_ctx = tcx.env.alias_ctx();
    let implementation = &macro_def.implementation;
    #[cfg(test)]
    record_user_macro_implementation_synthesis();
    let implementation_synth = synth_path(implementation.segments(), implementation.span(), tcx)?;
    let implementation_leaf = implementation
        .last()
        .expect("the parser emits a nonempty macro implementation path");
    <LoweredTyper as crate::pass::typecheck_core::Typer<Lowered>>::record_position_type(
        implementation.span(),
        implementation_synth.ty.clone(),
        tcx,
    );
    if implementation_leaf.span != implementation.span() {
        <LoweredTyper as crate::pass::typecheck_core::Typer<Lowered>>::record_position_type(
            implementation_leaf.span,
            implementation_synth.ty.clone(),
            tcx,
        );
    }
    validate_user_macro_implementation_binding(macro_def, tcx)?;
    let implementation_ty = implementation_synth.into_mono_interned()?;
    // The implementation contract is one semantic product packet. Its
    // concrete function value may bind that packet as one value or flatten
    // the product into multiple binders, so stored ABI arity is not the
    // definition-side slot authority.
    let (params, ret) = user_macro_semantic_function_type(&implementation_ty, span, &alias_ctx)?;
    let capture_spellings = macro_def
        .captures
        .iter()
        .map(classify_user_macro_capture)
        .collect::<Result<Vec<_>, _>>()?;
    let fills_schedule = macro_def.schedule == crate::ast::MacroSchedule::Fills;
    let capability_count = if fills_schedule { 2 } else { 1 };
    let expected_param_count = capability_count + capture_spellings.len() + layout.slots.len();
    if params.len() != expected_param_count {
        return Err(Error::type_(
            span,
            format!(
                "user macro implementation ABI expects {expected_param_count} value \
                 parameters, but implementation has {}",
                params.len()
            ),
        ));
    }

    let mut param_index = 0usize;
    check_user_macro_param(
        &params[param_index],
        &comptime_proof_type(span),
        span,
        "the compile-time proof parameter",
        &alias_ctx,
    )?;
    param_index += 1;

    if fills_schedule {
        check_user_macro_param(
            &params[param_index],
            &fill_ctx_type(span),
            span,
            "the fill-context parameter",
            &alias_ctx,
        )?;
        param_index += 1;
    }

    for spelling in capture_spellings {
        let expected = match spelling {
            UserMacroCaptureSpelling::Type => refl_type_ty.clone(),
            UserMacroCaptureSpelling::Value | UserMacroCaptureSpelling::Member => {
                checked_term_ty.clone()
            }
        };
        check_user_macro_param(
            &params[param_index],
            &expected,
            span,
            "a capture parameter",
            &alias_ctx,
        )?;
        param_index += 1;
    }

    let eligible = layout
        .layers
        .iter()
        .enumerate()
        .flat_map(|(layer, details)| (0..details.type_params.len()).map(move |slot| (layer, slot)))
        .map(|(layer, slot)| type_slot_occurs_only_in_result(layout, layer, slot, &alias_ctx))
        .collect::<Vec<_>>();
    let mut type_slot_modes = Vec::new();
    for slot in &layout.slots {
        match slot {
            UserMacroSignatureSlot::Type { param, .. } => {
                let actual = &params[param_index];
                if crate::pass::typecheck_core::require_type_equiv_state(
                    actual.as_type(),
                    &refl_type_ty,
                    span,
                    &alias_ctx,
                    actual.identity_is_canonical(),
                    false,
                )
                .is_ok()
                {
                    type_slot_modes.push(if eligible[type_slot_modes.len()] {
                        UserMacroTypeSlotMode::RequiredResult
                    } else {
                        UserMacroTypeSlotMode::Input
                    });
                } else if eligible[type_slot_modes.len()]
                    && crate::pass::typecheck_core::require_type_equiv_state(
                        actual.as_type(),
                        &natural_type_ty,
                        span,
                        &alias_ctx,
                        actual.identity_is_canonical(),
                        false,
                    )
                    .is_ok()
                {
                    type_slot_modes.push(UserMacroTypeSlotMode::NaturalResult);
                } else {
                    let expected = if eligible[type_slot_modes.len()] {
                        "either `__Type__` or `.` for a result-only slot"
                    } else {
                        "`__Type__` for an input-related or unused slot"
                    };
                    return Err(Error::type_(
                        span,
                        format!(
                            "user macro implementation has `{}` for type slot `[{}]`, but \
                             the ABI expects {expected}",
                            display_type(actual.as_type()),
                            param.name
                        ),
                    ));
                }
            }
            UserMacroSignatureSlot::Value { .. } => {
                check_user_macro_param(
                    &params[param_index],
                    &checked_term_ty,
                    span,
                    "a value slot parameter",
                    &alias_ctx,
                )?;
            }
        }
        param_index += 1;
    }
    let expected_return = if fills_schedule {
        ty_product(checked_term_ty.clone(), fill_ctx_type(span), span)
    } else {
        checked_term_ty
    };
    check_user_macro_param(
        &ret,
        &expected_return,
        span,
        "the implementation return type",
        &alias_ctx,
    )?;
    Ok(type_slot_modes)
}

#[cfg(test)]
thread_local! {
    static USER_MACRO_IMPLEMENTATION_SYNTHESES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(test)]
fn record_user_macro_implementation_synthesis() {
    USER_MACRO_IMPLEMENTATION_SYNTHESES.with(|count| count.set(count.get() + 1));
}

#[cfg(test)]
fn reset_user_macro_implementation_syntheses() {
    USER_MACRO_IMPLEMENTATION_SYNTHESES.with(|count| count.set(0));
}

#[cfg(test)]
fn user_macro_implementation_syntheses() -> usize {
    USER_MACRO_IMPLEMENTATION_SYNTHESES.with(std::cell::Cell::get)
}

fn check_user_macro_item<'m>(
    macro_def: &'m crate::ast::UserMacroDef<Lowered>,
    item_index: usize,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    elaborations: &mut Elaborations,
) -> Result<(), Error> {
    check_well_formed_type(&macro_def.call_ty)?;
    let mut tcx = TypeCtx::new(env, elaborations).at_item(item_index);
    crate::pass::typecheck_core::check_callable_spine_kinds(&macro_def.call_ty, &mut tcx)?;
    let alias_ctx = env.alias_ctx();
    let call_ty = InternedType::fresh(macro_def.call_ty.clone());
    let layout = user_macro_signature_layout(&call_ty, &alias_ctx);
    validate_user_macro_capture_source_order(macro_def, item_index, env)?;
    resolve_user_macro_captures(macro_def, env, &mut tcx)?;
    tcx.pure_context = true;
    user_macro_implementation_type_slot_modes(macro_def, &layout, &mut tcx)?;
    Ok(())
}

impl crate::pass::typecheck_core::HeaderRecording<Lowered> for LoweredTyper {
    const RECORD_NOMINAL_TYPE_BINDERS: bool = true;

    fn record_binder_at<'m>(
        segment_span: crate::span::Span,
        kind: crate::pass::typecheck_core::ResolvedBinderKind,
        name: &str,
        parent: Option<&str>,
        qualifier: Option<&str>,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        // The map key identifies the source module containing this written
        // segment. The binder itself carries the resolved declaration owner;
        // imported and qualified paths must use that canonical owner so every
        // syntax surface shares one references/rename identity.
        let mp = tcx.env.module_path.clone();
        let binder = resolved_binder_for_position(kind, name, parent, qualifier, tcx);
        tcx.elaborations
            .record_position_binder(&mp, segment_span, binder);
    }

    fn record_nominal_type_binder_at<'m>(
        segment_span: crate::span::Span,
        kind: crate::pass::typecheck_core::NominalTypeBinderKind,
        declaring_module_path: &str,
        name: &str,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        let binder = resolved_nominal_type_binder(kind, declaring_module_path, name);
        let consumer_module = tcx.env.module_path.clone();
        tcx.elaborations
            .record_position_binder(&consumer_module, segment_span, binder);
    }

    fn record_binder_decl_at<'m>(
        decl_span: crate::span::Span,
        kind: crate::pass::typecheck_core::ResolvedBinderKind,
        name: &str,
        tcx: &mut crate::pass::typecheck_core::TypeCtx<'m, '_, Lowered>,
    ) {
        tcx.attach_decl_span_to_local(name, decl_span);
        let mp = tcx.env.module_path.clone();
        let binder = match kind {
            crate::pass::typecheck_core::ResolvedBinderKind::Local => ResolvedBinder::Local {
                name: name.to_owned(),
                decl_span: Some(decl_span),
            },
            crate::pass::typecheck_core::ResolvedBinderKind::TypeParam => {
                ResolvedBinder::TypeParam {
                    name: name.to_owned(),
                    decl_span: Some(decl_span),
                }
            }
            _ => unreachable!("only local and type-parameter binders have lexical declarations"),
        };
        tcx.elaborations
            .record_local_decl(&mp, name, decl_span, binder);
        if let Some(ty) = tcx.locals.iter().rev().find_map(|local| match local {
            crate::pass::typecheck_core::Local::Value {
                name: bound_name,
                ty,
                decl_span: Some(span),
                ..
            } if bound_name == name && *span == decl_span => Some(ty.clone()),
            _ => None,
        }) {
            // Keep the bound type at its declaration; a use can be adapted
            // or instantiated without changing the value available in scope.
            Self::record_position_type(decl_span, ty, tcx);
        }
    }
}

impl TyperPhase for Lowered {
    type Typer = LoweredTyper;
}

impl crate::pass::typecheck_core::DeclarationPhase for Lowered {
    type Elaborations = Elaborations;
    type HeaderRecording = LoweredTyper;
    type AuxiliaryItems = crate::pass::typecheck_core::BodyItemChecks;

    fn new_elaborations(
        scope: &crate::pass::typecheck_core::PackageTypecheckScope<Self>,
    ) -> Elaborations {
        #[cfg(feature = "lsp")]
        if scope.collects_refactoring_facts() {
            let mut elaborations = Elaborations::new();
            elaborations.position_index = PositionIndex::for_refactoring();
            return elaborations;
        }
        #[cfg(not(feature = "lsp"))]
        let _ = scope;
        Elaborations::new()
    }

    fn merge_elaborations(target: &mut Self::Elaborations, source: Self::Elaborations) {
        target.merge(source);
    }
}

// =========================================================================
// Public entry point
// =========================================================================

/// Type-check every module in `package`, produce a
/// [`Prime`](crate::ast::Prime)-phase package with the macro-position
/// elaborations substituted into the AST in place of the surface
/// `into` / `onto` / `match` nodes, then validate the substituted
/// package with the standalone Kio' typer. Bails on the first error.
///
/// `Package<Prime>` is the semantic contract every backend
/// ultimately realizes: the Prime AST carries no `Expr::UserMacro` nodes
/// (their extension type is `Never`),
/// so the elaboration the typer recorded lives in-tree rather than
/// in a pointer-keyed side table — the type system enforces the contract.
pub fn check_package(
    package: &Package,
) -> Result<crate::prime::typer::ValidatedPrimePackage, LocatedError> {
    let checked = check_package_preserving_normalization(package)?;
    Ok(checked.complete()?.into_runtime())
}

pub(crate) fn validate_substituted_package(
    substituted: crate::pass::alpha_normalize::AlphaNormalizedPackage<Prime>,
) -> Result<crate::prime::typer::ValidatedPrimePackage, LocatedError> {
    crate::prime::typer::check_normalized_package(substituted)
}

/// A checked Lowered package together with the proof-bearing normalized tree
/// the elaborations were recorded against.
pub(crate) struct CheckedLoweredPackage {
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
    elaborations: Elaborations,
}

impl CheckedLoweredPackage {
    pub(crate) fn normalized(
        &self,
    ) -> &crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered> {
        &self.normalized
    }

    #[cfg(any(feature = "cli", test))]
    pub(crate) fn package(&self) -> &Package {
        self.normalized.package()
    }

    pub(crate) fn elaborations(&self) -> &Elaborations {
        &self.elaborations
    }

    #[cfg(any(feature = "lsp", test))]
    pub(crate) fn into_elaborations(self) -> Elaborations {
        self.elaborations
    }

    pub(crate) fn substituted(
        &self,
    ) -> crate::pass::alpha_normalize::AlphaNormalizedPackage<Prime> {
        substitute::substitute_normalized_package(self.normalized.clone(), &self.elaborations)
    }

    pub(crate) fn complete(self) -> Result<CompletedSourcePackage, LocatedError> {
        let runtime = validate_substituted_package(self.substituted())?;
        Ok(CompletedSourcePackage {
            source: CompletedLoweredSource { checked: self },
            runtime,
        })
    }
}

/// The exact checked source and its independently validated runtime output.
pub(crate) struct CompletedSourcePackage {
    source: CompletedLoweredSource,
    runtime: crate::prime::typer::ValidatedPrimePackage,
}

impl CompletedSourcePackage {
    #[cfg(any(feature = "repl-core", test))]
    pub(crate) fn runtime(&self) -> &crate::prime::typer::ValidatedPrimePackage {
        &self.runtime
    }

    #[cfg(any(feature = "lsp", test))]
    pub(crate) fn source(&self) -> &CompletedLoweredSource {
        &self.source
    }

    pub(crate) fn into_runtime(self) -> crate::prime::typer::ValidatedPrimePackage {
        self.runtime
    }

    /// Discard the runtime tree before constructing the distinct evaluator tree.
    pub(crate) fn into_source(self) -> CompletedLoweredSource {
        self.source
    }
}

/// Ordinary evaluation's source/elaboration pair, after runtime completion.
pub(crate) struct CompletedLoweredSource {
    checked: CheckedLoweredPackage,
}

impl CompletedLoweredSource {
    pub(crate) fn checked(&self) -> &CheckedLoweredPackage {
        &self.checked
    }

    pub(crate) fn eval_artifact(&self) -> Result<crate::normalization::EvalArtifact, LocatedError> {
        crate::normalization::EvalArtifact::from_completed_source(self)
    }
}

pub(crate) fn check_package_preserving_normalization(
    package: &Package,
) -> Result<CheckedLoweredPackage, LocatedError> {
    check_package_preserving_normalization_collect_errors(package).map_err(|errors| {
        errors
            .into_iter()
            .next()
            .expect("collected package errors are non-empty")
    })
}

pub(crate) fn check_package_preserving_normalization_collect_errors(
    package: &Package,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let type_interner = std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default());
    check_package_preserving_normalization_with_interner_and_execution(
        package,
        type_interner,
        crate::pass::typecheck_core::TypecheckExecution::AllowParallel,
    )
}

#[cfg(feature = "cli")]
pub(crate) fn check_normalized_package_collect_errors(
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let typecheck_scope =
        crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
            &normalized,
            std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
        );
    check_normalized_package_with_scope_and_execution(
        normalized,
        typecheck_scope,
        crate::pass::typecheck_core::TypecheckExecution::AllowParallel,
    )
}

#[cfg(feature = "lsp")]
pub(crate) fn check_normalized_package_collect_errors_with_scope(
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
    typecheck_scope: std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    check_normalized_package_with_scope_and_execution(
        normalized,
        typecheck_scope,
        crate::pass::typecheck_core::TypecheckExecution::AllowParallel,
    )
}

fn check_package_preserving_normalization_with_interner_and_execution(
    package: &Package,
    type_interner: std::sync::Arc<crate::pass::typecheck_core::TypeInterner<Lowered>>,
    execution: crate::pass::typecheck_core::TypecheckExecution,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let normalized = crate::pass::alpha_normalize::normalize_package(package);
    let typecheck_scope =
        crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
            &normalized,
            type_interner,
        );
    check_normalized_package_with_scope_and_execution(normalized, typecheck_scope, execution)
}

fn check_normalized_package_with_scope_and_execution(
    normalized: crate::pass::alpha_normalize::AlphaNormalizedPackage<Lowered>,
    typecheck_scope: std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
    execution: crate::pass::typecheck_core::TypecheckExecution,
) -> Result<CheckedLoweredPackage, Vec<LocatedError>> {
    let mut elaborations = Lowered::new_elaborations(&typecheck_scope);
    crate::pass::typecheck_core::check_package_modules_with_typecheck_scope_collect_errors_with_execution(
        normalized.package(),
        &mut elaborations,
        typecheck_scope,
        execution,
    )?;
    elaborations.present_binder_names(normalized.presentation_arc());
    Ok(CheckedLoweredPackage {
        normalized,
        elaborations,
    })
}

#[cfg(feature = "lsp")]
mod presentation;
pub(crate) mod publication;
pub(crate) mod rec_quote;
mod rec_quote_source;
#[cfg(feature = "lsp")]
mod refactoring_facts;
pub use crate::pass::binder_presentation::TypeBinderScope;
pub(crate) use rec_quote::QuotedPublicRecipe;

#[derive(Debug, Default)]
struct RecordedCallPlan {
    macro_output_stage: Option<usize>,
    splits: Vec<usize>,
    implicit_unit_slots: Vec<usize>,
    residual_eta_type: Option<RecordedTypeResolution>,
}

/// Carries typer-time replacement trees for surface elaboration forms and
/// compiler-private Lowered carriers. Surface forms such as `into`, `onto`,
/// and `match` record the Kio' trees that realize their runtime semantics;
/// `Expr::RecOrder` resolves an explicit recursive-CPS ordering/type-flow
/// direction and records either an ordinary `let` (with its exact binder type
/// retained alongside) or its type-only body. Entries are keyed by [`NodeId`],
/// whether parser- or desugar-issued, and IDs survive `Clone` and phase
/// rebuilds. Pointer-based keying would not survive subtree clones because
/// each clone has a fresh address.
///
/// Also carries the typer's **position-keyed index** for IDE / LSP
/// queries: per-expression synthesized types and per-path-segment
/// resolved binders. See [`PositionIndex`] for the contract — the
/// index is populated on every `synth_expr` / `synth_path` walk so
/// downstream LSP queries (hover, goto-definition, references) can
/// look up "what's at this cursor position" without re-running the
/// typer.
#[derive(Debug, Default)]
pub struct Elaborations {
    #[allow(clippy::box_collection)] // Keep the ordinary no-rec layout to one pointer.
    rec_loop_diagnostics: Option<Box<Vec<RecLoopDiagnosticRecord>>>,
    /// Sparse, occurrence-keyed public type inventory for recursive quotation.
    /// Entries become readable only when their ordinary publication closes.
    rec_quote: Option<Box<rec_quote::RecQuoteCaptures>>,
    /// Keyed by `(module_path, NodeId)`. A `NodeId` alone is file-local, so the
    /// module-path prefix disambiguates package modules exactly as for the
    /// occurrence-keyed fields below. `NodeId` (not span/pointer) is retained in the
    /// key so it survives the typer's subtree clones.
    entries: HashMap<(String, NodeId), RecordedElaboration>,
    /// Compiler-private recursive-order replacements paired with the exact
    /// binder type that substitution must put on their root `let`. Keeping
    /// these out of [`RecordedElaboration`] preserves that public enum's
    /// surface while retaining the same stable module-and-node identity.
    rec_order_runtime: HashMap<(String, NodeId), RecordedRecOrderRuntime>,
    /// Solved type arguments keyed by the actual call occurrence and canonical
    /// slot. Copied syntax can share a source span while independently checked
    /// instances require different substitutions.
    type_resolutions:
        HashMap<(String, crate::ast::ExpressionOccurrenceId, usize), RecordedTypeResolution>,
    /// Canonical argument boundaries and any residual eta plan for one Full
    /// Kio call. Keeping both in one record makes the Lowered → PrePrime
    /// consumer observe exactly the call plan that committed with inference.
    call_plans: HashMap<(String, crate::ast::ExpressionOccurrenceId), RecordedCallPlan>,
    /// Resolved primitive values whose semantic schemes determine runtime erasure.
    primitive_values: HashMap<(String, crate::ast::ExpressionOccurrenceId), String>,
    comptime_literals: HashMap<(String, crate::ast::ExpressionOccurrenceId), ComptimeLiteralPlan>,
    comptime_literal_names: HashMap<String, HashSet<String>>,
    /// The selected type and checked numeric value, keyed by `(module_path, literal_id)`.
    /// Substitution bakes these into ordinary Prime literals for every later consumer.
    literal_resolutions: HashMap<
        (String, crate::ast::ExpressionOccurrenceId),
        (RecordedTypeResolution, Option<String>),
    >,
    /// Checked lambda parameter types, plus the body result for proof-gated
    /// lambdas whose body is erased before Prime. `Some(index)` identifies a
    /// value parameter; `None` identifies that checked body result.
    fn_signature_types: HashMap<
        (String, crate::ast::ExpressionOccurrenceId, Option<usize>),
        RecordedTypeResolution,
    >,
    generated_imports: HashMap<String, Vec<UserMacroTemplateGeneratedImport>>,
    prime_requalification_imports: HashMap<String, Vec<UserMacroTemplateGeneratedImport>>,
    generated_type_aliases: HashMap<String, Vec<PrimeLocalTypeAlias>>,
    /// Position-keyed index of the typer's output — per-expression
    /// synthesized types and per-path-segment resolved binders.
    /// Populated by the `Typer<Lowered>` impl on every `synth_expr`
    /// return and by `synth_path` on every binder resolution. The
    /// LSP consumes this to answer hover / goto-definition / references queries
    /// without re-running the typer. See [`PositionIndex`] for the data shape
    /// and the merge / disjointness contract.
    position_index: PositionIndex,
    /// **Deferred-elaboration queue.** A closed-result user macro can
    /// leave glue production until the module boundary: its ordinary call
    /// plan already fixes the result type, and the queued obligation later
    /// runs the macro and checks its returned term against that type.
    /// A type-producing macro instead runs while its application frontier
    /// is live; the returned checked term constrains that owner's output goal,
    /// and its already-computed template is queued only for uniform recording.
    /// Draining happens in [`Self::discharge_deferred`] while the module's alias
    /// context remains available, and records each resulting Kio' tree into
    /// `entries` for the Lowered → Prime substitution pass.
    ///
    /// The queue is keyed by `(macro name, reified source, reified
    /// target)` so structurally identical obligations are comparable
    /// across sites before glue production.
    deferred: Vec<DeferredElaboration>,
}

#[derive(Debug)]
pub(crate) struct RecLoopDiagnosticRecord {
    pub(crate) outer_call: crate::ast::ExpressionOccurrenceId,
    pub(crate) selected_path: Span,
    pub(crate) escape_call: Option<Span>,
    pub(crate) actual_type: InternedType,
    pub(crate) initial_result_sites: Vec<crate::ast::ExpressionOccurrenceId>,
    pub(crate) callee_binder_goals: Vec<crate::ast::TypeGoalRef>,
}

#[derive(Debug, Clone)]
pub enum RecordedElaboration {
    Lowered(Expr),
    UncheckedPrime {
        expression: UncheckedPrimeExpr,
        primitives: Option<std::sync::Arc<crate::normalization::EvalPrimitiveEnv>>,
    },
}

#[derive(Debug, Clone)]
pub(crate) struct ComptimeLiteralPlan {
    pub(crate) binding: String,
    pub(crate) constructor: crate::comptime::ComptimeLiteralConstructor,
}

#[derive(Debug)]
struct RecordedRecOrderRuntime {
    replacement: Expr,
    binding_type: RecordedTypeResolution,
}

/// A single deferred elaboration obligation. Closed-result obligations carry
/// the result type against which discharge checks the macro's returned
/// term. Type-producing obligations carry a template already evaluated on the
/// live application frontier, where that returned term constrained the output
/// goal; discharge reuses the template without running the macro again.
///
/// Owned (not borrowed): the discharge runs after the per-fn-body typer
/// borrows have dropped, so `value` is a clone of the macro's inner
/// expression and the types are owned. The clone shares `NodeId`s with
/// the original (the parser issues them and they survive `Clone`), so
/// the elaboration the discharge records under `node_id` lands on the
/// surface node the `substitute` pass looks up.
#[derive(Debug)]
enum DeferredElaboration {
    UserMacro(Box<DeferredUserMacroElaboration>),
}

#[derive(Debug)]
pub(crate) struct DeferredUserMacroElaboration {
    node_id: NodeId,
    name: String,
    macro_module_path: Option<String>,
    values: Vec<Expr>,
    abi_inputs: Vec<UserMacroTemplateInput>,
    input_keys: Vec<UserMacroTemplateInputKey>,
    capture_imports: Vec<UserMacroTemplateGeneratedImport>,
    value_adapter: crate::normalization::CheckedTermTemplateValueAdapter,
    residual_abstraction: crate::pass::substitute::EtaPlan<UncheckedPrime>,
    ambient_type_names: HashSet<String>,
    residual_reflection_bindings: Vec<(String, crate::normalization::ReflectedVariable)>,
    result_ty: Option<InternedType>,
    precomputed_template: Option<UserMacroTemplateResult>,
    quoted_public_recipe: Option<Box<QuotedPublicRecipe>>,
    span: Span,
}

pub(crate) struct ReadyUserMacroAction {
    schedule: crate::ast::MacroSchedule,
    node_id: NodeId,
    name: String,
    macro_module_path: Option<String>,
    values: Vec<Expr>,
    abi_inputs: Vec<UserMacroTemplateInput>,
    input_keys: Vec<UserMacroTemplateInputKey>,
    capture_imports: Vec<UserMacroTemplateGeneratedImport>,
    value_adapter: crate::normalization::CheckedTermTemplateValueAdapter,
    residual_abstraction: crate::pass::substitute::EtaPlan<UncheckedPrime>,
    ambient_type_names: HashSet<String>,
    residual_reflection_bindings: Vec<(String, crate::normalization::ReflectedVariable)>,
    terminal_result_ty: Option<InternedType>,
    span: Span,
    result_span: Span,
}

pub(crate) struct StagedReadyProjectedUserMacroEvaluation<'m> {
    ready: ReadyProjectedUserMacroAction<'m>,
    returned: crate::normalization::Value,
}

impl ReadyUserMacroAction {
    pub(crate) fn result_span(&self) -> Span {
        self.result_span
    }

    pub(crate) fn schedule(&self) -> crate::ast::MacroSchedule {
        self.schedule
    }

    fn into_obligation(
        self,
        result_ty: Option<InternedType>,
        precomputed_template: Option<UserMacroTemplateResult>,
    ) -> DeferredUserMacroElaboration {
        DeferredUserMacroElaboration {
            node_id: self.node_id,
            name: self.name,
            macro_module_path: self.macro_module_path,
            values: self.values,
            abi_inputs: self.abi_inputs,
            input_keys: self.input_keys,
            capture_imports: self.capture_imports,
            value_adapter: self.value_adapter,
            residual_abstraction: self.residual_abstraction,
            ambient_type_names: self.ambient_type_names,
            residual_reflection_bindings: self.residual_reflection_bindings,
            result_ty,
            precomputed_template,
            quoted_public_recipe: None,
            span: self.span,
        }
    }
}

pub(crate) fn defer_ready_user_macro_action(
    ready: ReadyUserMacroAction,
) -> DeferredUserMacroElaboration {
    assert_eq!(ready.schedule, crate::ast::MacroSchedule::Late);
    let result_ty = ready
        .terminal_result_ty
        .clone()
        .expect("a deferred macro action has a closed terminal result type");
    ready.into_obligation(Some(result_ty), None)
}

pub(crate) fn evaluate_ready_user_macro_action<'m>(
    ready: ReadyUserMacroAction,
    tcx: &TypeCtx<'m, '_>,
) -> Result<(DeferredUserMacroElaboration, InternedType), Error> {
    assert_eq!(ready.schedule, crate::ast::MacroSchedule::Late);
    assert!(
        ready.terminal_result_ty.is_none(),
        "only an unresolved type-producing macro action evaluates on the frontier"
    );
    let mut obligation = ready.into_obligation(None, None);
    let key = user_macro_template_memo_key(&obligation, tcx.env);
    let computed = compute_user_macro_deferred_template(
        &obligation,
        key,
        tcx.env,
        &*tcx.elaborations,
        &tcx.env.memo,
    )?;
    let result_ty = match &computed {
        Ok(template) => crate::ast::convert_type::<UncheckedPrime, Lowered>(template.result_ty()),
        Err(message) => return Err(Error::macro_error(obligation.span, message.clone())),
    };
    check_well_formed_type(&result_ty)?;
    let result_ty = InternedType::fresh_canonical(result_ty);
    obligation.result_ty = Some(result_ty.clone());
    obligation.precomputed_template = Some(computed);
    Ok((obligation, result_ty))
}

pub(crate) fn evaluate_ready_projected_user_macro_action<'m>(
    ready: ReadyProjectedUserMacroAction<'m>,
    tcx: &TypeCtx<'m, '_>,
) -> Result<StagedReadyProjectedUserMacroEvaluation<'m>, Error> {
    let packet = ready.eval_packet();
    let evaluated = evaluate_user_macro_packet(
        &ready.action.name,
        ready.action.macro_module.map(module_path_string).as_deref(),
        &ready.captures.imports,
        ready.action.span,
        packet,
        tcx,
    )?;
    Ok(StagedReadyProjectedUserMacroEvaluation {
        ready,
        returned: evaluated,
    })
}

pub(crate) fn prevalidate_ready_projected_user_macro_action<'m>(
    evaluation: StagedReadyProjectedUserMacroEvaluation<'m>,
) -> Result<
    (
        ReadyProjectedUserMacroAction<'m>,
        crate::pass::typecheck_core::apply::fills::ProjectedCheckedResult,
        crate::pass::typecheck_core::apply::fills::FillContext,
    ),
    Error,
> {
    let span = evaluation.ready.action.span;
    let Some((checked, returned_context)) =
        crate::normalization::core_product_value_parts(&evaluation.returned)
    else {
        return Err(Error::macro_error(
            span,
            "fills macro returned a value other than `__Checked_term__ & __Fill_ctx__`",
        ));
    };
    let (checked, returned_context) = prevalidate_projected_returned_values(
        checked,
        returned_context,
        &evaluation.ready.proof,
        &evaluation.ready.fills,
        span,
    )?;
    Ok((evaluation.ready, checked, returned_context))
}

fn prevalidate_projected_returned_values(
    checked: &crate::normalization::Value,
    returned_context: &crate::normalization::Value,
    proof: &crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    initial_context: &crate::pass::typecheck_core::apply::fills::FillContext,
    span: Span,
) -> Result<
    (
        crate::pass::typecheck_core::apply::fills::ProjectedCheckedResult,
        crate::pass::typecheck_core::apply::fills::FillContext,
    ),
    Error,
> {
    let returned_context = crate::normalization::fill_context_from_value(returned_context)
        .filter(|context| context.matches(initial_context))
        .cloned()
        .ok_or_else(|| {
            Error::macro_error(
                span,
                "fills macro returned a `__Fill_ctx__` from another invocation",
            )
        })?;
    let checked = match checked {
        crate::normalization::Value::CheckedTerm(checked) => {
            crate::pass::typecheck_core::apply::fills::ProjectedCheckedResult::Closed(
                prevalidate_projected_closed_checked_result(checked.clone(), span)?,
            )
        }
        crate::normalization::Value::Projected(_) => {
            let projected = crate::normalization::projected_value_from_value(checked)
                .expect("a projected evaluator value lost its opaque payload");
            let recipe = projected
                .authenticated_checked_recipe(proof)
                .ok_or_else(|| {
                    Error::macro_error(
                        span,
                        "fills macro returned a projected value other than an authenticated `__Checked_term__`",
                    )
                })?;
            prevalidate_projected_checked_error(recipe.checked_error(), span)?;
            crate::pass::typecheck_core::apply::fills::ProjectedCheckedResult::Recipe(recipe)
        }
        _ => {
            return Err(Error::macro_error(
                span,
                "fills macro returned a value other than `__Checked_term__`",
            ));
        }
    };
    Ok((checked, returned_context))
}

fn prevalidate_projected_closed_checked_result(
    checked: crate::normalization::EvalRef<crate::normalization::CheckedTerm>,
    span: Span,
) -> Result<crate::normalization::EvalRef<crate::normalization::CheckedTerm>, Error> {
    prevalidate_projected_checked_error(checked.checked_error(), span)?;
    Ok(checked)
}

fn prevalidate_projected_checked_error(
    checked_error: Option<(crate::normalization::CheckedTermErrorKind, &str)>,
    span: Span,
) -> Result<(), Error> {
    if let Some((kind, message)) = checked_error {
        return Err(match kind {
            crate::normalization::CheckedTermErrorKind::Macro => Error::macro_error(span, message),
            crate::normalization::CheckedTermErrorKind::Type => Error::type_(span, message),
        });
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn materialize_ready_projected_user_macro_action<'m>(
    ready: ReadyProjectedUserMacroAction<'m>,
    typed: TypedUserMacroCall,
    checked: crate::normalization::EvalRef<crate::normalization::CheckedTerm>,
    public_terminal_result: InternedType,
    checked_result: InternedType,
    projected_sources: Vec<crate::pass::typecheck_core::apply::fills::ProjectedTemplateSource>,
    quoted_public_recipe: Option<Box<QuotedPublicRecipe>>,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<DeferredUserMacroElaboration, Error> {
    let residual_bindings: Vec<_> = ready.residual_reflection_bindings().collect();
    let ReadyProjectedUserMacroAction {
        action,
        captures,
        declared_inputs: _,
        frozen_residual,
        proof: _,
        fills: _,
    } = ready;
    let mut adapter_sources = Vec::with_capacity(projected_sources.len());
    let mut adapter_slots = Vec::with_capacity(projected_sources.len());
    let mut values = Vec::with_capacity(projected_sources.len());
    for (index, source) in projected_sources.into_iter().enumerate() {
        let reflected_ty = reflect_projected_type(
            &source.ty,
            tcx,
            &source.reflection_scope,
            residual_bindings.iter().cloned(),
        )?;
        adapter_sources.push(crate::normalization::CheckedTermTemplateSource {
            ty: reflected_ty.clone(),
            force_if_unused: source
                .layer
                .is_some_and(|layer| action.layout.layers[layer].value_abi_arity == 0),
        });
        adapter_slots.push(crate::normalization::CheckedTermTemplateSlot {
            pieces: vec![crate::normalization::CheckedTermTemplatePiece {
                source_index: index,
                source_slot: 0,
                source_slot_tys: vec![reflected_ty],
            }],
        });
        values.push(source.source);
    }
    let mut ordinary =
        action.into_ready_with_captures(typed, captures, Some(&frozen_residual), tcx)?;
    assert_eq!(ordinary.schedule, crate::ast::MacroSchedule::Fills);
    ordinary.values = values;
    ordinary.value_adapter = crate::normalization::CheckedTermTemplateValueAdapter {
        sources: adapter_sources,
        slots: adapter_slots,
    };
    // Keep the projected and ordinary derivations honest at the public eta
    // boundary before checking the possibly lifted runtime result below.
    let ordinary_terminal_result = ordinary
        .terminal_result_ty
        .clone()
        .expect("a residual-aware fills ABI has a terminal eta-body result type");
    crate::pass::typecheck_core::require_type_equiv_state(
        public_terminal_result.as_type(),
        ordinary_terminal_result.as_type(),
        ordinary.span,
        &tcx.env.alias_ctx(),
        public_terminal_result.identity_is_canonical(),
        ordinary_terminal_result.identity_is_canonical(),
    )?;
    let template = trusted_user_macro_template(checked.as_ref().clone(), &residual_bindings);
    let lowered_checked_ty =
        crate::ast::convert_type::<UncheckedPrime, Lowered>(template.checked.ty());
    crate::pass::typecheck_core::require_type_equiv_state(
        &lowered_checked_ty,
        checked_result.as_type(),
        ordinary.span,
        &tcx.env.alias_ctx(),
        true,
        checked_result.identity_is_canonical(),
    )?;
    let mut obligation = ordinary.into_obligation(Some(checked_result), Some(Ok(template)));
    obligation.quoted_public_recipe = quoted_public_recipe;
    Ok(obligation)
}

fn evaluate_user_macro_packet<'m>(
    name: &str,
    macro_module_path: Option<&str>,
    capture_imports: &[UserMacroTemplateGeneratedImport],
    span: Span,
    packet: crate::normalization::Value,
    tcx: &TypeCtx<'m, '_>,
) -> Result<crate::normalization::Value, Error> {
    let macro_module = macro_module_for_path(tcx.env, macro_module_path);
    let macro_module_path = macro_module
        .map(module_path_string)
        .unwrap_or_else(|| tcx.env.module_path.clone());
    let artifact_pair = tcx
        .env
        .typecheck_scope
        .user_macro_artifacts()
        .get_or_try_compute(
            UserMacroArtifactKey::new(
                macro_module_path.clone(),
                name.to_owned(),
                capture_imports.to_vec(),
            ),
            || user_macro_eval_artifact(tcx.env, capture_imports, name, span, macro_module),
            |cached| {
                let fresh = user_macro_eval_artifact(
                    tcx.env,
                    capture_imports,
                    name,
                    span,
                    macro_module,
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "KIO_DEBUG_MEMO_VERIFY=1: fresh user macro artifact validation failed: {}",
                        error.diagnostic().message
                    )
                });
                verify_user_macro_artifact_memo(cached, &fresh);
            },
        )?;
    let prepared = prepare_user_macro_value(
        UserMacroPreparedRequest {
            macro_name: name,
            purpose: UserMacroPreparedPurpose::Template,
            macro_module,
        },
        tcx.env,
        artifact_pair.as_ref(),
        &tcx.env.memo,
        crate::timing::user_macro_frontend_enabled(),
    )?;
    let eval_metrics = crate::timing::user_macro_frontend_enabled()
        .then(crate::normalization::EvalMetrics::collect);
    let mut ctx = user_macro_eval_ctx_from_artifact(&artifact_pair)
        .with_fn_closure_cache(prepared.fn_closure_cache.clone())
        .with_eval_function_cache(prepared.eval_function_cache.clone())
        .with_type_view_cache(prepared.type_view_cache.clone())
        .with_exact_call_memo_cache(prepared.exact_call_memo_cache.clone());
    if let Some(metrics) = &eval_metrics {
        ctx = ctx.with_metrics(metrics.clone());
    }
    let eval_start = crate::timing::user_macro_frontend_enabled().then(Instant::now);
    #[cfg(test)]
    tcx.env
        .memo
        .record_user_macro_template_execution(&macro_module_path, name);
    let returned = crate::normalization::apply(prepared.value.clone(), vec![packet], &ctx);
    if let Some(eval_start) = eval_start {
        tcx.env
            .memo
            .record_user_macro_template_eval(eval_start.elapsed());
        if let Some(metrics) = eval_metrics {
            tcx.env
                .memo
                .record_user_macro_eval_metrics(metrics.snapshot());
        }
    }
    if let Some(fault) = crate::normalization::comptime_fault(&returned, &ctx) {
        return Err(fault.into_error(span));
    }
    Ok(returned)
}

/// Position-keyed index of the typer's output. For every expression
/// node the typer visits in `Lowered` mode, records the synthesized
/// type keyed by the node's source span; for every identifier
/// reference the typer resolves (the head segment of an
/// `Expr::Path`), records the resolution target keyed by the segment's
/// span.
///
/// The keying contract:
///
/// - Both maps are keyed by `(module_path, span)` — the slash module
///   path (`prog/util`) plus the file-local byte span. Module path
///   is load-bearing: spans are file-local byte offsets and collide
///   across modules of the same package, so keying by span alone
///   picks up a sibling module's entry at the same byte offset and
///   returns the wrong type / binder.
/// - Checked copies may share source spans. Expression observations retain
///   the existing source-ordered refinement rule; inferred call arguments
///   retain their distinct occurrence and application-stage owners until
///   presentation coalesces equivalent complete observations.
///
/// Some types the typer constructs have no source span — synthesized
/// fresh metavariables, desugared intermediates, intrinsic call
/// arguments materialised inside an elaboration. Those entries skip
/// the index by virtue of the recording sites not firing for them;
/// downstream queries either find the enclosing expression's entry
/// or fall through cleanly.
#[derive(Debug, Default, Clone)]
pub struct PositionIndex {
    /// Per-expression-node synthesized type and local declaration's bound
    /// type. Expression types are recorded at every
    /// `synth_expr` return in `Lowered` mode — the type is the
    /// **post-macro** synthesized type, so hover-on-`into(e, T)`
    /// shows `T` rather than `e`'s pre-coerced type.
    types: HashMap<(String, Span), Type>,
    /// Keys whose recorded type carries identity-canonical nominal heads.
    /// Kept beside the structural AST so editor rendering can distinguish a
    /// canonical module path from a source-written qualified import alias.
    canonical_types: HashSet<(String, Span)>,
    type_binders: HashMap<(String, Span), TypeBinderScope>,
    binder_presentations: Vec<std::sync::Arc<crate::pass::binder_presentation::BinderPresentation>>,
    /// Per-path-segment resolved binder. Recorded at every
    /// `synth_path` resolution — the head segment's span maps to
    /// what it resolves to (local, fn, host fn, intrinsic, …).
    /// Two-segment and three-segment paths record additional
    /// entries for their downstream segments (e.g. `Foo.mk_foo`
    /// records `Foo` as a newtype and `mk_foo` as a newtype
    /// constructor).
    binders: HashMap<(String, Span), ResolvedBinder>,
    /// Source-written declaration entries among `binders`. Local and
    /// type-parameter entries may need exact name-span remapping; top-level
    /// items and qualified-import aliases already carry exact token spans.
    binder_declarations: HashSet<(String, Span)>,
    /// Exact declaration sites for top-level semantic identities and
    /// module-local qualified-import aliases. Focused LSP analysis may retain
    /// a remote declaration here without publishing the provider's unrelated
    /// positions through `binders`.
    declaration_sites: HashMap<DeclarationIdentity, (String, Span)>,
    /// Name-based declaration fallback for local / type-parameter occurrences
    /// without a declaration span. Exact lexical identities use the span
    /// carried by each binder and the separate `local_decls_by_span` index.
    local_decls: HashMap<(String, String), Span>,
    local_decls_by_span: HashMap<(String, Span), String>,
    /// Inferred type for each unannotated `let` binder, keyed by the
    /// binder's own source span inside its module.
    inlay_let_types: HashMap<(String, Span), (Type, TypeBinderScope)>,
    /// Inferred type arguments for a call, keyed by a zero-width span
    /// at the callee's end inside its module.
    inlay_type_args: HashMap<(String, Span), Vec<InlayTypeArguments>>,
    #[cfg(feature = "lsp")]
    refactoring: Option<Box<refactoring_facts::RefactoringFacts>>,
    #[cfg(feature = "lsp")]
    call_presentations: Option<Box<CallPresentations>>,
}

/// Source correspondence for an already selected public-type value packet.
/// Declaration spelling is used only by the editor's subsequent display projection.
#[cfg(feature = "lsp")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CallValueProjection {
    Range { first: usize, width: usize },
    Tail { first: usize },
}

#[cfg(feature = "lsp")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CallArgumentRole {
    Type,
    Value(CallValueProjection),
}

#[cfg(feature = "lsp")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct CallLayerPresentation {
    pub(crate) has_value_layer: bool,
    pub(crate) consumed: bool,
    pub(crate) implicit_unit: bool,
}

#[cfg(feature = "lsp")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CallPresentationFact {
    Layer(CallLayerPresentation),
    Argument { span: Span, role: CallArgumentRole },
}

#[cfg(feature = "lsp")]
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub(crate) struct CallPresentationLayer {
    pub(crate) layer: Option<CallLayerPresentation>,
    pub(crate) arguments: std::collections::BTreeMap<(u32, u32), CallArgumentRole>,
    ambiguous: bool,
}

#[cfg(feature = "lsp")]
type CallPresentationLayers = std::collections::BTreeMap<usize, CallPresentationLayer>;
#[cfg(feature = "lsp")]
type CallPresentations = HashMap<
    String,
    HashMap<Span, HashMap<crate::ast::ExpressionOccurrenceId, CallPresentationLayers>>,
>;

#[cfg(all(test, feature = "lsp"))]
thread_local! {
    static SIGNATURE_CALL_OBSERVATIONS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(all(test, feature = "lsp"))]
pub(crate) fn take_signature_call_observations() -> usize {
    SIGNATURE_CALL_OBSERVATIONS.with(|count| count.replace(0))
}

#[derive(Debug, Clone)]
pub(crate) struct InlayTypeArguments {
    pub(crate) call_site: crate::ast::ExpressionSite,
    pub(crate) slot_offset: usize,
    pub(crate) types: Vec<Type>,
    pub(crate) binders: TypeBinderScope,
}

/// What a path segment resolves to, as recorded in
/// [`PositionIndex::binders`]. Each variant carries enough
/// information for an LSP `goto-definition` / `references` query to
/// find the declaration site and the set of use sites.
///
/// Path variants mirror [`crate::pass::typecheck_core::synth_path`]. Contextual
/// trailing labels are published from the validated source declaration scope
/// after checking, before the editor snapshot becomes visible.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ResolvedBinder {
    /// A continuation label belongs to one descriptor of the selected
    /// macro, independently of another declaration's label spelling.
    BlockLabel {
        module_path: String,
        macro_name: String,
        ordinal: usize,
        name: String,
        exposure: crate::ast::BlockExposure,
    },
    /// A local binding — `let x = e;` or a `fn` value parameter.
    /// The declaration site is the
    /// binding's own span, which the LSP recovers by walking the
    /// containing `FnDef` body.
    Local {
        name: String,
        decl_span: Option<Span>,
    },
    /// A type parameter `[A]` introduced by a `fn`, `fn`, or
    /// `alias`. Treated as a rigid type variable; the declaration
    /// site is the binder's span on the enclosing signature.
    TypeParam {
        name: String,
        decl_span: Option<Span>,
    },
    /// A top-level `fn` declared in this module or imported from a
    /// sibling module via `import m(foo);`. `module_path` names
    /// the source module so cross-module goto-definition can hop
    /// across files; `name` is the fn's identifier.
    Fn { module_path: String, name: String },
    /// A host fn. The declaration lives in the root module
    /// env or the package file's env; the LSP composes `module_path`
    /// with `name` to find it.
    HostEnvFn { module_path: String, name: String },
    /// One of the eight value intrinsics (`__left__`,
    /// `__right__`, `__either__`, `__pair__`, `__fst__`,
    /// `__snd__`, `__if_then_else__`, `__absurd__`). Intrinsics have
    /// no source declaration — goto-definition for one of these is a
    /// no-op (or a link to the spec).
    Intrinsic { name: String },
    /// A transparent `type` declaration referenced in type position.
    TypeAlias { module_path: String, name: String },
    /// A host-provided nominal type referenced in type position.
    HostType { module_path: String, name: String },
    /// A `newtype` declaration — either same-module or imported
    /// via `import m(Foo);`. Records
    /// just the head segment for two-segment paths like
    /// `Foo.mk_foo`; the member segment gets its own entry
    /// (`NewtypeMember`).
    Newtype { module_path: String, name: String },
    /// The `.<member>` tail of a two-segment newtype path:
    /// `Foo.mk_foo` records `Foo` as `Newtype` and `mk_foo` as
    /// `NewtypeMember`. The LSP composes the parent newtype's
    /// `(module_path, name)` with this segment's `member` to find
    /// the constructor / projector declaration.
    NewtypeMember {
        module_path: String,
        newtype: String,
        member: String,
    },
    /// A qualified-import alias — `import pkg/helper as h;` registers
    /// `h` mapped to a target module; the head segment of `h.foo`
    /// resolves here. The member segment records the semantic target
    /// (`Fn`, `HostEnvFn`, or `NewtypeMember`) so its identity matches a
    /// selective import or an unqualified reference to the same declaration.
    QualifiedImport { alias: String },
    /// Legacy/manual index representation for a qualified member. Ordinary
    /// typer publication canonicalizes such leaves to their semantic target;
    /// this variant remains for consumers that construct an index directly.
    QualifiedImportMember { alias: String, member: String },
}

#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
enum DeclarationIdentity {
    BlockLabel {
        module_path: String,
        macro_name: String,
        ordinal: usize,
    },
    Fn {
        module_path: String,
        name: String,
    },
    HostFn {
        module_path: String,
        name: String,
    },
    TypeAlias {
        module_path: String,
        name: String,
    },
    HostType {
        module_path: String,
        name: String,
    },
    Newtype {
        module_path: String,
        name: String,
    },
    NewtypeMember {
        module_path: String,
        newtype: String,
        member: String,
    },
    QualifiedImport {
        module_path: String,
        alias: String,
    },
}

impl DeclarationIdentity {
    fn from_binder(binder: &ResolvedBinder) -> Option<Self> {
        match binder {
            ResolvedBinder::BlockLabel {
                module_path,
                macro_name,
                ordinal,
                ..
            } => Some(Self::BlockLabel {
                module_path: module_path.clone(),
                macro_name: macro_name.clone(),
                ordinal: *ordinal,
            }),
            ResolvedBinder::Fn { module_path, name } => Some(Self::Fn {
                module_path: module_path.clone(),
                name: name.clone(),
            }),
            ResolvedBinder::HostEnvFn { module_path, name } => Some(Self::HostFn {
                module_path: module_path.clone(),
                name: name.clone(),
            }),
            ResolvedBinder::TypeAlias { module_path, name } => Some(Self::TypeAlias {
                module_path: module_path.clone(),
                name: name.clone(),
            }),
            ResolvedBinder::HostType { module_path, name } => Some(Self::HostType {
                module_path: module_path.clone(),
                name: name.clone(),
            }),
            ResolvedBinder::Newtype { module_path, name } => Some(Self::Newtype {
                module_path: module_path.clone(),
                name: name.clone(),
            }),
            ResolvedBinder::NewtypeMember {
                module_path,
                newtype,
                member,
            } => Some(Self::NewtypeMember {
                module_path: module_path.clone(),
                newtype: newtype.clone(),
                member: member.clone(),
            }),
            ResolvedBinder::Local { .. }
            | ResolvedBinder::TypeParam { .. }
            | ResolvedBinder::Intrinsic { .. }
            | ResolvedBinder::QualifiedImport { .. }
            | ResolvedBinder::QualifiedImportMember { .. } => None,
        }
    }

    fn from_occurrence(module_path: &str, binder: &ResolvedBinder) -> Option<Self> {
        match binder {
            ResolvedBinder::QualifiedImport { alias } => Some(Self::QualifiedImport {
                module_path: module_path.to_owned(),
                alias: alias.clone(),
            }),
            _ => Self::from_binder(binder),
        }
    }
}

impl PositionIndex {
    pub fn new() -> Self {
        Self::default()
    }

    /// Record `ty` as the synthesized type at `span` inside
    /// `module_path`. Overwrites any prior entry at the same key —
    /// re-visiting an expression with a refined type (e.g., a
    /// elaboration replacing the inner type with the
    /// elaborated target) is intentional, and the merge contract
    /// covers parallel walks separately. See [`Self::merge`].
    pub fn record_type(&mut self, module_path: &str, span: Span, ty: Type) {
        let key = (module_path.to_owned(), span);
        #[cfg(feature = "lsp")]
        self.observe_type(&key, &ty, false, None);
        self.canonical_types.remove(&key);
        self.type_binders.remove(&key);
        self.types.insert(key, ty);
    }

    pub(crate) fn record_type_with_identity(
        &mut self,
        module_path: &str,
        span: Span,
        ty: InternedType,
        binders: impl Into<TypeBinderScope>,
    ) {
        let key = (module_path.to_owned(), span);
        let binders = binders.into();
        #[cfg(feature = "lsp")]
        self.observe_type(&key, &ty, ty.identity_is_canonical(), Some(&binders));
        if ty.identity_is_canonical() {
            self.canonical_types.insert(key.clone());
        } else {
            self.canonical_types.remove(&key);
        }
        self.type_binders.insert(key.clone(), binders);
        self.types.insert(key, ty.clone_type());
    }

    pub fn type_identity_is_canonical(&self, module_path: &str, span: Span) -> bool {
        self.canonical_types
            .contains(&(module_path.to_owned(), span))
    }

    pub fn type_binders_at(&self, module_path: &str, span: Span) -> Option<HashSet<String>> {
        self.type_binders
            .get(&(module_path.to_owned(), span))
            .map(TypeBinderScope::names)
    }

    /// Look up the recorded type at `span` inside `module_path`,
    /// if any.
    pub fn type_at(&self, module_path: &str, span: Span) -> Option<&Type> {
        self.types.get(&(module_path.to_owned(), span))
    }

    /// Record `binder` as the resolution of the path segment at
    /// `span` inside `module_path`. Overwrites prior entries —
    /// see [`Self::record_type`] for the rationale.
    pub fn record_binder(&mut self, module_path: &str, span: Span, binder: ResolvedBinder) {
        let key = (module_path.to_owned(), span);
        #[cfg(feature = "lsp")]
        self.observe_binder(&key, &binder);
        self.binders.insert(key, binder);
    }

    pub(crate) fn record_binder_declaration(
        &mut self,
        module_path: &str,
        span: Span,
        binder: ResolvedBinder,
    ) {
        self.record_declaration_site_only(module_path, span, &binder);
        let key = (module_path.to_owned(), span);
        #[cfg(feature = "lsp")]
        self.observe_binder(&key, &binder);
        self.binders.insert(key.clone(), binder);
        self.binder_declarations.insert(key);
    }

    /// Retain a declaration target without adding a source occurrence to the
    /// position map. Focused analysis uses this for remote providers:
    /// goto-definition needs the exact site, while references, highlights,
    /// and rename must remain limited to the focused shard.
    pub(crate) fn record_declaration_site_only(
        &mut self,
        module_path: &str,
        span: Span,
        binder: &ResolvedBinder,
    ) {
        if let Some(identity) = DeclarationIdentity::from_occurrence(module_path, binder) {
            self.declaration_sites
                .insert(identity, (module_path.to_owned(), span));
        }
    }

    #[cfg(feature = "lsp")]
    pub(crate) fn declaration_site(&self, binder: &ResolvedBinder) -> Option<(&str, Span)> {
        let identity = DeclarationIdentity::from_binder(binder)?;
        self.declaration_sites
            .get(&identity)
            .map(|(module_path, span)| (module_path.as_str(), *span))
    }

    /// Resolve the exact source declaration for a binder occurrence.
    /// Top-level identities use the package-wide declaration index; locals
    /// and type parameters carry their lexical declaration span and remain
    /// scoped to the module containing the occurrence.
    #[cfg(feature = "lsp")]
    pub(crate) fn semantic_declaration_site<'a>(
        &'a self,
        occurrence_module_path: &'a str,
        binder: &ResolvedBinder,
    ) -> Option<(&'a str, Span)> {
        match binder {
            ResolvedBinder::Local { name, decl_span }
            | ResolvedBinder::TypeParam { name, decl_span } => {
                let span =
                    decl_span.or_else(|| self.local_decl_at(occurrence_module_path, name))?;
                Some((occurrence_module_path, span))
            }
            ResolvedBinder::QualifiedImport { .. } => {
                let identity =
                    DeclarationIdentity::from_occurrence(occurrence_module_path, binder)?;
                self.declaration_sites
                    .get(&identity)
                    .map(|(module_path, span)| (module_path.as_str(), *span))
            }
            _ => self.declaration_site(binder),
        }
    }

    /// Return one representative binder for every top-level semantic identity
    /// referenced by this shard whose exact declaration site is not present.
    /// Focused LSP analysis uses this bounded projection to fetch only the
    /// remote declarations needed by the focused module.
    #[cfg(feature = "lsp")]
    pub(crate) fn try_missing_declaration_site_binders(
        &self,
        mut is_cancelled: impl FnMut() -> bool,
    ) -> Option<Vec<ResolvedBinder>> {
        let mut missing = std::collections::BTreeMap::new();
        for binder in self.binders.values() {
            if is_cancelled() {
                return None;
            }
            let Some(identity) = DeclarationIdentity::from_binder(binder) else {
                continue;
            };
            if !self.declaration_sites.contains_key(&identity) {
                missing.entry(identity).or_insert_with(|| binder.clone());
            }
        }
        Some(missing.into_values().collect())
    }

    pub(crate) fn binder_at(&self, module_path: &str, span: Span) -> Option<&ResolvedBinder> {
        self.binders.get(&(module_path.to_owned(), span))
    }

    /// Record the local declaration with its exact lexical span, retaining
    /// a module-and-name fallback for occurrences without that span.
    pub fn record_local_decl(&mut self, module_path: &str, name: &str, span: Span) {
        self.record_local_decl_with_binder(
            module_path,
            name,
            span,
            ResolvedBinder::Local {
                name: name.to_owned(),
                decl_span: Some(span),
            },
        );
    }

    pub(crate) fn record_local_decl_with_binder(
        &mut self,
        module_path: &str,
        name: &str,
        span: Span,
        binder: ResolvedBinder,
    ) {
        self.record_binder_declaration(module_path, span, binder);
        self.local_decls
            .insert((module_path.to_owned(), name.to_owned()), span);
        self.local_decls_by_span
            .insert((module_path.to_owned(), span), name.to_owned());
    }

    pub fn record_inlay_let_type(
        &mut self,
        module_path: &str,
        name_span: Span,
        ty: Type,
        binders: TypeBinderScope,
    ) {
        self.inlay_let_types
            .insert((module_path.to_owned(), name_span), (ty, binders));
    }

    pub fn record_inlay_type_args(
        &mut self,
        module_path: &str,
        call_site: crate::ast::ExpressionSite,
        callee_end: Span,
        slot_offset: usize,
        types: Vec<Type>,
        binders: TypeBinderScope,
    ) {
        let groups = self
            .inlay_type_args
            .entry((module_path.to_owned(), callee_end))
            .or_default();
        let entry = InlayTypeArguments {
            call_site,
            slot_offset,
            types,
            binders,
        };
        if let Some(previous) = groups
            .iter_mut()
            .find(|group| group.call_site.id == call_site.id && group.slot_offset == slot_offset)
        {
            *previous = entry;
        } else {
            groups.push(entry);
        }
    }

    #[cfg(feature = "lsp")]
    pub(crate) fn record_call_presentation(
        &mut self,
        module_path: &str,
        call_site: crate::ast::ExpressionSite,
        slot_offset: usize,
        fact: CallPresentationFact,
    ) {
        let layer = self
            .call_presentations
            .get_or_insert_with(Default::default)
            .entry(module_path.to_owned())
            .or_default()
            .entry(call_site.span)
            .or_default()
            .entry(call_site.id)
            .or_default()
            .entry(slot_offset)
            .or_default();
        match fact {
            CallPresentationFact::Layer(value) => {
                layer.ambiguous |= layer.layer.is_some_and(|previous| previous != value);
                layer.layer = Some(value);
            }
            CallPresentationFact::Argument { span, role } => {
                layer.ambiguous |= layer
                    .arguments
                    .insert((span.start, span.end), role)
                    .is_some_and(|previous| previous != role);
            }
        }
    }

    /// Recover written operand boundaries after the checker selects one product packet.
    #[cfg(feature = "lsp")]
    pub(crate) fn reconcile_call_presentations(
        &mut self,
        module_path: &str,
        written: impl FnOnce() -> HashMap<Span, Vec<Span>>,
    ) {
        let Some(calls) = self
            .call_presentations
            .as_mut()
            .and_then(|all| all.get_mut(module_path))
        else {
            return;
        };
        let written = written();
        calls.retain(|span, occurrences| {
            let Some(values) = written.get(span) else {
                return false;
            };
            let mut original = occurrences.values();
            if let Some(first) = original.next()
                && original.any(|other| other != first)
            {
                return true;
            }
            if values.len() > 1 {
                for layers in occurrences.values_mut() {
                    for layer in layers.values_mut() {
                        let packet = {
                            let mut selected =
                                layer
                                    .arguments
                                    .iter()
                                    .filter_map(|(span, role)| match role {
                                        CallArgumentRole::Value(projection) => {
                                            Some((*span, *projection))
                                        }
                                        CallArgumentRole::Type => None,
                                    });
                            match (selected.next(), selected.next()) {
                                (Some((span, CallValueProjection::Tail { first: 0 })), None) => {
                                    span
                                }
                                _ => continue,
                            }
                        };
                        layer.arguments.remove(&packet);
                        for (index, value) in values.iter().enumerate() {
                            let projection = if index + 1 == values.len() {
                                CallValueProjection::Tail { first: index }
                            } else {
                                CallValueProjection::Range {
                                    first: index,
                                    width: 1,
                                }
                            };
                            let role = CallArgumentRole::Value(projection);
                            layer.ambiguous |= layer
                                .arguments
                                .insert((value.start, value.end), role)
                                .is_some_and(|previous| previous != role);
                        }
                    }
                }
            }
            true
        });
    }

    /// A lookup visits only occurrences of this source call. Cloned source
    /// must agree completely before an editor can present one argument plan.
    #[cfg(feature = "lsp")]
    pub(crate) fn call_presentation(
        &self,
        module_path: &str,
        span: Span,
    ) -> Option<&CallPresentationLayers> {
        let occurrences = self
            .call_presentations
            .as_ref()?
            .get(module_path)?
            .get(&span)?;
        let mut observations = occurrences.values();
        let first = observations.next()?;
        #[cfg(test)]
        SIGNATURE_CALL_OBSERVATIONS.with(|count| count.set(count.get() + 1));
        if first
            .values()
            .any(|layer| layer.ambiguous || layer.layer.is_none())
            || observations.any(|other| {
                #[cfg(test)]
                SIGNATURE_CALL_OBSERVATIONS.with(|count| count.set(count.get() + 1));
                other != first
            })
        {
            return None;
        }
        Some(first)
    }

    #[cfg(all(test, feature = "lsp"))]
    pub(crate) fn call_presentation_counts(&self) -> Option<[usize; 5]> {
        let modules = self.call_presentations.as_ref()?;
        let mut counts = [modules.len(), 0, 0, 0, 0];
        for calls in modules.values() {
            counts[1] += calls.len();
            for occurrences in calls.values() {
                counts[2] += occurrences.len();
                for layers in occurrences.values() {
                    counts[3] += layers.len();
                    counts[4] += layers
                        .values()
                        .map(|layer| layer.arguments.len())
                        .sum::<usize>();
                }
            }
        }
        Some(counts)
    }

    /// Look up the declaration span of the local / type-parameter
    /// named `name` declared in `module_path`, if recorded.
    pub fn local_decl_at(&self, module_path: &str, name: &str) -> Option<Span> {
        self.local_decls
            .get(&(module_path.to_owned(), name.to_owned()))
            .copied()
    }

    pub fn local_decls_iter(&self) -> impl Iterator<Item = (&(String, Span), &String)> {
        self.local_decls_by_span.iter()
    }

    /// Number of recorded type entries — useful for tests and
    /// memory-cost measurement.
    pub fn type_count(&self) -> usize {
        self.types.len()
    }

    /// Number of recorded binder entries.
    pub fn binder_count(&self) -> usize {
        self.binders.len()
    }

    /// Iterate over every recorded type entry as `((module_path,
    /// span), ty)`. Scanned for entries that intersect a cursor
    /// position by the REPL expr-query path and LSP hover.
    pub fn types_iter(&self) -> impl Iterator<Item = (&(String, Span), &Type)> {
        self.types.iter()
    }

    /// Iterate over every recorded binder entry. See
    /// [`Self::types_iter`].
    pub fn binders_iter(&self) -> impl Iterator<Item = (&(String, Span), &ResolvedBinder)> {
        self.binders.iter()
    }

    #[cfg(feature = "lsp")]
    pub(crate) fn declaration_binders_iter(
        &self,
    ) -> impl Iterator<Item = (&(String, Span), &ResolvedBinder)> {
        self.binders
            .iter()
            .filter(|(key, _)| self.binder_declarations.contains(*key))
    }

    #[cfg(feature = "lsp")]
    pub(crate) fn remap_local_declaration_spans(&mut self, remaps: &HashMap<(String, Span), Span>) {
        if remaps.is_empty() {
            return;
        }

        for ((module_path, _), binder) in &mut self.binders {
            let decl_span = match binder {
                ResolvedBinder::Local { decl_span, .. }
                | ResolvedBinder::TypeParam { decl_span, .. } => decl_span,
                _ => continue,
            };
            if let Some(exact) = decl_span
                .and_then(|span| remaps.get(&(module_path.clone(), span)))
                .copied()
            {
                *decl_span = Some(exact);
            }
        }

        for ((module_path, old_span), new_span) in remaps {
            let old_key = (module_path.clone(), *old_span);
            let new_key = (module_path.clone(), *new_span);
            self.remap_refactoring_position(&old_key, &new_key);
            if let Some(binder) = self.binders.remove(&old_key) {
                self.observe_binder(&new_key, &binder);
                self.binders.insert(new_key.clone(), binder);
            }
            if self.binder_declarations.remove(&old_key) {
                self.binder_declarations.insert(new_key.clone());
                if let Some(ty) = self.types.remove(&old_key) {
                    if self.refactoring.is_some() {
                        let scope = self.type_binders.get(&old_key).cloned();
                        self.observe_type(
                            &new_key,
                            &ty,
                            self.canonical_types.contains(&old_key),
                            scope.as_ref(),
                        );
                    }
                    self.types.insert(new_key.clone(), ty);
                }
                if self.canonical_types.remove(&old_key) {
                    self.canonical_types.insert(new_key.clone());
                }
                if let Some(binders) = self.type_binders.remove(&old_key) {
                    self.type_binders.insert(new_key.clone(), binders);
                }
            }
            if let Some(name) = self.local_decls_by_span.remove(&old_key) {
                let named_key = (module_path.clone(), name.clone());
                if self.local_decls.get(&named_key) == Some(old_span) {
                    self.local_decls.insert(named_key, *new_span);
                }
                self.local_decls_by_span.insert(new_key, name);
            }
        }
    }

    #[cfg(feature = "lsp")]
    pub(crate) fn remove_local_declaration_metadata<'a>(
        &mut self,
        declarations: impl Iterator<Item = (&'a str, Span)>,
    ) {
        let mut removed_by_module: HashMap<&str, HashSet<Span>> = HashMap::new();
        for (module_path, span) in declarations {
            let key = (module_path.to_owned(), span);
            self.invalidate_refactoring_position(&key);
            self.binders.remove(&key);
            self.binder_declarations.remove(&key);
            self.types.remove(&key);
            self.canonical_types.remove(&key);
            self.type_binders.remove(&key);
            self.local_decls_by_span.remove(&key);
            removed_by_module
                .entry(module_path)
                .or_default()
                .insert(span);
        }
        if removed_by_module.is_empty() {
            return;
        }
        self.local_decls.retain(|(owner, _), declaration| {
            !removed_by_module
                .get(owner.as_str())
                .is_some_and(|spans| spans.contains(declaration))
        });
    }

    #[cfg(feature = "lsp")]
    pub(crate) fn try_retain_binders(
        &mut self,
        mut retain: impl FnMut(&str, Span, &ResolvedBinder) -> Option<bool>,
    ) -> bool {
        let mut remove = Vec::new();
        for ((module_path, span), binder) in &self.binders {
            let Some(keep) = retain(module_path, *span, binder) else {
                return false;
            };
            if !keep {
                remove.push((module_path.clone(), *span));
            }
        }
        for key in remove {
            self.invalidate_refactoring_position(&key);
            self.binders.remove(&key);
        }
        let binders = &self.binders;
        let local_decls = &self.local_decls_by_span;
        self.binder_declarations
            .retain(|key| binders.contains_key(key) || local_decls.contains_key(key));
        true
    }

    pub fn inlay_let_types_iter(&self) -> impl Iterator<Item = (&(String, Span), &Type)> {
        self.inlay_let_types.iter().map(|(key, (ty, _))| (key, ty))
    }

    pub fn inlay_type_args_iter(&self) -> impl Iterator<Item = (&(String, Span), &[Type])> {
        self.inlay_type_args.iter().flat_map(|(key, groups)| {
            groups
                .iter()
                .map(move |group| (key, group.types.as_slice()))
        })
    }

    /// Merge `other` into `self`. Used by the per-fn-body parallel
    /// typer path: each fn body's walk produces its own
    /// `PositionIndex`, and the per-module merge folds them at the
    /// module boundary.
    ///
    /// Parser-issued spans are normally unique inside hand-written
    /// bodies, but generated / cloned bodies can reuse source spans.
    /// Expression entries refine repeated keys in source order. Parallel
    /// typing preserves that order by merging function shards in item order.
    /// Call-argument groups refine only the same occurrence and stage.
    pub fn merge(&mut self, other: PositionIndex) {
        #[cfg(feature = "lsp")]
        self.merge_refactoring_coverage(other.refactoring);
        #[cfg(feature = "lsp")]
        if let Some(modules) = other.call_presentations {
            for (module, calls) in *modules {
                for (span, occurrences) in calls {
                    for (id, layers) in occurrences {
                        for (slot_offset, layer) in layers {
                            let site = crate::ast::ExpressionSite { id, span };
                            if let Some(value) = layer.layer {
                                self.record_call_presentation(
                                    &module,
                                    site,
                                    slot_offset,
                                    CallPresentationFact::Layer(value),
                                );
                            }
                            for ((start, end), role) in layer.arguments {
                                self.record_call_presentation(
                                    &module,
                                    site,
                                    slot_offset,
                                    CallPresentationFact::Argument {
                                        span: Span::new(start, end),
                                        role,
                                    },
                                );
                            }
                            if layer.ambiguous {
                                self.call_presentations
                                    .as_mut()
                                    .unwrap()
                                    .get_mut(&module)
                                    .unwrap()
                                    .get_mut(&site.span)
                                    .unwrap()
                                    .get_mut(&id)
                                    .unwrap()
                                    .get_mut(&slot_offset)
                                    .unwrap()
                                    .ambiguous = true;
                            }
                        }
                    }
                }
            }
        }
        for presentation in other.binder_presentations {
            if !self
                .binder_presentations
                .iter()
                .any(|existing| std::sync::Arc::ptr_eq(existing, &presentation))
            {
                self.binder_presentations.push(presentation);
            }
        }
        for (key, ty) in other.types {
            #[cfg(feature = "lsp")]
            if self.refactoring.is_some() {
                self.observe_type(
                    &key,
                    &ty,
                    other.canonical_types.contains(&key),
                    other.type_binders.get(&key),
                );
            }
            if !other.canonical_types.contains(&key) {
                self.canonical_types.remove(&key);
            }
            if !other.type_binders.contains_key(&key) {
                self.type_binders.remove(&key);
            }
            self.types.insert(key, ty);
        }
        self.canonical_types.extend(other.canonical_types);
        self.type_binders.extend(other.type_binders);
        for (key, binder) in other.binders {
            #[cfg(feature = "lsp")]
            self.observe_binder(&key, &binder);
            self.binders.insert(key, binder);
        }
        self.binder_declarations.extend(other.binder_declarations);
        self.declaration_sites.extend(other.declaration_sites);
        for (key, span) in other.local_decls {
            self.local_decls.insert(key, span);
        }
        for (key, name) in other.local_decls_by_span {
            self.local_decls_by_span.insert(key, name);
        }
        for (key, ty) in other.inlay_let_types {
            self.inlay_let_types.insert(key, ty);
        }
        for ((module, end), groups) in other.inlay_type_args {
            for group in groups {
                self.record_inlay_type_args(
                    &module,
                    group.call_site,
                    end,
                    group.slot_offset,
                    group.types,
                    group.binders,
                );
            }
        }
    }

    pub(crate) fn present_binder_names(
        &mut self,
        presentation: std::sync::Arc<crate::pass::binder_presentation::BinderPresentation>,
    ) {
        for ((module_path, _), binder) in &mut self.binders {
            let (name, decl_span) = match binder {
                ResolvedBinder::Local {
                    name,
                    decl_span: Some(decl_span),
                }
                | ResolvedBinder::TypeParam {
                    name,
                    decl_span: Some(decl_span),
                } => (name, *decl_span),
                _ => continue,
            };
            presentation.present_name(module_path, decl_span, name);
        }

        for ((module_path, span), name) in &mut self.local_decls_by_span {
            presentation.present_name(module_path, *span, name);
        }
        self.binder_presentations.push(presentation);
    }
}

impl Elaborations {
    pub(crate) fn rec_loop_diagnostic_checkpoint(&self) -> usize {
        self.rec_loop_diagnostics
            .as_ref()
            .map_or(0, |records| records.len())
    }

    pub(crate) fn record_rec_loop_diagnostic(&mut self, source: &Expr, actual_type: &InternedType) {
        let Expr::Call {
            diagnostic, args, ..
        } = source
        else {
            return;
        };
        let (selected_path, escape_call) = match diagnostic {
            crate::ast::RecLoopDiagnostic::Loop { selected_path } => (*selected_path, None),
            crate::ast::RecLoopDiagnostic::Reentry {
                selected_path,
                escape_call,
            } => (*selected_path, Some(*escape_call)),
            _ => return,
        };
        fn result_sites(source: &Expr, sites: &mut Vec<crate::ast::ExpressionOccurrenceId>) {
            let Expr::Call {
                diagnostic: crate::ast::RecLoopDiagnostic::InitialStateResult,
                args,
                ..
            } = source
            else {
                return;
            };
            sites.push(source.site().id);
            for argument in args {
                if let CallArg::Value(value) = argument {
                    result_sites(value, sites);
                }
            }
        }
        let records = self
            .rec_loop_diagnostics
            .get_or_insert_with(Default::default);
        if records
            .iter()
            .any(|record| record.outer_call == source.site().id)
        {
            return;
        }
        let mut initial_result_sites = Vec::new();
        for argument in args {
            if let CallArg::Value(value) = argument {
                result_sites(value, &mut initial_result_sites);
            }
        }
        records.push(RecLoopDiagnosticRecord {
            outer_call: source.site().id,
            selected_path,
            escape_call,
            actual_type: actual_type.clone(),
            initial_result_sites,
            callee_binder_goals: Vec::new(),
        });
    }

    pub(crate) fn record_rec_loop_binder_goals(
        &mut self,
        call_site: crate::ast::ExpressionOccurrenceId,
        goals: impl Iterator<Item = crate::ast::TypeGoalRef>,
    ) {
        if let Some(records) = &mut self.rec_loop_diagnostics
            && let Some(record) = records
                .iter_mut()
                .find(|record| record.outer_call == call_site)
        {
            for goal in goals {
                if !record.callee_binder_goals.contains(&goal) {
                    record.callee_binder_goals.push(goal);
                }
            }
        }
    }

    pub(crate) fn finish_rec_loop_diagnostics<T>(
        &mut self,
        checkpoint: usize,
        result: Result<T, Error>,
    ) -> Result<T, Error> {
        use crate::error::{CallFailureOperation, TypeFailureOrigin};
        let result = result.map_err(|mut error| {
            if let Some(origin) = error.type_failure_origin()
                && let Some(records) = &self.rec_loop_diagnostics
                && let Some(record) = records[checkpoint..]
                    .iter()
                    .rev()
                    .find(|record| match origin {
                        TypeFailureOrigin::Application {
                            call_site,
                            operation,
                        } => {
                            record.outer_call == call_site
                                || (operation == CallFailureOperation::Result
                                    && record.initial_result_sites.contains(&call_site))
                        }
                        TypeFailureOrigin::UnresolvedGoal(goal) => {
                            record.callee_binder_goals.contains(&goal)
                        }
                    })
            {
                error = if let Some(escape_call) = record.escape_call {
                    error.with_rec_reentry_context(
                        record.selected_path,
                        escape_call,
                        &display_type(&record.actual_type),
                    )
                } else {
                    error.with_rec_loop_context(
                        record.selected_path,
                        &display_type(&record.actual_type),
                    )
                };
                if let Some(source) = record.actual_type.requirement_source() {
                    error = error.with_secondary_in_file(
                        source.file.clone(),
                        source.span,
                        "the selected loop's type is declared here",
                    );
                }
            }
            if checkpoint == 0 {
                error.clear_type_failure_origin();
            }
            error
        });
        if let Some(records) = &mut self.rec_loop_diagnostics {
            records.truncate(checkpoint);
        }
        result
    }

    pub fn new() -> Self {
        Self {
            rec_loop_diagnostics: None,
            rec_quote: None,
            entries: HashMap::new(),
            rec_order_runtime: HashMap::new(),
            type_resolutions: HashMap::new(),
            call_plans: HashMap::new(),
            literal_resolutions: HashMap::new(),
            primitive_values: HashMap::new(),
            comptime_literals: HashMap::new(),
            comptime_literal_names: HashMap::new(),
            fn_signature_types: HashMap::new(),
            generated_imports: HashMap::new(),
            prime_requalification_imports: HashMap::new(),
            generated_type_aliases: HashMap::new(),
            position_index: PositionIndex::new(),
            deferred: Vec::new(),
        }
    }

    #[cfg(test)]
    pub(crate) fn type_resolution_count(&self) -> usize {
        self.type_resolutions.len()
    }

    #[cfg(test)]
    pub(crate) fn call_plan_count(&self) -> usize {
        self.call_plans.len()
    }

    /// Read-only view of the position-keyed index. The LSP
    /// consumes this to answer hover / goto-definition / references
    /// queries. Elaboration validation also consults the ordinary path
    /// binder recorded here when a named implementation needs a
    /// declaration-visibility check.
    pub fn position_index(&self) -> &PositionIndex {
        &self.position_index
    }

    /// Consume `self` and return the position index. Used by the LSP
    /// analysis path (`check::analyze_workspace_at_with_overlay_lsp`)
    /// to extract the index for merging across packages without an
    /// extra clone.
    pub fn into_position_index(self) -> PositionIndex {
        self.position_index
    }

    pub(crate) fn present_binder_names(
        &mut self,
        presentation: std::sync::Arc<crate::pass::binder_presentation::BinderPresentation>,
    ) {
        self.position_index.present_binder_names(presentation);
    }

    /// Record `ty` as the synthesized type at `span` inside
    /// `module_path` in the position-keyed index. Delegates to
    /// [`PositionIndex::record_type`]; see the field doc for the
    /// keying contract.
    pub fn record_position_type(
        &mut self,
        module_path: &str,
        span: Span,
        ty: InternedType,
        binders: impl Into<TypeBinderScope>,
    ) {
        self.position_index
            .record_type_with_identity(module_path, span, ty, binders);
    }

    /// Record `binder` as the resolved binder at `span` inside
    /// `module_path` in the position-keyed index. Delegates to
    /// [`PositionIndex::record_binder`].
    pub fn record_position_binder(
        &mut self,
        module_path: &str,
        span: Span,
        binder: ResolvedBinder,
    ) {
        self.position_index.record_binder(module_path, span, binder);
    }

    /// Record the declaration span of a local / type-parameter binder
    /// in the position-keyed index. Delegates to
    /// [`PositionIndex::record_local_decl`].
    pub fn record_local_decl(
        &mut self,
        module_path: &str,
        name: &str,
        span: Span,
        binder: ResolvedBinder,
    ) {
        self.position_index
            .record_local_decl_with_binder(module_path, name, span, binder);
    }

    pub fn record_inlay_let_type(
        &mut self,
        module_path: &str,
        name_span: Span,
        ty: Type,
        binders: TypeBinderScope,
    ) {
        self.position_index
            .record_inlay_let_type(module_path, name_span, ty, binders);
    }

    pub fn record_inlay_type_args(
        &mut self,
        module_path: &str,
        call_site: crate::ast::ExpressionSite,
        callee_end: Span,
        slot_offset: usize,
        types: Vec<Type>,
        binders: TypeBinderScope,
    ) {
        self.position_index.record_inlay_type_args(
            module_path,
            call_site,
            callee_end,
            slot_offset,
            types,
            binders,
        );
    }

    /// Record the replacement tree for one NodeId-bearing Lowered expression.
    pub fn record_elaboration(&mut self, module_path: &str, original: &Expr, elaborated: Expr) {
        let id = elaboration_node_id(original)
            .expect("record_elaboration on an expression without a NodeId-backed replacement slot");
        self.entries.insert(
            (module_path.to_owned(), id),
            RecordedElaboration::Lowered(elaborated),
        );
    }

    pub(crate) fn record_rec_order_elaboration(
        &mut self,
        module_path: &str,
        original: &Expr,
        replacement: Expr,
        binding_type: InternedType,
    ) {
        assert!(
            matches!(original, Expr::RecOrder { .. }),
            "recursive-order elaboration must originate at a recursive-order carrier"
        );
        assert!(
            matches!(replacement, Expr::Let { ty: None, .. }),
            "runtime recursive-order replacement must leave its root let type to the paired artifact"
        );
        let id =
            elaboration_node_id(original).expect("recursive-order elaboration must have a node id");
        self.record_rec_order_runtime(module_path, id, replacement, binding_type);
    }

    fn record_rec_order_runtime(
        &mut self,
        module_path: &str,
        node_id: NodeId,
        replacement: Expr,
        binding_type: InternedType,
    ) {
        assert!(
            matches!(replacement, Expr::Let { ty: None, .. }),
            "runtime recursive-order replacement must leave its root let type to the paired artifact"
        );
        self.rec_order_runtime.insert(
            (module_path.to_owned(), node_id),
            RecordedRecOrderRuntime {
                replacement,
                binding_type: binding_type.into(),
            },
        );
    }

    fn record_unchecked_prime_elaboration(
        &mut self,
        module_path: &str,
        node_id: NodeId,
        elaborated: UncheckedPrimeExpr,
        primitives: Option<std::sync::Arc<crate::normalization::EvalPrimitiveEnv>>,
    ) {
        self.entries.insert(
            (module_path.to_owned(), node_id),
            RecordedElaboration::UncheckedPrime {
                expression: elaborated,
                primitives,
            },
        );
    }

    /// Look up a replacement by its module and expression identity.
    pub fn elaboration_for(
        &self,
        module_path: &str,
        original: &Expr,
    ) -> Option<&RecordedElaboration> {
        self.entries
            .get(&(module_path.to_owned(), elaboration_node_id(original)?))
    }

    pub(crate) fn rec_order_runtime_for(
        &self,
        module_path: &str,
        original: &Expr,
    ) -> Option<(&Expr, &RecordedTypeResolution)> {
        let recorded = self
            .rec_order_runtime
            .get(&(module_path.to_owned(), elaboration_node_id(original)?))?;
        Some((&recorded.replacement, &recorded.binding_type))
    }

    /// Enqueue either closed-result glue production or an already-computed
    /// type-producing template for module-boundary recording. See
    /// [`DeferredElaboration`] and the `deferred` field documentation.
    fn enqueue_deferred(&mut self, obligation: DeferredElaboration) {
        self.deferred.push(obligation);
    }

    /// Drain the deferred-elaboration queue for the module the typer just
    /// finished and record each Kio' glue tree under the surface node's
    /// `NodeId`. Runs at the per-module boundary (from the `Typer<Lowered>`
    /// impl), where the module's alias context is still live. A closed-result
    /// obligation evaluates its template here and compares the returned
    /// checked-term type with `result_ty`; an obligation whose template was
    /// evaluated on the live frontier replays that result directly.
    ///
    /// Dedupe-keyed: the per-key cache means two obligations naming the
    /// same `(kind, source, target)` elaboration run the producer once.
    fn discharge_deferred(
        &mut self,
        env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
    ) -> Result<(), Error> {
        self.discharge_deferred_with_execution(env, env.typecheck_execution())
    }

    fn discharge_deferred_with_execution(
        &mut self,
        env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
        execution: crate::pass::typecheck_core::TypecheckExecution,
    ) -> Result<(), Error> {
        if self.deferred.is_empty() {
            return rec_quote::finish_expansions(self, env);
        }
        let memo = &env.memo;
        let obligations = std::mem::take(&mut self.deferred);
        let mut user_macro_batch = Vec::new();
        for ob in obligations {
            match ob {
                DeferredElaboration::UserMacro(ob) => {
                    user_macro_batch.push(*ob);
                }
            }
        }
        self.discharge_user_macro_batch(&mut user_macro_batch, env, memo, execution)?;
        rec_quote::finish_expansions(self, env)
    }

    fn discharge_user_macro_batch(
        &mut self,
        obligations: &mut Vec<DeferredUserMacroElaboration>,
        env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
        memo: &crate::pass::typecheck_core::MemoCtx<Lowered>,
        execution: crate::pass::typecheck_core::TypecheckExecution,
    ) -> Result<(), Error> {
        if obligations.is_empty() {
            return Ok(());
        }
        let record_timing = crate::timing::user_macro_frontend_enabled();
        let elaborations: &Elaborations = self;
        let key_start = record_timing.then(Instant::now);
        let mut unique_by_key = HashMap::new();
        let mut unique = Vec::new();
        let mut obligation_unique_indices = Vec::with_capacity(obligations.len());
        for (ob_index, ob) in obligations.iter().enumerate() {
            if ob.precomputed_template.is_some() {
                obligation_unique_indices.push(None);
                continue;
            }
            let key = user_macro_template_memo_key(ob, env);
            let unique_index = if let Some(key) = key {
                match unique_by_key.get_key_value(&key) {
                    Some((stored, &index)) if key.reuse_matches(stored) => index,
                    existing => {
                        let index = unique.len();
                        if existing.is_none() {
                            unique_by_key.insert(key.clone(), index);
                        }
                        unique.push((ob_index, Some(key)));
                        index
                    }
                }
            } else {
                let index = unique.len();
                unique.push((ob_index, None));
                index
            };
            obligation_unique_indices.push(Some(unique_index));
        }
        if let Some(key_start) = key_start {
            memo.record_user_macro_template_batch_key(key_start.elapsed());
        }
        memo.record_user_macro_template_batch(obligations.len(), unique.len());
        let compute_start = record_timing.then(Instant::now);
        let mut computed: Vec<Option<Result<UserMacroTemplateResult, Error>>> =
            if unique.len() < USER_MACRO_PAR_BATCH_MIN || !execution.parallelizes(unique.len()) {
                unique
                    .iter()
                    .map(|(ob_index, key)| {
                        Some(compute_user_macro_deferred_template(
                            &obligations[*ob_index],
                            key.clone(),
                            env,
                            elaborations,
                            memo,
                        ))
                    })
                    .collect()
            } else {
                crate::maybe_par_iter!(&unique)
                    .map(|(ob_index, key)| {
                        Some(compute_user_macro_deferred_template(
                            &obligations[*ob_index],
                            key.clone(),
                            env,
                            elaborations,
                            memo,
                        ))
                    })
                    .collect()
            };
        if let Some(compute_start) = compute_start {
            memo.record_user_macro_template_batch_compute(compute_start.elapsed());
        }
        let replay_loop_start = record_timing.then(Instant::now);
        let obligations = std::mem::take(obligations);
        let mut replay_env = UserMacroReplayEnv {
            module_path: &env.module_path,
            module: env.module,
            elaborations: self,
            package: env.package,
            memo,
        };
        for (ob, unique_index) in obligations.into_iter().zip(obligation_unique_indices) {
            let elaborated = match (ob.precomputed_template.as_ref(), unique_index) {
                (Some(template), None) => user_macro_template_to_elaboration(
                    template,
                    UserMacroReplayInputs {
                        values: &ob.values,
                        value_adapter: Some(&ob.value_adapter),
                        residual_eta: Some(&ob.residual_abstraction),
                        ambient_type_names: &ob.ambient_type_names,
                        residual_reflection_bindings: &ob.residual_reflection_bindings,
                        capture_imports: &ob.capture_imports,
                        quoted: Some((ob.node_id, ob.quoted_public_recipe.as_deref())),
                    },
                    ob.span,
                    &mut replay_env,
                )?,
                (None, Some(unique_index)) => match computed[unique_index]
                    .as_ref()
                    .expect("unique macro template result missing")
                {
                    Ok(template) => user_macro_template_to_elaboration(
                        template,
                        UserMacroReplayInputs {
                            values: &ob.values,
                            value_adapter: Some(&ob.value_adapter),
                            residual_eta: Some(&ob.residual_abstraction),
                            ambient_type_names: &ob.ambient_type_names,
                            residual_reflection_bindings: &ob.residual_reflection_bindings,
                            capture_imports: &ob.capture_imports,
                            quoted: Some((ob.node_id, ob.quoted_public_recipe.as_deref())),
                        },
                        ob.span,
                        &mut replay_env,
                    )?,
                    Err(_) => {
                        return Err(computed[unique_index]
                            .take()
                            .expect("unique macro template result missing")
                            .expect_err("checked error arm above"));
                    }
                },
                _ => unreachable!("user macro precompute state and batch key disagree"),
            };
            if elaborated.computation {
                replay_env.elaborations.record_rec_quote_computation(
                    ob.node_id,
                    crate::ast::convert_expr::<UncheckedPrime, substitute::PrePrime>(
                        &elaborated.expression,
                    ),
                );
            } else {
                replay_env.elaborations.record_unchecked_prime_elaboration(
                    replay_env.module_path,
                    ob.node_id,
                    elaborated.expression,
                    elaborated.primitives,
                );
            }
        }
        if let Some(replay_loop_start) = replay_loop_start {
            memo.record_user_macro_template_batch_replay_loop(replay_loop_start.elapsed());
        }
        Ok(())
    }

    /// Record one solved type argument for this call instance's canonical slot.
    pub fn record_type_resolution(
        &mut self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
        slot_index: usize,
        resolved: InternedType,
    ) {
        self.type_resolutions.insert(
            (module_path.to_owned(), call_id, slot_index),
            resolved.into(),
        );
    }

    /// Look up the resolved type for a `Type::Infer` at slot
    /// `slot_index` of the call occurrence `call_id` inside
    /// module `module_path`. Every substitution route treats a missing
    /// resolution as a typer-pipeline invariant violation.
    pub(crate) fn type_resolution_for(
        &self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
        slot_index: usize,
    ) -> Option<&RecordedTypeResolution> {
        self.type_resolutions
            .get(&(module_path.to_owned(), call_id, slot_index))
    }

    pub fn record_call_split(
        &mut self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
        split_after_slot: usize,
    ) {
        let splits = &mut self
            .call_plans
            .entry((module_path.to_owned(), call_id))
            .or_default()
            .splits;
        match splits.binary_search(&split_after_slot) {
            Ok(_) => {}
            Err(index) => splits.insert(index, split_after_slot),
        }
    }

    pub(crate) fn record_macro_output_stage(
        &mut self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
        stage: usize,
    ) {
        let previous = self
            .call_plans
            .entry((module_path.to_owned(), call_id))
            .or_default()
            .macro_output_stage
            .replace(stage);
        assert!(
            previous.is_none_or(|previous| previous == stage),
            "a macro's public input boundary changed during checking"
        );
    }

    pub(crate) fn macro_output_stage_for(
        &self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
    ) -> Option<usize> {
        self.call_plans
            .get(&(module_path.to_owned(), call_id))?
            .macro_output_stage
    }

    pub fn call_splits_for(
        &self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
    ) -> Option<&[usize]> {
        self.call_plans
            .get(&(module_path.to_owned(), call_id))
            .map(|plan| plan.splits.as_slice())
            .filter(|splits| !splits.is_empty())
    }

    pub(crate) fn record_call_implicit_unit_slot(
        &mut self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
        slot_index: usize,
    ) {
        let slots = &mut self
            .call_plans
            .entry((module_path.to_owned(), call_id))
            .or_default()
            .implicit_unit_slots;
        match slots.binary_search(&slot_index) {
            Ok(_) => {}
            Err(index) => slots.insert(index, slot_index),
        }
    }

    pub(crate) fn call_implicit_unit_slots_for(
        &self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
    ) -> Option<&[usize]> {
        self.call_plans
            .get(&(module_path.to_owned(), call_id))
            .map(|plan| plan.implicit_unit_slots.as_slice())
            .filter(|slots| !slots.is_empty())
    }

    pub(crate) fn record_call_residual_eta_type(
        &mut self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
        residual: InternedType,
    ) {
        let previous = self
            .call_plans
            .entry((module_path.to_owned(), call_id))
            .or_default()
            .residual_eta_type
            .replace(residual.into());
        assert!(
            previous.is_none(),
            "one call committed more than one residual eta plan"
        );
    }

    /// Merge a plan from an independently checked clone of the same source
    /// call. Recursive-block lowering can place one cloned call in more than
    /// one local elaboration table; only structurally identical resolved
    /// types with identical identity state describe the same boundary
    /// rewrite. Local publication remains strict in
    /// [`Self::record_call_residual_eta_type`].
    fn merge_call_residual_eta_type(
        &mut self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
        residual: RecordedTypeResolution,
    ) {
        let recorded = &mut self
            .call_plans
            .entry((module_path.to_owned(), call_id))
            .or_default()
            .residual_eta_type;
        if let Some(previous) = recorded {
            assert!(
                previous.identity_canonical == residual.identity_canonical
                    && previous.resolved == residual.resolved,
                "cloned call sites produced divergent residual eta plans: {module_path} at \
                 {call_id:?}"
            );
        } else {
            *recorded = Some(residual);
        }
    }

    pub(crate) fn call_residual_eta_type_for(
        &self,
        module_path: &str,
        call_id: crate::ast::ExpressionOccurrenceId,
    ) -> Option<&RecordedTypeResolution> {
        self.call_plans
            .get(&(module_path.to_owned(), call_id))?
            .residual_eta_type
            .as_ref()
    }

    /// Record the typer's resolved host type for the literal at
    /// `literal_id` inside module `module_path` — the result of
    /// explicit annotation or contextual inference. The substitution pass bakes this
    /// into the literal's `annotation` so every post-`Prime`
    /// literal carries its concrete type. Module path keying is
    /// load-bearing — see the `literal_resolutions` field doc.
    pub fn record_literal_resolution(
        &mut self,
        module_path: &str,
        literal_id: crate::ast::ExpressionOccurrenceId,
        resolved: InternedType,
        numeric_value: Option<String>,
    ) {
        self.literal_resolutions.insert(
            (module_path.to_owned(), literal_id),
            (resolved.into(), numeric_value),
        );
    }

    /// Look up the typer's resolved type for the literal at
    /// `literal_id` inside module `module_path`.
    pub(crate) fn literal_resolution_for(
        &self,
        module_path: &str,
        literal_id: crate::ast::ExpressionOccurrenceId,
    ) -> Option<&(RecordedTypeResolution, Option<String>)> {
        self.literal_resolutions
            .get(&(module_path.to_owned(), literal_id))
    }

    pub(crate) fn replay_primitives_for(
        &self,
        module: &str,
    ) -> impl Iterator<Item = &crate::normalization::EvalPrimitiveEnv> {
        self.entries
            .iter()
            .filter_map(move |((owner, _), entry)| match entry {
                RecordedElaboration::UncheckedPrime {
                    primitives: Some(primitives),
                    ..
                } if owner == module => Some(primitives.as_ref()),
                _ => None,
            })
    }

    pub(crate) fn primitive_value_for(
        &self,
        module: &str,
        occurrence: crate::ast::ExpressionOccurrenceId,
    ) -> Option<&str> {
        self.primitive_values
            .get(&(module.to_owned(), occurrence))
            .map(String::as_str)
    }

    pub(crate) fn comptime_literal_for(
        &self,
        module: &str,
        occurrence: crate::ast::ExpressionOccurrenceId,
    ) -> Option<&ComptimeLiteralPlan> {
        self.comptime_literals.get(&(module.to_owned(), occurrence))
    }

    pub(crate) fn comptime_literals_for(
        &self,
        module: &str,
    ) -> impl Iterator<Item = &ComptimeLiteralPlan> {
        self.comptime_literals
            .iter()
            .filter_map(move |((owner, _), plan)| (owner == module).then_some(plan))
    }

    pub fn record_fn_param_type(
        &mut self,
        module_path: &str,
        fn_id: crate::ast::ExpressionOccurrenceId,
        value_param_index: usize,
        resolved: InternedType,
    ) {
        self.fn_signature_types.insert(
            (module_path.to_owned(), fn_id, Some(value_param_index)),
            resolved.into(),
        );
    }

    pub(crate) fn fn_param_type_for(
        &self,
        module_path: &str,
        fn_id: crate::ast::ExpressionOccurrenceId,
        value_param_index: usize,
    ) -> Option<&RecordedTypeResolution> {
        self.fn_signature_types
            .get(&(module_path.to_owned(), fn_id, Some(value_param_index)))
    }

    pub(crate) fn record_proof_fn_body_type(
        &mut self,
        module_path: &str,
        fn_id: crate::ast::ExpressionOccurrenceId,
        resolved: InternedType,
    ) {
        self.fn_signature_types
            .insert((module_path.to_owned(), fn_id, None), resolved.into());
    }

    pub(crate) fn proof_fn_body_type_for(
        &self,
        module_path: &str,
        fn_id: crate::ast::ExpressionOccurrenceId,
    ) -> Option<&RecordedTypeResolution> {
        self.fn_signature_types
            .get(&(module_path.to_owned(), fn_id, None))
    }

    pub fn generated_imports_for(&self, module_path: &str) -> &[UserMacroTemplateGeneratedImport] {
        self.generated_imports
            .get(module_path)
            .map(Vec::as_slice)
            .unwrap_or(&[])
    }

    fn record_generated_imports(
        &mut self,
        module_path: &str,
        imports: &[UserMacroTemplateGeneratedImport],
    ) {
        if imports.is_empty() {
            return;
        }
        let existing = self
            .generated_imports
            .entry(module_path.to_owned())
            .or_default();
        for import in imports {
            if !existing.iter().any(|item| item == import) {
                existing.push(import.clone());
            }
        }
    }

    pub(crate) fn prime_requalification_imports_for(
        &self,
        module_path: &str,
    ) -> &[UserMacroTemplateGeneratedImport] {
        self.prime_requalification_imports
            .get(module_path)
            .map(Vec::as_slice)
            .unwrap_or(&[])
    }

    pub(crate) fn record_prime_requalification_imports(
        &mut self,
        module_path: &str,
        imports: &[UserMacroTemplateGeneratedImport],
    ) {
        let existing = self
            .prime_requalification_imports
            .entry(module_path.to_owned())
            .or_default();
        for import in imports {
            if let Some(item) = existing.iter_mut().find(|item| item.alias == import.alias) {
                *item = import.clone();
            } else {
                existing.push(import.clone());
            }
        }
    }

    pub(crate) fn generated_type_aliases_for(&self, module_path: &str) -> &[PrimeLocalTypeAlias] {
        self.generated_type_aliases
            .get(module_path)
            .map(Vec::as_slice)
            .unwrap_or(&[])
    }

    pub(crate) fn record_generated_type_aliases(
        &mut self,
        module_path: &str,
        aliases: &[PrimeLocalTypeAlias],
    ) {
        let existing = self
            .generated_type_aliases
            .entry(module_path.to_owned())
            .or_default();
        for alias in aliases {
            if let Some(item) = existing.iter_mut().find(|item| item.alias == alias.alias) {
                *item = alias.clone();
            } else {
                existing.push(alias.clone());
            }
        }
    }

    pub fn merge(&mut self, other: Elaborations) {
        if let Some(other) = other.rec_quote {
            self.rec_quote
                .get_or_insert_with(Default::default)
                .merge(*other);
        }
        for (key, value) in other.entries {
            self.entries.insert(key, value);
        }
        for (key, value) in other.rec_order_runtime {
            self.rec_order_runtime.insert(key, value);
        }
        for (key, value) in other.type_resolutions {
            self.type_resolutions.insert(key, value);
        }
        for ((module_path, span), plan) in other.call_plans {
            for split_after_slot in plan.splits {
                self.record_call_split(&module_path, span, split_after_slot);
            }
            for slot_index in plan.implicit_unit_slots {
                self.record_call_implicit_unit_slot(&module_path, span, slot_index);
            }
            if let Some(residual) = plan.residual_eta_type {
                self.merge_call_residual_eta_type(&module_path, span, residual);
            }
            if let Some(stage) = plan.macro_output_stage {
                self.record_macro_output_stage(&module_path, span, stage);
            }
        }
        self.primitive_values.extend(other.primitive_values);
        self.comptime_literals.extend(other.comptime_literals);
        for (module, names) in other.comptime_literal_names {
            self.comptime_literal_names
                .entry(module)
                .or_default()
                .extend(names);
        }
        for (key, value) in other.literal_resolutions {
            self.literal_resolutions.insert(key, value);
        }
        for (key, value) in other.fn_signature_types {
            self.fn_signature_types.insert(key, value);
        }
        for (module_path, imports) in other.generated_imports {
            self.record_generated_imports(&module_path, &imports);
        }
        for (module_path, imports) in other.prime_requalification_imports {
            self.record_prime_requalification_imports(&module_path, &imports);
        }
        for (module_path, aliases) in other.generated_type_aliases {
            self.record_generated_type_aliases(&module_path, &aliases);
        }
        self.position_index.merge(other.position_index);
        self.deferred.extend(other.deferred);
    }
}

/// Pull the [`NodeId`] off a replacement-bearing `Expr` variant. Returns
/// `None` for variants without a keyed replacement.
fn elaboration_node_id(e: &Expr) -> Option<NodeId> {
    match e {
        Expr::RecOrder { ext, .. } | Expr::RecQuote { ext, .. } => Some(*ext),
        Expr::UserMacro { ext, .. } => Some(*ext),
        Expr::Ufcs { ext, .. } => match *ext {},
        _ => None,
    }
}

/// Type-check a normalized clone of one module in isolation. Unit-test helper
/// for cases that do not need package resolution.
#[cfg(test)]
fn check_module(module: &Module) -> Result<(), Error> {
    check_module_with_package_file(module, None, None)
}

#[cfg(test)]
fn check_module_with_package_file(
    module: &Module,
    package_file: Option<&PackageFile>,
    package_name: Option<&str>,
) -> Result<(), Error> {
    let module = crate::pass::alpha_normalize::normalize_module(module);
    let typecheck_scope =
        crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_standalone_module(
            &module,
            std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
        );
    let mut elabs = Elaborations::new();
    crate::pass::typecheck_core::check_module_in_package_with_typecheck_scope_collect_errors(
        module.module(),
        package_file,
        package_name,
        None,
        &mut elabs,
        typecheck_scope,
    )
    .map_err(|errors| {
        errors
            .into_iter()
            .next()
            .expect("collected isolated-module errors are non-empty")
    })
}

// The scoped per-module checker lives in `crate::pass::typecheck_core` so the
// standalone Kio'-only typer can drive the same loop at `P = Prime`.

// =========================================================================
// Module-level environment
// =========================================================================

// `ModuleEnv` (per-module typer environment) lives in
// `crate::pass::typecheck_core` as `ModuleEnv<'m, P>`. `typecheck_full`
// consumes it via the `<Lowered>`-pinned type alias above; the
// standalone Kio'-only walker in `crate::prime::typer` instantiates
// it at `<Prime>`. The `build`, `populate_env_imports`, and
// `populate_cross_module_imports` helpers live alongside it.

// =========================================================================
// Local context (per-fn)
// =========================================================================
//
// `Local<'m, P>` and `TypeCtx<'m, 'e, P: TyperPhase>` live in
// `crate::pass::typecheck_core`. `typecheck_full` consumes them via the
// `<Lowered>`-pinned type aliases above; the standalone Kio'-only
// walker in `crate::prime::typer` instantiates them at `<Prime>`.
// The shared TypeCtx threads a `&mut P::Elaborations`. Lowered uses the full
// surface-completion table; Prime uses its narrower call/lambda publication
// table. Each phase consumes its table before returning the next artifact.

// =========================================================================
// Scheme — the type of a polymorphic value
// =========================================================================
//
// `Synth` lives in `crate::pass::typecheck_core` as `Synth<P>`. Imported
// via the use clause at the top of this module.

// =========================================================================
// Per-fn check
// =========================================================================

// `check_fn_def` lives in `crate::pass::typecheck_core`. It threads the
// declared return type through `<P::Typer as Typer<P>>::check_value_against`,
// landing in this module's `LoweredTyper` impl at `P = Lowered` and
// in `prime::typer::PrimeTyper` at `P = Prime`. Imported via the
// use clause at the top of this module.

// =========================================================================
// Per-newtype check
// =========================================================================
//
// `check_newtype_payload` and `param_appears_negatively` are in
// `crate::pass::typecheck_core` and called inline by
// the shared per-module checker.
// `check_well_formed_type` lives there too.

// =========================================================================
// Expression synthesis
// =========================================================================

fn synth_rec_order<'m>(
    original: &'m Expr,
    plan: &'m RecOrderPlan<Lowered>,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<Synth, Error> {
    if crate::pass::typecheck_core::apply::is_rec_order_function_shell(plan)
        || matches!(
            plan.disposition,
            RecOrderDisposition::DeferredTail {
                requirement: crate::ast::RecOrderTailRequirement::Optional
                    | crate::ast::RecOrderTailRequirement::Escaping,
                ..
            }
        )
    {
        return crate::pass::typecheck_core::apply::run_general_ordinary_value(original, None, tcx);
    }
    let flow = match plan.disposition {
        RecOrderDisposition::Ordered(flow) => flow,
        RecOrderDisposition::DeferredTail { .. } => {
            return Err(deferred_rec_tail_error(
                plan.source_call.as_deref(),
                original.span(),
            ));
        }
    };
    let mark = tcx.save();
    let disposition = (|| match flow {
        RecOrderTypeFlow::ExpectedFromBody => {
            let pending = tcx.push_pending_rec_order(
                plan.name.clone(),
                plan.value.as_ref(),
                plan.value.span(),
            );
            let runtime_ty = tcx.intern_type(&plan.runtime_ty);
            check_value_against(&plan.body, &runtime_ty, tcx)?;
            match tcx.pending_rec_order_state(pending) {
                PendingRecOrderState::Runtime {
                    exact_ty,
                    source_checked,
                } => {
                    if !source_checked {
                        #[cfg(test)]
                        crate::pass::typecheck_core::apply::record_rec_order_source_span(
                            plan.value.span(),
                        );
                        check_value_against(&plan.value, &exact_ty, tcx)?;
                    }
                    Ok(PendingRecOrderState::Runtime {
                        exact_ty,
                        source_checked: true,
                    })
                }
                PendingRecOrderState::Pending => unreachable!(
                    "recursive ordering binder `{}` was not classified at its generated use site",
                    plan.name
                ),
            }
        }
        RecOrderTypeFlow::SynthesizedValue | RecOrderTypeFlow::ElaboratedValue => {
            let source_ty = crate::pass::typecheck_core::annotation_plan::synth_let_bound_type(
                plan.annotation.as_ref(),
                &plan.value,
                tcx,
            )?;
            let binding_ty = if flow == RecOrderTypeFlow::ElaboratedValue {
                tcx.intern_type(&plan.runtime_ty)
            } else {
                source_ty
            };
            tcx.push_value_interned(plan.name.clone(), binding_ty.clone());
            let runtime_ty = tcx.intern_type(&plan.runtime_ty);
            check_value_against(&plan.body, &runtime_ty, tcx)?;
            Ok(PendingRecOrderState::Runtime {
                exact_ty: binding_ty,
                source_checked: true,
            })
        }
    })();
    tcx.restore(mark);
    let disposition = disposition?;
    let module_path = tcx.env.module_path.clone();
    match disposition {
        PendingRecOrderState::Runtime { exact_ty, .. } => {
            let replacement = Expr::Let {
                occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
                name: plan.name.clone(),
                name_span: plan.value.span(),
                ty: None,
                pattern: (),
                value: plan.value.clone(),
                body: plan.body.clone(),
                meta: Meta::new(original.span()),
            };
            tcx.elaborations.record_rec_order_elaboration(
                &module_path,
                original,
                replacement,
                exact_ty,
            );
        }
        PendingRecOrderState::Pending => {
            unreachable!("pending recursive ordering disposition escaped carrier typechecking")
        }
    }
    Ok(Synth::value(plan.runtime_ty.clone()))
}

pub(crate) fn deferred_rec_tail_error(
    source: Option<&crate::ast::RecCallDiagnostic>,
    span: Span,
) -> Error {
    crate::pass::desugar::rec_boundary_error(source, span, true)
}

fn comptime_literal_reserved_names(module: &Module, include_references: bool) -> HashSet<String> {
    comptime_literal_reserved_names_in(&mut module.clone(), include_references)
}

fn comptime_literal_reserved_names_in(
    module: &mut Module,
    include_references: bool,
) -> HashSet<String> {
    use crate::pass::visit_mut::{TypecheckVisitMut, walk_expr, walk_type};
    struct Names(HashSet<String>, bool);
    impl TypecheckVisitMut<Lowered> for Names {
        fn enter_value_binder(&mut self, name: &mut String, _: Span, _: Span) {
            self.0.insert(name.clone());
        }
        fn enter_type_binder(&mut self, param: &mut TypeParam, _: Span) {
            self.0.insert(param.name.clone());
        }
        fn visit_expr(&mut self, expr: &mut Expr) {
            if self.1
                && let Expr::Path { segments, .. } = expr
            {
                self.0
                    .extend(segments.iter().map(|segment| segment.name.clone()));
            }
            walk_expr(self, expr);
        }
        fn visit_type(&mut self, ty: &mut Type) {
            if self.1
                && let Type::Path { segments, .. } = ty
            {
                self.0
                    .extend(segments.iter().map(|segment| segment.name.clone()));
            }
            walk_type(self, ty);
        }
    }
    let mut names = Names(HashSet::new(), include_references);
    for item in &module.items {
        crate::pass::resolve::for_each_item_declaration(item, |declaration| {
            let name = declaration
                .fn_def()
                .map(|def| def.name.as_str())
                .or_else(|| declaration.host_fn().map(|def| def.name.as_str()))
                .or_else(|| declaration.host_type().map(|def| def.name.as_str()))
                .or_else(|| declaration.type_alias().map(|def| def.name.as_str()))
                .or_else(|| declaration.newtype().map(|def| def.name.as_str()));
            if let Some(name) = name {
                names.0.insert(name.to_owned());
            }
        });
    }
    for import in &module.imports {
        match &import.kind {
            ImportKind::Qualified { alias, .. } => {
                names.0.insert(alias.clone());
            }
            ImportKind::Selective { items, .. } => names.0.extend(
                items
                    .iter()
                    .filter_map(crate::ast::ImportItem::as_local_name)
                    .map(str::to_owned),
            ),
            _ => {}
        }
    }
    names.visit_module(module);
    names.0
}

fn check_comptime_literal<'m>(
    expr: &'m Expr,
    expected: Option<&InternedType>,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<InternedType, Error> {
    let (result, plan) = prepare_comptime_literal(expr, expected, tcx)?;
    tcx.elaborations
        .comptime_literals
        .insert((tcx.env.module_path.clone(), expr.site().id), plan);
    Ok(result)
}

pub(crate) fn prepare_comptime_literal<'m>(
    expr: &'m Expr,
    expected: Option<&InternedType>,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<(InternedType, ComptimeLiteralPlan), Error> {
    use crate::ast::ComptimeLiteralValue;
    use crate::comptime::{ComptimeBuiltin, ComptimeLiteralConstructor};
    let Expr::ComptimeLiteral {
        value, proof, ext, ..
    } = expr
    else {
        unreachable!()
    };
    if !tcx.env.comptime_in_scope {
        let insertion = tcx.env.module.path.span.end + 1;
        let next = tcx
            .env
            .module
            .imports
            .first()
            .map(|import| import.span.start)
            .or_else(|| tcx.env.module.items.first().map(|item| item.span().start))
            .unwrap_or(insertion);
        return Err(Error::type_(
            expr.span(),
            "compile-time literal construction requires `import __comptime__;`",
        )
        .with_help("add `import __comptime__;` to this module")
        .with_fix(crate::error::Fix::machine_applicable(
            "Import compile-time APIs",
            vec![crate::error::FixEdit::from_parts(
                Span::new(insertion, insertion),
                vec![crate::error::FixReplacementPart::Text(
                    "\n\nimport __comptime__;".to_owned(),
                )],
                vec![Span::new(insertion, next)],
            )],
        )));
    }
    let proof_type = InternedType::fresh(Type::synth_path(
        vec!["__Comptime__".to_owned()],
        Vec::new(),
        proof.span(),
    ));
    check_value_against(proof, &proof_type, tcx)?;
    let constructor = match value {
        ComptimeLiteralValue::Bool(value) => ComptimeLiteralConstructor::Bool(*value),
        ComptimeLiteralValue::Str(value) => {
            let bound = tcx.in_scope_type_param_binders();
            match expected.and_then(|ty| tcx.env.comptime_type_identity_in(ty.as_type(), ty.identity_is_canonical(), &tcx.binder_alias_ctx(&bound))) {
                Some(ComptimeBuiltin::ComptimeStr) => ComptimeLiteralConstructor::Str(value.clone()),
                Some(ComptimeBuiltin::DiagnosticText) => ComptimeLiteralConstructor::DiagnosticText(value.clone()),
                _ => return Err(Error::type_(expr.span(), "cannot determine the compile-time text carrier")
                    .with_help("supply a `Comptime_str` or `__Diagnostic_text__` binding, argument, or return type")),
            }
        }
    };
    let module = tcx.env.module_path.clone();
    let reserved = tcx
        .elaborations
        .comptime_literal_names
        .entry(module.clone())
        .or_insert_with(|| comptime_literal_reserved_names(tcx.env.module, true));
    let tag = match constructor {
        ComptimeLiteralConstructor::Bool(_) => "bool",
        ComptimeLiteralConstructor::Str(_) => "str",
        ComptimeLiteralConstructor::DiagnosticText(_) => "diagnostic",
    };
    let base = format!("__ct_{tag}_literal{}", ext.0);
    let mut binding = base.clone();
    let mut suffix = 2;
    while reserved.contains(&binding) {
        binding = crate::naming::indexed_name(&base, suffix);
        suffix += 1;
    }
    let result = InternedType::fresh(Type::synth_path(
        vec![constructor.result_builtin().public_name().to_owned()],
        Vec::new(),
        expr.span(),
    ));
    Ok((
        result,
        ComptimeLiteralPlan {
            binding,
            constructor,
        },
    ))
}

fn synth_expr<'m>(e: &'m Expr, tcx: &mut TypeCtx<'m, '_>) -> Result<Synth, Error> {
    match e {
        Expr::ComptimeLiteral { .. } => {
            check_comptime_literal(e, None, tcx).map(Synth::value_interned)
        }
        crate::ast::Expr::BlockCall { ext, .. } => match *ext {},
        Expr::Unit {
            source_trivia: _,
            occurrence: _,
            meta: Meta { span, .. },
        } => Ok(Synth::value(Type::Unit {
            meta: Meta::new(*span),
        })),
        Expr::Path {
            segments,
            meta: Meta { span, .. },
            ..
        } => crate::pass::typecheck_core::synth_path_with_binder_recorder(
            segments,
            *span,
            tcx,
            |segment_span, kind, name, parent, qualifier, _local_index, tcx| {
                if matches!(
                    kind,
                    crate::pass::typecheck_core::ResolvedBinderKind::Intrinsic
                ) {
                    tcx.elaborations
                        .primitive_values
                        .insert((tcx.env.module_path.clone(), e.site().id), name.to_owned());
                }
                let binder = resolved_binder_for_position(kind, name, parent, qualifier, tcx);
                tcx.elaborations
                    .record_position_binder(&tcx.env.module_path, segment_span, binder);
            },
        ),
        Expr::Let {
            name,
            name_span,
            ty,
            value,
            body,
            ..
        } => crate::pass::typecheck_core::annotation_plan::synth_let(
            name,
            *name_span,
            ty.as_ref(),
            value,
            body,
            tcx,
        ),
        Expr::Seq { value, body, .. } => synth_seq(value, body, tcx),
        Expr::FnExpr {
            sig,
            ret_ty,
            body,
            meta: Meta { span, .. },
            ..
        } => crate::pass::typecheck_core::annotation_plan::synth_lowered_fn(
            e,
            sig,
            ret_ty.as_ref(),
            body,
            *span,
            tcx,
        ),
        Expr::Call { .. } => {
            crate::pass::typecheck_core::apply::run_general_ordinary_value(e, None, tcx)
        }
        Expr::StrLit {
            meta: Meta { .. },
            annotation,
            ..
        } => synth_literal(RoleShape::Str, annotation.as_ref(), e.site(), None, tcx)
            .map(Synth::value_interned),
        Expr::IntLit {
            meta: Meta { .. },
            annotation,
            ..
        } => synth_literal(
            RoleShape::Int,
            annotation.as_ref(),
            e.site(),
            crate::pass::typecheck_core::numeric_literal_diagnostic(e),
            tcx,
        )
        .map(Synth::value_interned),
        Expr::FloatLit {
            meta: Meta { .. },
            annotation,
            ..
        } => synth_literal(
            RoleShape::Float,
            annotation.as_ref(),
            e.site(),
            crate::pass::typecheck_core::numeric_literal_diagnostic(e),
            tcx,
        )
        .map(Synth::value_interned),
        Expr::BoolLit {
            meta: Meta { .. },
            annotation,
            ..
        } => synth_literal(RoleShape::Bool, annotation.as_ref(), e.site(), None, tcx)
            .map(Synth::value_interned),
        // Statically uninhabited in `Lowered`.
        Expr::Tuple { ext, .. } => match *ext {},
        Expr::OpChain { ext, .. } => match *ext {},
        Expr::RecCall { ext, .. } => match *ext {},
        // Statically uninhabited in `Lowered`.
        Expr::FnPlaceholder { ext, .. } => match *ext {},
        Expr::RecOrder { plan, .. } => synth_rec_order(e, plan, tcx),
        Expr::RecQuote { .. } => {
            crate::pass::typecheck_core::apply::run_general_ordinary_value(e, None, tcx)
        }
        Expr::UserMacro { .. } => {
            crate::pass::typecheck_core::apply::run_general_ordinary_value(e, None, tcx)
        }
        Expr::Ufcs { ext, .. } => match *ext {},
        // Statically uninhabited at `Lowered` — the enriched
        // structural variants are produced post-typecheck by the
        // structural-recovery pass at `Enriched` and retained at `Routed`.
        Expr::EnrichedTuple { ext, .. }
        | Expr::EnrichedProject { ext, .. }
        | Expr::EnrichedInject { ext, .. }
        | Expr::EnrichedMatch { ext, .. }
        | Expr::EnrichedConditional { ext, .. }
        | Expr::EnrichedFieldGet { ext, .. } => match *ext {},
        Expr::LowHostCall { ext, .. }
        | Expr::LowModuleCall { ext, .. }
        | Expr::LowQualifiedModuleCall { ext, .. }
        | Expr::LowQualifiedNewtypeMember { ext, .. }
        | Expr::LowNewtypeCtor { ext, .. }
        | Expr::LowNewtypeProj { ext, .. }
        | Expr::LowClosureCall { ext, .. }
        | Expr::LowIndirectCall { ext, .. }
        | Expr::LowTypeApplication { ext, .. }
        | Expr::LowAbsurdCall { ext, .. }
        | Expr::LowCpsProjectorApply { ext, .. }
        | Expr::LowBoundRef { ext, .. }
        | Expr::LowHostFnValueRef { ext, .. }
        | Expr::LowModuleFnValueRef { ext, .. } => match *ext {},
    }
}

pub(crate) fn prepare_literal_annotation(
    site: crate::ast::ExpressionSite,
    resolved: &InternedType,
    tcx: &TypeCtx<'_, '_>,
) -> (
    InternedType,
    Vec<UserMacroTemplateGeneratedImport>,
    Vec<PrimeLocalTypeAlias>,
) {
    crate::pass::typecheck_core::assert_goal_free(
        resolved.as_type(),
        "literal annotation publication",
    );
    if !resolved.identity_is_canonical() {
        return (resolved.clone(), Vec::new(), Vec::new());
    }
    let bound = tcx.in_scope_type_param_binders();
    let written = crate::pass::typecheck_core::source_type_spelling_with_bound(
        resolved.as_type(),
        tcx.env.module,
        true,
        &bound,
    );
    let existing_spelling = matches!(resolved.as_type(), Type::Path { args, .. } if args.is_empty())
        && (written != *resolved.as_type()
            || match &written {
                Type::Path { segments, .. } if segments.len() < 2 => tcx
                    .env
                    .module
                    .imports
                    .iter()
                    .any(|import_| matches!(import_.kind, ImportKind::Comptime)),
                Type::Path { segments, .. } if segments.len() == 2 => {
                    !bound.contains(segments[0].as_str())
                        && tcx.env.module.imports.iter().any(|import_| {
                            matches!(&import_.kind, ImportKind::Qualified { path, alias }
                            if alias == segments[0].as_str()
                                && path.segments.len() == 1
                                && path.segments[0].as_str() == segments[0].as_str())
                        })
                }
                _ => false,
            });
    if existing_spelling {
        return (InternedType::fresh(written), Vec::new(), Vec::new());
    }
    let module_hex = prime_binding_module_hex(&tcx.env.module_path);
    let mut requalifier = prime_requalifier_with_namespace(
        &format!("l{module_hex}_{}_{}", site.span.start, site.span.end),
        tcx,
    );
    let written = requalifier.rewrite(resolved.as_type(), &bound);
    let (imports, aliases) = take_prime_bindings(&mut requalifier);
    (InternedType::fresh(written), imports, aliases)
}

fn prime_binding_module_hex(module_path: &str) -> String {
    module_path
        .bytes()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn prime_requalifier_with_namespace(
    namespace: &str,
    tcx: &TypeCtx<'_, '_>,
) -> crate::pass::typecheck_core::PrimeTypeRequalifier {
    let mut requalifier = crate::pass::typecheck_core::PrimeTypeRequalifier::new_with_namespace(
        tcx.env.module,
        namespace,
    );
    for import in tcx.elaborations.generated_imports_for(&tcx.env.module_path) {
        requalifier.add_generated_import(&import.module_path, &import.alias);
    }
    for import in tcx
        .elaborations
        .prime_requalification_imports_for(&tcx.env.module_path)
    {
        requalifier.add_generated_import(&import.module_path, &import.alias);
    }
    for alias in tcx
        .elaborations
        .generated_type_aliases_for(&tcx.env.module_path)
    {
        requalifier.reserve_local_alias(alias);
    }
    requalifier
}

fn take_prime_bindings(
    requalifier: &mut crate::pass::typecheck_core::PrimeTypeRequalifier,
) -> (
    Vec<UserMacroTemplateGeneratedImport>,
    Vec<PrimeLocalTypeAlias>,
) {
    let imports = requalifier
        .take_imports()
        .into_iter()
        .filter_map(|import_| {
            let ImportKind::Qualified { path, alias, .. } = import_.kind else {
                return None;
            };
            Some(UserMacroTemplateGeneratedImport {
                module_path: path
                    .segments
                    .iter()
                    .map(PathSegment::as_str)
                    .collect::<Vec<_>>()
                    .join("/"),
                alias,
            })
        })
        .collect::<Vec<_>>();
    let aliases = requalifier.take_local_aliases();
    (imports, aliases)
}

fn record_prime_bindings(
    tcx: &mut TypeCtx<'_, '_>,
    imports: &[UserMacroTemplateGeneratedImport],
    aliases: &[PrimeLocalTypeAlias],
) {
    let module_path = tcx.env.module_path.clone();
    tcx.elaborations
        .record_prime_requalification_imports(&module_path, imports);
    tcx.elaborations
        .record_generated_type_aliases(&module_path, aliases);
}

fn canonical_nominal_identity(segments: &[PathSegment]) -> Option<(String, String)> {
    let (name, module_segments) = segments.split_last()?;
    if module_segments.is_empty() {
        return None;
    }
    Some((
        module_segments
            .iter()
            .map(PathSegment::as_str)
            .collect::<Vec<_>>()
            .join("/"),
        name.as_str().to_owned(),
    ))
}

// The synth/check/apply family — `synth_literal`, `synth_path`,
// `synth_top_fn_def`, `synth_let`, `synth_fn`, `synth_call`,
// `apply_polymorphic_function`, `apply_mono`, plus the supporting
// `unify_pattern` — all live in
// `crate::pass::typecheck_core` so the standalone Kio'-only typer can
// reuse them at `P = Prime`. The recursive arms route back through
// the `Typer<P>` dispatch trait (`<P::Typer as Typer<P>>::synth_expr`
// and `::check_value_against`), landing in this module's
// `LoweredTyper` impl at `P = Lowered`. Imported via the use clause
// at the top of this module.

/// Bidirectional check: confirm `e` has type `expected`. The default
/// path synthesizes `e` and structurally compares; the exceptions
/// are forms whose own typing depends on `expected`:
///
/// - `Expr::FnExpr` — checks each parameter and the body against the
///   corresponding expected function slots.
fn check_value_against<'m>(
    e: &'m Expr,
    expected: &InternedType,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<(), Error> {
    if matches!(e, Expr::ComptimeLiteral { .. }) {
        let actual = check_comptime_literal(e, Some(expected), tcx)?;
        return crate::pass::typecheck_core::require_type_equiv_state(
            actual.as_type(),
            expected.as_type(),
            e.span(),
            &tcx.binder_alias_ctx(&tcx.in_scope_type_param_binders()),
            actual.identity_is_canonical(),
            expected.identity_is_canonical(),
        );
    }
    if matches!(e, Expr::Call { .. }) {
        crate::pass::typecheck_core::apply::run_general_ordinary_value(e, Some(expected), tcx)?;
        return Ok(());
    }
    if let Expr::FnExpr {
        sig,
        ret_ty,
        body,
        meta: Meta { .. },
        ..
    } = e
    {
        return crate::pass::typecheck_core::annotation_plan::check_lowered_fn_against(
            sig,
            ret_ty.as_ref(),
            body,
            expected,
            e.site(),
            tcx,
        );
    }
    if matches!(e, Expr::Let { .. }) {
        return crate::pass::typecheck_core::annotation_plan::check_lowered_let_against(
            e, expected, tcx,
        );
    }
    if let Expr::RecOrder { plan, .. } = e {
        if crate::pass::typecheck_core::apply::is_rec_order_function_shell(plan)
            || matches!(
                plan.disposition,
                RecOrderDisposition::DeferredTail {
                    requirement: crate::ast::RecOrderTailRequirement::Optional
                        | crate::ast::RecOrderTailRequirement::Escaping,
                    ..
                }
            )
        {
            crate::pass::typecheck_core::apply::run_general_ordinary_value(e, Some(expected), tcx)?;
            return Ok(());
        }
        let synth = synth_rec_order(e, plan, tcx)?;
        crate::pass::typecheck_core::require_type_equiv_state(
            synth.ty.as_type(),
            expected.as_type(),
            e.span(),
            &tcx.env.alias_ctx(),
            synth.ty.identity_is_canonical(),
            expected.identity_is_canonical(),
        )?;
        return Ok(());
    }
    if matches!(e, Expr::UserMacro { .. } | Expr::RecQuote { .. }) {
        crate::pass::typecheck_core::apply::run_general_ordinary_value(e, Some(expected), tcx)?;
        return Ok(());
    }
    crate::pass::typecheck_core::default_check_value_against(e, expected, tcx)
}

#[cfg(test)]
fn type_has_free_macro_param(ty: &Type, names: &HashSet<String>) -> bool {
    match ty {
        Type::Unit { .. } | Type::Bottom { .. } | Type::Infer { .. } => false,
        Type::Goal { args, .. } => args.iter().any(|arg| type_has_free_macro_param(arg, names)),
        Type::Path { segments, args, .. } => {
            (segments.len() == 1 && names.contains(segments[0].as_str()))
                || args.iter().any(|arg| type_has_free_macro_param(arg, names))
        }
        Type::Function { param, ret, .. } => {
            type_has_free_macro_param(param, names) || type_has_free_macro_param(ret, names)
        }
        Type::Product { left, right, .. } | Type::Sum { left, right, .. } => {
            type_has_free_macro_param(left, names) || type_has_free_macro_param(right, names)
        }
        Type::Forall { param, body, .. } => {
            let masked: HashSet<String> = names
                .iter()
                .filter(|name| name.as_str() != param.name.as_str())
                .cloned()
                .collect();
            type_has_free_macro_param(body, &masked)
        }
    }
}

fn reflect_macro_type_with_binders(
    ty: Type,
    tcx: &TypeCtx<'_, '_>,
    additional_binders: &[FrozenResidualTypeBinder],
    identity_canonical: bool,
) -> Result<ReflectableType, Error> {
    let mut bindings: Vec<_> = tcx
        .in_scope_type_param_bindings()
        .map(|(name, kind, identity)| {
            (
                name.to_owned(),
                crate::normalization::ReflectedVariable::caller(
                    name.to_owned(),
                    kind.arity(),
                    identity,
                ),
            )
        })
        .collect();
    let mut names = tcx.in_scope_type_param_binders();
    for binder in additional_binders {
        assert!(
            names.insert(binder.param.name.clone()),
            "a generated macro binder collided with an ambient type binder"
        );
        bindings.push((binder.param.name.clone(), binder.binding.clone()));
    }
    reflect_macro_type_in_bindings(ty, tcx, bindings, identity_canonical)
}

fn reflect_macro_type_in_bindings(
    ty: Type,
    tcx: &TypeCtx<'_, '_>,
    bindings: Vec<(String, crate::normalization::ReflectedVariable)>,
    identity_canonical: bool,
) -> Result<ReflectableType, Error> {
    let mut names = bindings
        .iter()
        .map(|(name, _)| name.clone())
        .collect::<HashSet<_>>();
    if identity_canonical {
        // Protect canonical free heads from ambient alias expansion.
        // The explicit bindings supply any lexical identity.
        collect_free_type_vars(&ty, &mut names);
    }
    let reflected = crate::pass::typecheck_core::materialize_aliases_in_scope(
        &ty,
        Some(tcx.env.module),
        tcx.env.package,
        Some(&names),
        identity_canonical,
    );
    user_macro_reflectable_type(reflected).map(|ty| ty.with_lexical_bindings(bindings))
}

#[cfg(test)]
fn reflect_macro_type(ty: Type, tcx: &TypeCtx<'_, '_>) -> Result<ReflectableType, Error> {
    reflect_macro_type_with_binders(ty, tcx, &[], false)
}

fn reflect_macro_interned_type(
    ty: &InternedType,
    tcx: &TypeCtx<'_, '_>,
) -> Result<ReflectableType, Error> {
    reflect_macro_interned_type_with_binders(ty, tcx, &[])
}

pub(crate) fn reflect_projected_type(
    ty: &InternedType,
    tcx: &TypeCtx<'_, '_>,
    scope: &crate::pass::typecheck_core::ScopedType,
    overlay: impl IntoIterator<Item = (String, crate::normalization::ReflectedVariable)>,
) -> Result<crate::normalization::ReflectedType, Error> {
    let lexical = scope.projected_reflection_bindings();
    let mut names: HashSet<_> = lexical.iter().map(|(name, _, _)| name.clone()).collect();
    if ty.identity_is_canonical() {
        collect_free_type_vars(ty.as_type(), &mut names);
    }
    let reflected = crate::pass::typecheck_core::materialize_aliases_in_scope(
        ty.as_type(),
        Some(tcx.env.module),
        tcx.env.package,
        Some(&names),
        ty.identity_is_canonical(),
    );
    let mut used = HashSet::new();
    collect_free_type_vars(&reflected, &mut used);
    let overlay: HashMap<_, _> = overlay.into_iter().collect();
    let bindings = lexical
        .into_iter()
        .filter(|(name, _, _)| used.contains(name))
        .map(|(name, kind, identity)| {
            let binding = match identity {
                Some(identity) => crate::normalization::ReflectedVariable::caller(
                    name.clone(),
                    kind.arity(),
                    identity,
                ),
                None => overlay
                    .get(&name)
                    .unwrap_or_else(|| {
                        panic!(
                            "a reflected lexical binder `{name}` lost its retained semantic reference"
                        )
                    })
                    .clone(),
            };
            (name, binding)
        })
        .collect::<Vec<_>>();
    user_macro_reflectable_type(reflected).map(|ty| ty.with_lexical_bindings(bindings))
}

fn reflect_macro_interned_type_with_binders(
    ty: &InternedType,
    tcx: &TypeCtx<'_, '_>,
    additional_binders: &[FrozenResidualTypeBinder],
) -> Result<ReflectableType, Error> {
    reflect_macro_type_with_binders(
        ty.clone_type(),
        tcx,
        additional_binders,
        ty.identity_is_canonical(),
    )
}

fn user_macro_input_keys(inputs: &[UserMacroTemplateInput]) -> Vec<UserMacroTemplateInputKey> {
    inputs
        .iter()
        .map(|input| match input {
            UserMacroTemplateInput::ComptimeProof => UserMacroTemplateInputKey::ComptimeProof,
            UserMacroTemplateInput::Type(t) => UserMacroTemplateInputKey::Type(t.clone()),
            UserMacroTemplateInput::NaturalResult => UserMacroTemplateInputKey::NaturalResult,
            UserMacroTemplateInput::Term { value_ty, .. } => {
                UserMacroTemplateInputKey::Term(value_ty.clone())
            }
            UserMacroTemplateInput::BoundTerm { value_ty, .. } => {
                UserMacroTemplateInputKey::Term(value_ty.clone())
            }
            UserMacroTemplateInput::CapturedTerm { term } => {
                UserMacroTemplateInputKey::CapturedTerm(term.clone())
            }
        })
        .collect()
}

fn user_macro_item_index(module: &Module, macro_def: &crate::ast::UserMacroDef<Lowered>) -> usize {
    module
        .items
        .iter()
        .position(|item| {
            matches!(
                item,
                Item::Macro(candidate, _) if std::ptr::eq(candidate, macro_def)
            )
        })
        .expect("a resolved macro belongs to its definition module")
}

fn resolve_user_macro_captures_for_call<'m>(
    macro_def: &'m crate::ast::UserMacroDef<Lowered>,
    caller_tcx: &mut TypeCtx<'m, '_>,
    macro_module: Option<&'m Module>,
) -> Result<ResolvedUserMacroCaptures, Error> {
    let Some(macro_module) = macro_module else {
        let item_index = user_macro_item_index(caller_tcx.env.module, macro_def);
        // Captures resolve in the declaration environment. Reusing the caller
        // context here would let a local binder shadow a named capture.
        let definition_env = caller_tcx.env;
        let mut definition_tcx =
            TypeCtx::new(definition_env, caller_tcx.elaborations).at_item(item_index);
        return resolve_user_macro_captures(macro_def, definition_env, &mut definition_tcx);
    };
    let package = caller_tcx.env.package;
    let package_file =
        package.and_then(|package| package.package_file().map(|entry| &entry.package_file));
    let package_name = package.and_then(|package| {
        package
            .package_file()
            .map(|entry| entry.package_name.as_str())
    });
    let definition_env = crate::pass::typecheck_core::ModuleEnv::build_with_typecheck_scope(
        macro_module,
        package_file,
        package_name,
        package,
        caller_tcx.env.typecheck_scope.clone(),
    )?;
    let item_index = user_macro_item_index(macro_module, macro_def);
    let mut definition_tcx =
        TypeCtx::new(&definition_env, caller_tcx.elaborations).at_item(item_index);
    resolve_user_macro_captures(macro_def, &definition_env, &mut definition_tcx)
}

fn resolve_user_macro_slot_modes_for_call<'m>(
    macro_def: &'m crate::ast::UserMacroDef<Lowered>,
    layout: &UserMacroSignatureLayout,
    caller_tcx: &mut TypeCtx<'m, '_>,
    macro_module: Option<&'m Module>,
) -> Result<Vec<UserMacroTypeSlotMode>, Error> {
    let Some(macro_module) = macro_module else {
        let item_index = user_macro_item_index(caller_tcx.env.module, macro_def);
        let mut definition_tcx =
            TypeCtx::new(caller_tcx.env, caller_tcx.elaborations).at_item(item_index);
        definition_tcx.pure_context = true;
        return user_macro_implementation_type_slot_modes(macro_def, layout, &mut definition_tcx);
    };
    let package = caller_tcx.env.package;
    let package_file =
        package.and_then(|package| package.package_file().map(|entry| &entry.package_file));
    let package_name = package.and_then(|package| {
        package
            .package_file()
            .map(|entry| entry.package_name.as_str())
    });
    let definition_env = crate::pass::typecheck_core::ModuleEnv::build_with_typecheck_scope(
        macro_module,
        package_file,
        package_name,
        package,
        caller_tcx.env.typecheck_scope.clone(),
    )?;
    let item_index = user_macro_item_index(macro_module, macro_def);
    let mut definition_tcx =
        TypeCtx::new(&definition_env, caller_tcx.elaborations).at_item(item_index);
    definition_tcx.pure_context = true;
    user_macro_implementation_type_slot_modes(macro_def, layout, &mut definition_tcx)
}

fn resolve_user_macro_for_call<'m>(
    name: &str,
    span: Span,
    tcx: &TypeCtx<'m, '_>,
) -> Result<(&'m crate::ast::UserMacroDef<Lowered>, Option<&'m Module>), Error> {
    if let Some(macro_def) = tcx.env.cross_module_user_macros.get(name) {
        Ok((
            *macro_def,
            tcx.env.cross_module_user_macro_modules.get(name).copied(),
        ))
    } else if let Some(macro_def) = tcx.env.user_macros.get(name) {
        Ok((*macro_def, None))
    } else {
        Err(Error::type_(
            span,
            format!("`{name}` is not an imported macro"),
        ))
    }
}

fn user_macro_call_type(
    macro_def: &crate::ast::UserMacroDef<Lowered>,
    macro_module: Option<&Module>,
    tcx: &TypeCtx<'_, '_>,
) -> InternedType {
    let (call_ty, already_canonical) = match macro_module {
        Some(macro_module) => (
            crate::pass::resolve::qualify_contract_type_in_module(
                &macro_def.call_ty,
                macro_module,
                &HashMap::new(),
            ),
            true,
        ),
        None => (macro_def.call_ty.clone(), false),
    };
    let (call_ty, identity_canonical) = crate::pass::typecheck_core::canonicalize_for_comparison(
        &call_ty,
        &tcx.env.alias_ctx(),
        already_canonical,
    );
    InternedType::fresh_with_identity(call_ty, identity_canonical)
}

pub(crate) fn prepare_user_macro_action<'m>(
    original: &'m Expr,
    tcx: &mut TypeCtx<'m, '_>,
) -> Result<PreparedUserMacroAction<'m>, Error> {
    let span = original.span();
    let (name, stages) = match original {
        Expr::UserMacro { name, stages, .. } => (name.as_str(), stages),
        _ => unreachable!("user-macro action preparation received another expression"),
    };
    let source_args: Vec<_> = stages
        .iter()
        .flat_map(|stage| call_arg_refs(&stage.args))
        .collect();
    let (macro_def, macro_module) = resolve_user_macro_for_call(name, span, tcx)?;
    let trailing_final_prefix = match original {
        Expr::UserMacro {
            form: crate::ast::UserMacroCallForm::TrailingBlocks { has_final_prefix },
            ..
        } => Some(*has_final_prefix),
        _ => None,
    };
    if trailing_final_prefix.is_some()
        && source_args
            .iter()
            .any(|arg| matches!(arg, CallArgRef::Type(_)))
    {
        return Err(Error::type_(
            span,
            "a trailing-block call infers its type arguments",
        ));
    }
    let call_ty = user_macro_call_type(macro_def, macro_module, tcx);
    let layout = {
        let alias_ctx = tcx.env.alias_ctx();
        user_macro_signature_layout(&call_ty, &alias_ctx)
    };
    let type_slot_modes =
        resolve_user_macro_slot_modes_for_call(macro_def, &layout, tcx, macro_module)?;
    let args = source_args;
    Ok(PreparedUserMacroAction {
        result_span: span,
        node_id: elaboration_node_id(original)
            .expect("a user-macro expression carries an elaboration node"),
        name: macro_def.name.clone(),
        macro_def,
        macro_module,
        call_ty,
        args,
        stages,
        layout,
        type_slot_modes,
        span,
    })
}

fn module_path_string(module: &Module) -> String {
    module
        .path
        .segments
        .iter()
        .map(|s| s.as_str())
        .collect::<Vec<_>>()
        .join("/")
}

fn module_import_path(path: &crate::ast::ModulePath) -> String {
    path.segments
        .iter()
        .map(|s| s.as_str())
        .collect::<Vec<_>>()
        .join("/")
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct EvalFnIdentity {
    module_path: String,
    name: String,
}

fn eval_module_env<'m>(
    module: &'m Module,
    package: Option<&'m LoweredPackage>,
    typecheck_scope: std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
) -> Result<ModuleEnv<'m>, Error> {
    let package_file = package.and_then(|package| package.package_file());
    ModuleEnv::build_with_typecheck_scope(
        module,
        package_file.map(|entry| &entry.package_file),
        package_file.map(|entry| entry.package_name.as_str()),
        package,
        typecheck_scope,
    )
    .map_err(|error| eval_source_error(error, module, package))
}

fn eval_source_error(error: Error, module: &Module, package: Option<&LoweredPackage>) -> Error {
    match package.and_then(|package| package.module(&module_path_string(module))) {
        Some(entry) => error.with_source_file(entry.file_path.clone()),
        None => error,
    }
}

fn eval_fn_identity_for_path(
    segments: &[PathSegment],
    bound: &std::collections::BTreeSet<String>,
    env: &ModuleEnv<'_>,
    elaborations: &Elaborations,
) -> Option<EvalFnIdentity> {
    match segments {
        [name] if !bound.contains(name.as_str()) => {
            if env.fn_defs.contains_key(name.as_str()) {
                return Some(EvalFnIdentity {
                    module_path: env.module_path.clone(),
                    name: name.name.clone(),
                });
            }
            let owner = env.cross_module_fn_def_modules.get(name.as_str())?;
            let definition = env.cross_module_fn_defs.get(name.as_str())?;
            Some(EvalFnIdentity {
                module_path: module_path_string(owner),
                name: definition.name.clone(),
            })
        }
        [alias, name] if !bound.contains(alias.as_str()) => {
            let target = env
                .qualified_imports
                .get(alias.as_str())
                .copied()
                .or_else(|| {
                    let dependency = elaborations
                        .generated_imports_for(&env.module_path)
                        .iter()
                        .find(|dependency| dependency.alias == alias.as_str())?;
                    env.package?
                        .module(&dependency.module_path)
                        .map(|entry| &entry.module)
                })?;
            target.items.iter().find_map(|item| match item {
                Item::FnDef(def) if def.name == name.as_str() => Some(EvalFnIdentity {
                    module_path: module_path_string(target),
                    name: def.name.clone(),
                }),
                _ => None,
            })
        }
        _ => None,
    }
}

fn collect_eval_fn_refs(
    expr: &UncheckedPrimeExpr,
    bound: &mut std::collections::BTreeSet<String>,
    env: &ModuleEnv<'_>,
    elaborations: &Elaborations,
    out: &mut std::collections::BTreeSet<EvalFnIdentity>,
) {
    match expr {
        crate::ast::Expr::ComptimeLiteral { ext, .. } => match *ext {},
        crate::ast::Expr::BlockCall { ext, .. } => match *ext {},
        crate::ast::Expr::Path { segments, .. } => {
            if let Some(identity) = eval_fn_identity_for_path(segments, bound, env, elaborations) {
                out.insert(identity);
            }
        }
        crate::ast::Expr::Call { callee, args, .. } => {
            collect_eval_fn_refs(callee, bound, env, elaborations, out);
            for arg in args {
                if let crate::ast::CallArg::Value(value) = arg {
                    collect_eval_fn_refs(value, bound, env, elaborations, out);
                }
            }
        }
        crate::ast::Expr::FnExpr { sig, body, .. } => {
            let added: Vec<_> = sig
                .params
                .iter()
                .filter_map(|param| match param {
                    crate::ast::SignatureParam::Value(param)
                        if bound.insert(param.name.clone()) =>
                    {
                        Some(param.name.clone())
                    }
                    _ => None,
                })
                .collect();
            collect_eval_fn_refs(body, bound, env, elaborations, out);
            for name in added {
                bound.remove(&name);
            }
        }
        crate::ast::Expr::Let {
            name, value, body, ..
        } => {
            collect_eval_fn_refs(value, bound, env, elaborations, out);
            let added = bound.insert(name.clone());
            collect_eval_fn_refs(body, bound, env, elaborations, out);
            if added {
                bound.remove(name);
            }
        }
        crate::ast::Expr::Seq { value, body, .. } => {
            collect_eval_fn_refs(value, bound, env, elaborations, out);
            collect_eval_fn_refs(body, bound, env, elaborations, out);
        }
        crate::ast::Expr::Unit { .. }
        | crate::ast::Expr::StrLit { .. }
        | crate::ast::Expr::IntLit { .. }
        | crate::ast::Expr::FloatLit { .. }
        | crate::ast::Expr::BoolLit { .. } => {}
        crate::ast::Expr::Tuple { ext, .. }
        | crate::ast::Expr::FnPlaceholder { ext, .. }
        | crate::ast::Expr::RecOrder { ext, .. }
        | crate::ast::Expr::RecQuote { ext, .. }
        | crate::ast::Expr::UserMacro { ext, .. }
        | crate::ast::Expr::Ufcs { ext, .. }
        | crate::ast::Expr::OpChain { ext, .. }
        | crate::ast::Expr::RecCall { ext, .. }
        | crate::ast::Expr::EnrichedTuple { ext, .. }
        | crate::ast::Expr::EnrichedProject { ext, .. }
        | crate::ast::Expr::EnrichedInject { ext, .. }
        | crate::ast::Expr::EnrichedMatch { ext, .. }
        | crate::ast::Expr::EnrichedConditional { ext, .. }
        | crate::ast::Expr::EnrichedFieldGet { ext, .. }
        | crate::ast::Expr::LowHostCall { ext, .. }
        | crate::ast::Expr::LowModuleCall { ext, .. }
        | crate::ast::Expr::LowQualifiedModuleCall { ext, .. }
        | crate::ast::Expr::LowQualifiedNewtypeMember { ext, .. }
        | crate::ast::Expr::LowNewtypeCtor { ext, .. }
        | crate::ast::Expr::LowNewtypeProj { ext, .. }
        | crate::ast::Expr::LowClosureCall { ext, .. }
        | crate::ast::Expr::LowIndirectCall { ext, .. }
        | crate::ast::Expr::LowTypeApplication { ext, .. }
        | crate::ast::Expr::LowAbsurdCall { ext, .. }
        | crate::ast::Expr::LowCpsProjectorApply { ext, .. }
        | crate::ast::Expr::LowBoundRef { ext, .. }
        | crate::ast::Expr::LowHostFnValueRef { ext, .. }
        | crate::ast::Expr::LowModuleFnValueRef { ext, .. } => match *ext {},
    }
}

fn use_name_survives_eval_filter(
    package: &LoweredPackage,
    from: &crate::ast::ModulePath,
    name: &str,
    selected: &std::collections::BTreeSet<EvalFnIdentity>,
) -> bool {
    let from_path = module_import_path(from);
    let Some(target) = package.module(&from_path) else {
        return true;
    };
    target.module.items.iter().any(|item| {
        if let Item::TypeRecGroup(group) = item {
            return group.members.iter().any(|member| match member {
                crate::ast::TypeRecMember::TypeAlias(alias) => alias.name == name,
                crate::ast::TypeRecMember::Newtype(newtype) => newtype.name == name,
                crate::ast::TypeRecMember::Labels(labels, _) => {
                    labels.type_alias_name.as_deref() == Some(name)
                }
            });
        }
        if crate::pass::resolve::item_name(item) != name {
            return false;
        }
        match item {
            Item::Macro(_, _) => false,
            Item::FnDef(_) => selected.contains(&EvalFnIdentity {
                module_path: from_path.clone(),
                name: name.to_owned(),
            }),
            _ => true,
        }
    })
}

fn filtered_eval_module(
    module: &Module,
    selected: &std::collections::BTreeSet<EvalFnIdentity>,
    module_path: &str,
    item_count: usize,
) -> Module {
    let items = module
        .items
        .iter()
        .take(item_count)
        .filter(|item| match item {
            Item::FnDef(def) => selected.contains(&EvalFnIdentity {
                module_path: module_path.to_owned(),
                name: def.name.clone(),
            }),
            _ => true,
        });
    #[cfg(test)]
    let items = items.inspect(|item| eval_module_copy_tests::record_item_clone(item));
    Module {
        path: module.path.clone(),
        imports: module.imports.clone(),
        items: items.cloned().collect(),
        meta: module.meta.clone(),
        doc: module.doc.clone(),
    }
}

#[cfg(test)]
#[path = "typecheck_full/eval_module_copy_tests.rs"]
mod eval_module_copy_tests;

fn filtered_eval_package(
    package: &LoweredPackage,
    selected: &std::collections::BTreeSet<EvalFnIdentity>,
    root_module_path: &str,
    root_item_cutoff: usize,
) -> Result<LoweredPackage, Error> {
    let mut modules = std::collections::BTreeMap::new();
    for (path, entry) in package.modules() {
        let item_count = if path == root_module_path {
            root_item_cutoff + 1
        } else {
            entry.module.items.len()
        };
        let mut module = filtered_eval_module(&entry.module, selected, path, item_count);
        module.imports.retain_mut(|import_| {
            let ImportKind::Selective { items, from } = &mut import_.kind else {
                return true;
            };
            items.retain(|item| {
                item.as_name()
                    .is_none_or(|name| use_name_survives_eval_filter(package, from, name, selected))
            });
            !items.is_empty()
        });
        let scope = crate::pass::resolve::TopLevelScope::build(&module)
            .map_err(|error| error.with_source_file(entry.file_path.clone()))?;
        modules.insert(
            path.to_owned(),
            crate::pass::resolve::ModuleEntry {
                file_path: entry.file_path.clone(),
                module,
                scope,
            },
        );
    }
    Ok(LoweredPackage::from_parts(
        modules,
        package.package_file().cloned(),
    ))
}

fn staged_user_macro_artifact(
    env: &ModuleEnv<'_>,
    macro_name: &str,
    macro_module: Option<&Module>,
) -> Result<(crate::normalization::EvalArtifactInput, UncheckedPrimeExpr), Error> {
    let root_module = macro_module.unwrap_or(env.module);
    let package = env.package;
    let root_env = eval_module_env(root_module, package, env.typecheck_scope.clone())?;
    let mut staged = Elaborations::new();

    let (root_item_cutoff, def) = root_module
        .items
        .iter()
        .enumerate()
        .find(|(_, item)| matches!(item, Item::Macro(def, _) if def.name == macro_name))
        .and_then(|(index, item)| match item {
            Item::Macro(def, _) => Some((index, def)),
            _ => None,
        })
        .unwrap_or_else(|| {
            unreachable!("user macro `{macro_name}` is missing from its checked definition module")
        });
    let mut local = Elaborations::new();
    check_user_macro_item(def, root_item_cutoff, &root_env, &mut local)
        .map_err(|error| eval_source_error(error, root_module, package))?;
    UserMacroArtifactTypecheck::discharge_deferred(&mut local, &root_env)
        .map_err(|error| eval_source_error(error, root_module, package))?;
    staged.merge(local);

    let implementation_expr = Expr::Path {
        occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
        segments: def.implementation.segments().to_vec(),
        meta: Meta::new(def.implementation.span()),
        ext: (),
    };
    let root_expr = substitute::substitute_expr_for_eval(
        &implementation_expr,
        &staged,
        &root_env.module_path,
        package,
        Some(root_module),
    );
    let mut pending = std::collections::BTreeSet::new();
    collect_eval_fn_refs(
        &root_expr,
        &mut std::collections::BTreeSet::new(),
        &root_env,
        &staged,
        &mut pending,
    );
    let mut selected = std::collections::BTreeSet::new();
    while let Some(identity) = pending.pop_first() {
        if !selected.insert(identity.clone()) {
            continue;
        }
        let (owner_module, owner_package) = match package {
            Some(package) => {
                let entry = package.module(&identity.module_path).unwrap_or_else(|| {
                    unreachable!(
                        "selected compile-time helper module `{}` is missing from the checked package",
                        identity.module_path
                    )
                });
                (&entry.module, Some(package))
            }
            None if identity.module_path == root_env.module_path => (root_module, None),
            None => unreachable!(
                "a package-less evaluator artifact selected helper module `{}` outside its root",
                identity.module_path
            ),
        };
        let owner_env = eval_module_env(owner_module, owner_package, env.typecheck_scope.clone())?;
        let (item_index, def) = owner_module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(def) if def.name == identity.name => Some((index, def)),
                _ => None,
            })
            .unwrap_or_else(|| {
                unreachable!(
                    "selected compile-time helper `{}/{}` is missing from its checked module",
                    identity.module_path, identity.name
                )
            });
        let mut local = Elaborations::new();
        crate::pass::typecheck_core::check_fn_def(def, item_index, &owner_env, &mut local)
            .map_err(|error| eval_source_error(error, owner_module, owner_package))?;
        UserMacroArtifactTypecheck::discharge_deferred(&mut local, &owner_env)
            .map_err(|error| eval_source_error(error, owner_module, owner_package))?;
        staged.merge(local);
        let body = substitute::substitute_expr_for_eval(
            &def.body,
            &staged,
            &owner_env.module_path,
            owner_package,
            Some(owner_module),
        );
        collect_eval_fn_refs(
            &body,
            &mut def
                .sig
                .params
                .iter()
                .filter_map(|param| match param {
                    crate::ast::SignatureParam::Value(param) => Some(param.name.clone()),
                    crate::ast::SignatureParam::Type(_) => None,
                })
                .collect(),
            &owner_env,
            &staged,
            &mut pending,
        );
    }

    if let Some(package) = package {
        let filtered = env
            .typecheck_scope
            .try_renormalize_checked_for(package, |package| {
                filtered_eval_package(package, &selected, &root_env.module_path, root_item_cutoff)
            })?;
        let artifact = substitute::substitute_package_for_eval(&filtered, &staged)
            .map_err(LocatedError::into_error)?;
        Ok((artifact, root_expr))
    } else {
        let module = filtered_eval_module(
            root_module,
            &selected,
            &root_env.module_path,
            root_item_cutoff + 1,
        );
        let module =
            substitute::substitute_module_for_eval(&module, &staged, &root_env.module_path, None);
        let scope = crate::pass::resolve::TopLevelScope::build(&module)?;
        let entry = crate::pass::resolve::ModuleEntry {
            file_path: std::path::PathBuf::new(),
            module,
            scope,
        };
        let package = Package::from_parts(
            std::collections::BTreeMap::from([(root_env.module_path.clone(), entry)]),
            None,
        );
        let primitives =
            substitute::primitive_env_for_eval_module(root_module, &root_env.module_path, &staged);
        Ok((
            crate::normalization::EvalArtifactInput::new(package, primitives),
            root_expr,
        ))
    }
}

fn user_macro_eval_artifact(
    env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
    dependencies: &[UserMacroTemplateGeneratedImport],
    macro_name: &str,
    diagnostic_span: Span,
    macro_module: Option<&Module>,
) -> Result<UserMacroEvalArtifactPair, Error> {
    #[cfg(test)]
    record_user_macro_artifact_build(macro_name, &env.module_path);
    let (mut artifact, implementation) = staged_user_macro_artifact(env, macro_name, macro_module)?;
    if !dependencies.is_empty() {
        let (package, primitives) = artifact.into_parts();
        let (mut modules, package_file) = package.into_parts();
        let dependency_module_path = macro_module
            .map(module_path_string)
            .unwrap_or_else(|| env.module_path.clone());
        let entry = modules
            .get_mut(&dependency_module_path)
            .expect("evaluator artifact contains the macro definition module");
        let mut inserted_dependency = false;
        for dependency in dependencies {
            if dependency.module_path == dependency_module_path {
                continue;
            }
            let same_alias = entry
                .module
                .imports
                .iter()
                .find_map(|import_| match &import_.kind {
                    ImportKind::Qualified { path, alias } if alias == &dependency.alias => {
                        Some(module_import_path(path))
                    }
                    _ => None,
                });
            match same_alias {
                Some(path) if path == dependency.module_path => continue,
                Some(path) => unreachable!(
                    "evaluator dependency alias `{}` names both `{path}` and `{}`",
                    dependency.alias, dependency.module_path
                ),
                None => {}
            }
            entry.module.imports.push(Import {
                trailing_trivia: Vec::new(),
                kind: ImportKind::Qualified {
                    path: crate::ast::ModulePath {
                        segments: dependency
                            .module_path
                            .split('/')
                            .map(|segment| {
                                PathSegment::new(segment.to_owned(), entry.module.meta.span)
                            })
                            .collect(),
                        span: entry.module.meta.span,
                    },
                    alias: dependency.alias.clone(),
                },
                span: entry.module.meta.span,
                leading_trivia: Vec::new(),
            });
            inserted_dependency = true;
        }
        if inserted_dependency {
            entry.scope = crate::pass::resolve::TopLevelScope::build(&entry.module)
                .map_err(|error| error.with_source_file(entry.file_path.clone()))?;
        }
        artifact = crate::normalization::EvalArtifactInput::new(
            Package::from_parts(modules, package_file),
            primitives,
        );
    }
    artifact
        .package()
        .resolve_imports()
        .map_err(LocatedError::into_error)?;
    let implementation_module_path = macro_module
        .map(module_path_string)
        .unwrap_or_else(|| env.module_path.clone());
    UserMacroEvalArtifactPair::validate(
        artifact,
        implementation,
        implementation_module_path,
    )
    .map_err(|error| {
        let context = format!(
            "the expanded compile-time implementation of macro `{macro_name}` is validated at this call"
        );
        if error.source_file().is_some() {
            match env.package.and_then(|package| package.module(&env.module_path)) {
                Some(entry) if !entry.file_path.as_os_str().is_empty() => {
                    error.with_secondary_in_file(entry.file_path.clone(), diagnostic_span, context)
                }
                _ => error.with_note(context),
            }
        } else {
            error.reanchored_at(diagnostic_span).with_note(context)
        }
    })
}

fn verify_user_macro_artifact_memo(
    cached: &UserMacroEvalArtifactPair,
    fresh: &UserMacroEvalArtifactPair,
) {
    assert_eq!(
        cached.implementation_module_path(),
        fresh.implementation_module_path(),
        "KIO_DEBUG_MEMO_VERIFY=1: user macro artifact memo returned a different implementation owner"
    );
    assert_eq!(
        cached.implementation(),
        fresh.implementation(),
        "KIO_DEBUG_MEMO_VERIFY=1: user macro artifact memo returned a different implementation"
    );
    assert_eq!(
        cached.artifact().primitives(),
        fresh.artifact().primitives(),
        "KIO_DEBUG_MEMO_VERIFY=1: user macro artifact memo returned a different primitive environment"
    );
    let cached_modules = cached
        .artifact()
        .modules()
        .map(|(path, entry)| (path, &entry.module))
        .collect::<Vec<_>>();
    let fresh_modules = fresh
        .artifact()
        .modules()
        .map(|(path, entry)| (path, &entry.module))
        .collect::<Vec<_>>();
    assert_eq!(
        cached_modules, fresh_modules,
        "KIO_DEBUG_MEMO_VERIFY=1: user macro artifact memo returned different modules"
    );
    match (
        cached.artifact().package_file(),
        fresh.artifact().package_file(),
    ) {
        (Some(cached), Some(fresh)) => assert_eq!(
            (
                &cached.file_path,
                cached.package_name.as_str(),
                &cached.package_file,
            ),
            (
                &fresh.file_path,
                fresh.package_name.as_str(),
                &fresh.package_file,
            ),
            "KIO_DEBUG_MEMO_VERIFY=1: user macro artifact memo returned a different package file"
        ),
        (None, None) => {}
        _ => panic!(
            "KIO_DEBUG_MEMO_VERIFY=1: user macro artifact memo changed package-file presence"
        ),
    }
}

#[cfg(test)]
static USER_MACRO_ARTIFACT_BUILD_PROBES: std::sync::LazyLock<
    std::sync::Mutex<HashMap<String, HashMap<String, usize>>>,
> = std::sync::LazyLock::new(|| std::sync::Mutex::new(HashMap::new()));

#[cfg(test)]
fn start_user_macro_artifact_build_probe(macro_name: &str) {
    let previous = USER_MACRO_ARTIFACT_BUILD_PROBES
        .lock()
        .expect("user macro artifact build probes lock poisoned")
        .insert(macro_name.to_owned(), HashMap::new());
    assert!(previous.is_none(), "artifact build probe already active");
}

#[cfg(test)]
fn record_user_macro_artifact_build(macro_name: &str, module_path: &str) {
    if let Some(builds_by_module) = USER_MACRO_ARTIFACT_BUILD_PROBES
        .lock()
        .expect("user macro artifact build probes lock poisoned")
        .get_mut(macro_name)
    {
        *builds_by_module.entry(module_path.to_owned()).or_default() += 1;
    }
}

#[cfg(test)]
fn finish_user_macro_artifact_build_probe(macro_name: &str) -> HashMap<String, usize> {
    USER_MACRO_ARTIFACT_BUILD_PROBES
        .lock()
        .expect("user macro artifact build probes lock poisoned")
        .remove(macro_name)
        .expect("artifact build probe is active")
}

pub(crate) fn validate_user_macro_eval_artifact(
    artifact: &crate::normalization::EvalArtifactInput,
    implementation: &UncheckedPrimeExpr,
    implementation_module_path: &str,
) -> Result<(), Error> {
    for (owner, entries) in artifact.primitives().bindings() {
        if artifact.package().module(owner).is_none() {
            return Err(Error::type_(
                Span::new(0, 0),
                "compile-time primitive dependency names an absent module",
            ));
        }
        for (name, builtin) in entries {
            if name != builtin.public_name() {
                return Err(Error::type_(
                    Span::new(0, 0),
                    "compile-time primitive dependency has a mismatched binding name",
                ));
            }
        }
    }
    let comptime_modules = artifact
        .primitives()
        .bindings()
        .map(|(module_path, _)| module_path.to_owned())
        .collect::<HashSet<_>>();
    let mut modules = artifact
        .package()
        .modules()
        .map(|(path, entry)| {
            let mut imports = entry.module.imports.clone();
            if comptime_modules.contains(path)
                && !imports
                    .iter()
                    .any(|import_| matches!(import_.kind, ImportKind::Comptime))
            {
                imports.push(Import {
                    trailing_trivia: Vec::new(),
                    kind: ImportKind::Comptime,
                    span: entry.module.meta.span,
                    leading_trivia: Vec::new(),
                });
            }
            let module = crate::ast::Module {
                path: entry.module.path.clone(),
                imports,
                items: entry
                    .module
                    .items
                    .iter()
                    .map(crate::ast::convert_item::<UncheckedPrime, Lowered>)
                    .collect(),
                meta: crate::ast::convert_meta(&entry.module.meta),
                doc: entry.module.doc.clone(),
            };
            let scope = crate::pass::resolve::TopLevelScope::build(&module)
                .map_err(|error| error.with_source_file(entry.file_path.clone()))?;
            Ok((
                path.to_owned(),
                crate::pass::resolve::ModuleEntry {
                    file_path: entry.file_path.clone(),
                    module,
                    scope,
                },
            ))
        })
        .collect::<Result<std::collections::BTreeMap<_, _>, Error>>()?;
    use crate::pass::visit_mut::TypecheckVisitMut;
    struct PrimitiveReferences<'a> {
        owner: &'a str,
        primitives: &'a crate::normalization::EvalPrimitiveEnv,
        type_binders: Vec<String>,
        value_binders: Vec<String>,
        error: Option<Error>,
    }
    impl PrimitiveReferences<'_> {
        fn check(&mut self, segments: &[PathSegment], span: Span, is_type: bool) {
            let [name] = segments else { return };
            let binders = if is_type {
                &self.type_binders
            } else {
                &self.value_binders
            };
            if binders.iter().any(|bound| bound == name.as_str()) {
                return;
            }
            if let Some(builtin) = crate::comptime::ComptimeBuiltin::from_public_name(name.as_str())
                && builtin.is_type_name() == is_type
                && self.primitives.resolve(self.owner, name.as_str()) != Some(builtin)
                && self.error.is_none()
            {
                self.error = Some(Error::type_(
                    span,
                    format!(
                        "compile-time primitive `{}` requires its exact evaluator dependency",
                        name.as_str()
                    ),
                ));
            }
        }
    }
    impl TypecheckVisitMut<Lowered> for PrimitiveReferences<'_> {
        fn enter_type_binder(&mut self, param: &mut TypeParam, _: Span) {
            self.type_binders.push(param.name.clone());
        }
        fn exit_type_binder(&mut self, _: &mut TypeParam, _: Span) {
            self.type_binders.pop();
        }
        fn enter_value_binder(&mut self, name: &mut String, _: Span, _: Span) {
            self.value_binders.push(name.clone());
        }
        fn exit_value_binder(&mut self, _: &mut String, _: Span, _: Span) {
            self.value_binders.pop();
        }
        fn visit_type(&mut self, ty: &mut Type) {
            if let Type::Path { segments, meta, .. } = ty {
                self.check(segments, meta.span, true);
            }
            crate::pass::visit_mut::walk_type(self, ty);
        }
        fn visit_expr(&mut self, expr: &mut Expr) {
            if let Expr::Path { segments, meta, .. } = expr {
                self.check(segments, meta.span, false);
            }
            crate::pass::visit_mut::walk_expr(self, expr);
        }
    }
    let mut reserved_names = HashMap::new();
    for (owner, entry) in &mut modules {
        if entry
            .module
            .imports
            .iter()
            .any(|import| matches!(import.kind, ImportKind::Comptime))
        {
            let mut references = PrimitiveReferences {
                owner,
                primitives: artifact.primitives(),
                type_binders: Vec::new(),
                value_binders: Vec::new(),
                error: None,
            };
            references.visit_module(&mut entry.module);
            if let Some(error) = references.error {
                return Err(error);
            }
        }
        if artifact
            .primitives()
            .literal_bindings()
            .any(|(literal_owner, _, _)| literal_owner == owner)
        {
            reserved_names.insert(
                owner.clone(),
                comptime_literal_reserved_names_in(&mut entry.module, false),
            );
        }
    }
    for (owner, binding, constructor) in artifact.primitives().literal_bindings() {
        let entry = modules.get(owner).ok_or_else(|| {
            Error::type_(
                Span::new(0, 0),
                "compile-time literal dependency names an absent module",
            )
        })?;
        if !comptime_modules.contains(owner)
            || !entry
                .module
                .imports
                .iter()
                .any(|import| matches!(import.kind, ImportKind::Comptime))
        {
            return Err(Error::type_(
                entry.module.meta.span,
                "compile-time literal dependency requires the explicit compile-time primitive environment",
            ));
        }
        for builtin in [
            crate::comptime::ComptimeBuiltin::ComptimeProof,
            constructor.result_builtin(),
        ] {
            if artifact.primitives().resolve(owner, builtin.public_name()) != Some(builtin) {
                return Err(Error::type_(
                    entry.module.meta.span,
                    "compile-time literal dependency is missing a signature type dependency",
                ));
            }
        }
        crate::naming::validate_reference_name(
            binding,
            crate::naming::NameRole::Value,
            entry.module.meta.span,
        )?;
        if reserved_names
            .get(owner)
            .is_some_and(|names| names.contains(binding))
            || crate::comptime::ComptimeBuiltin::from_public_name(binding).is_some()
            || crate::pass::typecheck_core::intrinsic_scheme::<Lowered>(
                binding,
                entry.module.meta.span,
            )
            .is_some()
        {
            return Err(Error::type_(
                entry.module.meta.span,
                "compile-time literal dependency collides with a declared binding",
            ));
        }
    }
    let package = Package::from_parts(modules, None);
    package
        .resolve_imports()
        .map_err(LocatedError::into_error)?;
    package
        .check_no_value_cycles()
        .map_err(LocatedError::into_error)?;
    let type_interner = std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default());
    let checked = UserMacroArtifactTypecheck::check_package_with_primitives(
        &package,
        type_interner,
        Some(artifact.primitives()),
    )
    .map_err(|errors| {
        errors
            .into_iter()
            .next()
            .expect("collected evaluator artifact errors are non-empty")
            .into_error()
    })?;
    let package = checked.normalized();
    let module = &package
        .module(implementation_module_path)
        .ok_or_else(|| {
            Error::type_(
                implementation.span(),
                "evaluator implementation names an absent module",
            )
        })?
        .module;
    let typecheck_scope =
        crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
            package,
            std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
        )
        .with_evaluator_primitives(artifact.primitives());
    let env = ModuleEnv::build_with_typecheck_scope(
        module,
        None,
        None,
        Some(package.package()),
        typecheck_scope,
    )?;
    let mut elaborations = Elaborations::new();
    let mut tcx = TypeCtx::new(&env, &mut elaborations);
    tcx.pure_context = true;
    let mut implementation = crate::ast::convert_expr::<UncheckedPrime, Lowered>(implementation);
    if env.comptime_in_scope {
        let mut references = PrimitiveReferences {
            owner: implementation_module_path,
            primitives: artifact.primitives(),
            type_binders: Vec::new(),
            value_binders: Vec::new(),
            error: None,
        };
        references.visit_expr(&mut implementation);
        if let Some(error) = references.error {
            return Err(error);
        }
    }
    synth_expr(&implementation, &mut tcx).map(|_| ())
}

fn user_macro_eval_ctx_from_artifact<'m>(
    prepared: &'m UserMacroEvalArtifactPair,
) -> crate::normalization::AuthenticatedEvalCtx<'m> {
    let module = prepared
        .artifact()
        .prepare_module(prepared.implementation_module_path())
        .unwrap_or_else(|error| panic!("invalid evaluator artifact context: {error:?}"));
    crate::normalization::AuthenticatedEvalCtx::for_module(module)
}

fn user_macro_reflectable_type(ty: Type) -> Result<ReflectableType, Error> {
    ReflectableType::new(
        crate::ast::convert_type::<Lowered, UncheckedPrime>(&ty),
        USER_MACRO_REFLECTION_INFER_MESSAGE,
    )
}

fn compute_user_macro_deferred_template<'m>(
    ob: &DeferredUserMacroElaboration,
    key: Option<UserMacroMemoKey>,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    elaborations: &Elaborations,
    memo: &crate::pass::typecheck_core::MemoCtx<Lowered>,
) -> Result<UserMacroTemplateResult, Error> {
    let macro_module = macro_module_for_path(env, ob.macro_module_path.as_deref());
    let memo_start = crate::timing::user_macro_frontend_enabled().then(Instant::now);
    let compute = || {
        let record_timing = crate::timing::user_macro_frontend_enabled();
        let computed = compute_user_macro_template(
            UserMacroTemplateRequest {
                macro_name: &ob.name,
                macro_module,
                abi_inputs: ob.abi_inputs.clone(),
                capture_imports: ob.capture_imports.clone(),
                result_ty: ob.result_ty.as_ref(),
                ambient_type_names: &ob.ambient_type_names,
                residual_reflection_bindings: &ob.residual_reflection_bindings,
                span: ob.span,
            },
            env,
            elaborations,
            memo,
            record_timing,
        )?;
        Ok(computed)
    };
    let verify = |cached: &UserMacroTemplateResult| {
        let fresh = compute_user_macro_template(
            UserMacroTemplateRequest {
                macro_name: &ob.name,
                macro_module,
                abi_inputs: ob.abi_inputs.clone(),
                capture_imports: ob.capture_imports.clone(),
                result_ty: ob.result_ty.as_ref(),
                ambient_type_names: &ob.ambient_type_names,
                residual_reflection_bindings: &ob.residual_reflection_bindings,
                span: ob.span,
            },
            env,
            elaborations,
            memo,
            false,
        )
        .unwrap_or_else(|error| {
            panic!(
                "KIO_DEBUG_MEMO_VERIFY=1: user macro fresh validation failed: {}",
                error.diagnostic().message
            )
        });
        verify_user_macro_template_memo(cached, &fresh, ob, macro_module, env);
    };
    let result = match key {
        Some(key) => memo.user_macro_template_or_compute(key, compute, verify),
        None => compute(),
    };
    if let Some(memo_start) = memo_start {
        memo.record_user_macro_template_memo_total(memo_start.elapsed());
    }
    result
}

fn user_macro_template_memo_key(
    ob: &DeferredUserMacroElaboration,
    env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
) -> Option<UserMacroMemoKey> {
    user_macro_template_memo_key_with_budget(
        ob,
        env,
        crate::normalization::EXACT_CALL_MEMO_KEY_BUDGET,
    )
}

fn user_macro_template_memo_key_with_budget(
    ob: &DeferredUserMacroElaboration,
    env: &crate::pass::typecheck_core::ModuleEnv<'_, Lowered>,
    mut budget: usize,
) -> Option<UserMacroMemoKey> {
    enum Guard {
        Type(crate::normalization::ReflectedSnapshotKey),
        Captured(crate::normalization::CheckedSnapshotKey),
    }
    let mut guards = Vec::new();
    for input in &ob.input_keys {
        match input {
            UserMacroTemplateInputKey::Type(ty) | UserMacroTemplateInputKey::Term(ty) => {
                guards.push(Guard::Type(
                    crate::normalization::ReflectedSnapshotKey::new(ty, &mut budget)?,
                ));
            }
            UserMacroTemplateInputKey::CapturedTerm(term) => {
                guards.push(Guard::Captured(
                    crate::normalization::CheckedSnapshotKey::new(term, &mut budget)?,
                ));
            }
            UserMacroTemplateInputKey::ComptimeProof
            | UserMacroTemplateInputKey::NaturalResult
            | UserMacroTemplateInputKey::ResidualShape(_) => {}
        }
    }
    let mut key = UserMacroMemoKey::new(
        ob.macro_module_path
            .clone()
            .unwrap_or_else(|| env.module_path.clone()),
        ob.name.clone(),
        ob.input_keys
            .iter()
            .map(user_macro_memo_input_key)
            .collect(),
    )
    .with_result_type(
        ob.result_ty
            .as_ref()
            .map(|ty| crate::pass::typecheck_core::PresentedTypeMemoKey::from_type(ty.as_type())),
    );
    for guard in guards {
        match guard {
            Guard::Type(guard) => key.push_type_reflection_guard(guard),
            Guard::Captured(guard) => key.push_captured_reflection_guard(guard),
        }
    }
    Some(key)
}

fn user_macro_memo_input_key(input: &UserMacroTemplateInputKey) -> UserMacroMemoInputKey {
    match input {
        UserMacroTemplateInputKey::ComptimeProof => UserMacroMemoInputKey::ComptimeProof,
        UserMacroTemplateInputKey::Type(ty) => UserMacroMemoInputKey::Type(
            crate::pass::typecheck_core::PresentedTypeMemoKey::from_type(ty.as_type()),
        ),
        UserMacroTemplateInputKey::NaturalResult => UserMacroMemoInputKey::NaturalResult,
        UserMacroTemplateInputKey::Term(ty) => UserMacroMemoInputKey::Term(
            crate::pass::typecheck_core::PresentedTypeMemoKey::from_type(ty.as_type()),
        ),
        UserMacroTemplateInputKey::ResidualShape(ty) => UserMacroMemoInputKey::ResidualShape(
            crate::pass::typecheck_core::PresentedTypeMemoKey::from_type(ty),
        ),
        UserMacroTemplateInputKey::CapturedTerm(term) => UserMacroMemoInputKey::CapturedTerm(
            crate::pass::typecheck_core::PresentedTypeMemoKey::from_type(term.ty()),
        ),
    }
}

fn macro_module_for_path<'m>(
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    path: Option<&str>,
) -> Option<&'m Module> {
    path.map(|path| {
        env.package
            .and_then(|package| package.module(path))
            .map(|entry| &entry.module)
            .unwrap_or_else(|| {
                unreachable!("imported user macro module `{path}` missing at discharge")
            })
    })
}

struct UserMacroTemplateRequest<'a, 'm> {
    macro_name: &'a str,
    macro_module: Option<&'m Module>,
    abi_inputs: Vec<UserMacroTemplateInput>,
    capture_imports: Vec<UserMacroTemplateGeneratedImport>,
    result_ty: Option<&'a InternedType>,
    ambient_type_names: &'a HashSet<String>,
    residual_reflection_bindings: &'a [(String, crate::normalization::ReflectedVariable)],
    span: Span,
}

struct UserMacroPreparedRequest<'a, 'm> {
    macro_name: &'a str,
    purpose: UserMacroPreparedPurpose,
    macro_module: Option<&'m Module>,
}

struct UserMacroReplayEnv<'a> {
    module_path: &'a str,
    module: &'a Module,
    elaborations: &'a mut Elaborations,
    package: Option<&'a LoweredPackage>,
    memo: &'a crate::pass::typecheck_core::MemoCtx<Lowered>,
}

fn user_macro_replay_requalifier(
    replay: &UserMacroReplayEnv<'_>,
) -> crate::pass::typecheck_core::PrimeTypeRequalifier {
    let mut requalifier = crate::pass::typecheck_core::PrimeTypeRequalifier::new(replay.module);
    for import in replay
        .elaborations
        .generated_imports_for(replay.module_path)
    {
        requalifier.add_generated_import(&import.module_path, &import.alias);
    }
    for import in replay
        .elaborations
        .prime_requalification_imports_for(replay.module_path)
    {
        requalifier.add_generated_import(&import.module_path, &import.alias);
    }
    for alias in replay
        .elaborations
        .generated_type_aliases_for(replay.module_path)
    {
        requalifier.reserve_local_alias(alias);
    }
    requalifier
}

fn user_macro_eval_packet(inputs: &[UserMacroTemplateInput]) -> crate::normalization::Value {
    user_macro_eval_packet_with_capabilities(inputs, None)
}

fn user_macro_template_input_value(input: &UserMacroTemplateInput) -> crate::normalization::Value {
    match input {
        UserMacroTemplateInput::Type(ty) => crate::normalization::Value::ReflType(ty.clone()),
        UserMacroTemplateInput::CapturedTerm { term } => {
            crate::normalization::Value::CheckedTerm(term.clone())
        }
        UserMacroTemplateInput::ComptimeProof
        | UserMacroTemplateInput::NaturalResult
        | UserMacroTemplateInput::Term { .. }
        | UserMacroTemplateInput::BoundTerm { .. } => {
            unreachable!("a capture resolved as a declaration ABI slot")
        }
    }
}

fn user_macro_eval_packet_with_capabilities(
    inputs: &[UserMacroTemplateInput],
    mut capabilities: Option<(crate::normalization::Value, crate::normalization::Value)>,
) -> crate::normalization::Value {
    use crate::normalization::Value;
    let marked = capabilities.is_some();
    let mut values = Vec::with_capacity(inputs.len() + usize::from(marked));
    for input in inputs {
        let value = match input {
            UserMacroTemplateInput::ComptimeProof => {
                let proof = capabilities
                    .as_ref()
                    .map(|(proof, _)| proof.clone())
                    .unwrap_or(Value::Primitive(
                        crate::comptime::ComptimeBuiltin::ComptimeProof,
                    ));
                values.push(proof);
                if let Some((_, fills)) = capabilities.take() {
                    values.push(fills);
                }
                continue;
            }
            UserMacroTemplateInput::Type(ty) => Value::ReflType(ty.clone()),
            UserMacroTemplateInput::Term {
                value_index,
                value_ty,
            } => Value::CheckedTerm(crate::normalization::EvalRef::new(
                crate::normalization::CheckedTerm::template_value_reflected(
                    *value_index,
                    value_ty.clone(),
                ),
            )),
            UserMacroTemplateInput::BoundTerm { name, value_ty } => {
                Value::CheckedTerm(crate::normalization::EvalRef::new(
                    crate::normalization::CheckedTerm::local_reflected(
                        name.clone(),
                        value_ty.clone(),
                    ),
                ))
            }
            UserMacroTemplateInput::CapturedTerm { term } => Value::CheckedTerm(term.clone()),
            UserMacroTemplateInput::NaturalResult => Value::Unit,
        };
        values.push(value);
    }
    assert!(
        !marked || capabilities.is_none(),
        "a marked macro packet lost its leading capability slot"
    );
    crate::normalization::right_fold_product_values(values)
}

fn prepare_user_macro_value<'m>(
    request: UserMacroPreparedRequest<'_, 'm>,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    artifact_pair: &UserMacroEvalArtifactPair,
    memo: &crate::pass::typecheck_core::MemoCtx<Lowered>,
    record_timing: bool,
) -> Result<crate::pass::typecheck_core::PreparedUserMacro, Error> {
    let module_path = request
        .macro_module
        .map(module_path_string)
        .unwrap_or_else(|| env.module_path.clone());
    let key = UserMacroPreparedKey::new(
        module_path.clone(),
        request.macro_name.to_owned(),
        request.purpose,
    );
    memo.user_macro_prepared_or_try_compute(key, || {
        let caches = memo.user_macro_prepared_caches_for_module(&module_path);
        let eval_metrics = record_timing.then(crate::normalization::EvalMetrics::collect);
        let mut ctx = user_macro_eval_ctx_from_artifact(artifact_pair)
            .with_fn_closure_cache(caches.fn_closure_cache.clone())
            .with_eval_function_cache(caches.eval_function_cache.clone())
            .with_type_view_cache(caches.type_view_cache.clone())
            .with_exact_call_memo_cache(caches.exact_call_memo_cache.clone());
        if let Some(metrics) = &eval_metrics {
            ctx = ctx.with_metrics(metrics.clone());
        }
        let eval_start = record_timing.then(Instant::now);
        let value = crate::normalization::eval_authenticated(
            artifact_pair.implementation(),
            &crate::normalization::Env::new(),
            &ctx,
        );
        if let Some(eval_start) = eval_start {
            memo.record_user_macro_prepared_eval(eval_start.elapsed());
            if let Some(metrics) = eval_metrics {
                memo.record_user_macro_eval_metrics(metrics.snapshot());
            }
        }
        Ok(crate::pass::typecheck_core::PreparedUserMacro::new(
            value,
            caches.fn_closure_cache,
            caches.eval_function_cache,
            caches.type_view_cache,
            caches.exact_call_memo_cache,
        ))
    })
}

fn compute_user_macro_template<'m>(
    request: UserMacroTemplateRequest<'_, 'm>,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
    elaborations: &Elaborations,
    memo: &crate::pass::typecheck_core::MemoCtx<Lowered>,
    record_timing: bool,
) -> Result<UserMacroTemplateResult, Error> {
    let macro_module_path = request
        .macro_module
        .map(module_path_string)
        .unwrap_or_else(|| env.module_path.clone());
    let artifact_pair = env
        .typecheck_scope
        .user_macro_artifacts()
        .get_or_try_compute(
            UserMacroArtifactKey::new(
                macro_module_path.clone(),
                request.macro_name.to_owned(),
                request.capture_imports.clone(),
            ),
            || {
                user_macro_eval_artifact(
                    env,
                    &request.capture_imports,
                    request.macro_name,
                    request.span,
                    request.macro_module,
                )
            },
            |cached| {
                let fresh = user_macro_eval_artifact(
                    env,
                    &request.capture_imports,
                    request.macro_name,
                    request.span,
                    request.macro_module,
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "KIO_DEBUG_MEMO_VERIFY=1: fresh user macro artifact validation failed: {}",
                        error.diagnostic().message
                    )
                });
                verify_user_macro_artifact_memo(cached, &fresh);
            },
        )?;
    let prepared = prepare_user_macro_value(
        UserMacroPreparedRequest {
            macro_name: request.macro_name,
            purpose: UserMacroPreparedPurpose::Template,
            macro_module: request.macro_module,
        },
        env,
        artifact_pair.as_ref(),
        memo,
        record_timing,
    )?;
    let eval_metrics = record_timing.then(crate::normalization::EvalMetrics::collect);
    let mut ctx = user_macro_eval_ctx_from_artifact(&artifact_pair);
    ctx = ctx
        .with_fn_closure_cache(prepared.fn_closure_cache.clone())
        .with_eval_function_cache(prepared.eval_function_cache.clone())
        .with_type_view_cache(prepared.type_view_cache.clone())
        .with_exact_call_memo_cache(prepared.exact_call_memo_cache.clone());
    if let Some(metrics) = &eval_metrics {
        ctx = ctx.with_metrics(metrics.clone());
    }
    let eval_start = record_timing.then(Instant::now);
    let macro_value = prepared.value.clone();
    #[cfg(test)]
    memo.record_user_macro_template_execution(&macro_module_path, request.macro_name);
    let result = crate::normalization::apply(
        macro_value,
        vec![user_macro_eval_packet(&request.abi_inputs)],
        &ctx,
    );
    if let Some(eval_start) = eval_start {
        memo.record_user_macro_template_eval(eval_start.elapsed());
        if let Some(metrics) = eval_metrics {
            memo.record_user_macro_eval_metrics(metrics.snapshot());
        }
    }
    match decode_user_macro_result(result, &ctx) {
        Ok(checked) => {
            let template =
                trusted_user_macro_template(checked, request.residual_reflection_bindings);
            let checked = &template.checked;
            if let Some(target) = request.result_ty {
                let artifact = artifact_pair.artifact();
                let artifact_module = &artifact
                    .module(&macro_module_path)
                    .expect("evaluator artifact contains the macro module")
                    .module;
                let artifact_env = ModuleEnv::<UncheckedPrime>::build(
                    artifact_module,
                    artifact.package_file().map(|entry| &entry.package_file),
                    artifact
                        .package_file()
                        .map(|entry| entry.package_name.as_str()),
                    Some(artifact.as_ref()),
                )
                .unwrap_or_else(|error| panic!("invalid evaluator artifact context: {error:?}"));
                let target_display = source_type_spelling(
                    target.as_type(),
                    env.module,
                    target.identity_is_canonical(),
                );
                let mut binders = request.ambient_type_names.clone();
                if target.identity_is_canonical() {
                    collect_free_type_vars(target.as_type(), &mut binders);
                }
                let target_alias_ctx = AliasCtx {
                    binder_locals: Some(&binders),
                    ..env.alias_ctx()
                };
                let (canonical_target, target_is_canonical) =
                    crate::pass::typecheck_core::canonicalize_for_comparison(
                        target.as_type(),
                        &target_alias_ctx,
                        target.identity_is_canonical(),
                    );
                let canonical_target = crate::pass::typecheck_core::materialize_aliases_in_scope(
                    &canonical_target,
                    Some(env.module),
                    env.package,
                    Some(&binders),
                    target_is_canonical,
                );
                let target_eval = substitute::substitute_type_for_eval(
                    &canonical_target,
                    elaborations,
                    &env.module_path,
                    env.package,
                    Some(env.module),
                );
                collect_free_type_vars(checked.ty(), &mut binders);
                if target_is_canonical {
                    collect_free_type_vars(&target_eval, &mut binders);
                }
                let alias_ctx = crate::pass::typecheck_core::AliasCtx {
                    binder_locals: Some(&binders),
                    ..artifact_env.alias_ctx()
                };
                if crate::pass::typecheck_core::require_type_equiv_state(
                    checked.ty(),
                    &target_eval,
                    request.span,
                    &alias_ctx,
                    true,
                    target_is_canonical,
                )
                .is_err()
                {
                    let checked_display = source_type_spelling(checked.ty(), artifact_module, true);
                    return Ok(Err(format!(
                        "user macro returned a checked term of type `{}` but the declared \
                         result type was `{}`",
                        display_type(&checked_display),
                        display_type(&target_display)
                    )));
                }
            }
            Ok(Ok(template))
        }
        Err(UserMacroDecodeError::Diagnostic(message)) => Ok(Err(message)),
        Err(UserMacroDecodeError::Type(message)) => Err(Error::type_(request.span, message)),
        Err(UserMacroDecodeError::Evaluation(fault)) => Err(fault.into_error(request.span)),
    }
}

struct UserMacroReplayInputs<'a> {
    values: &'a [Expr],
    value_adapter: Option<&'a crate::normalization::CheckedTermTemplateValueAdapter>,
    residual_eta: Option<&'a crate::pass::substitute::EtaPlan<UncheckedPrime>>,
    ambient_type_names: &'a HashSet<String>,
    residual_reflection_bindings: &'a [(String, crate::normalization::ReflectedVariable)],
    capture_imports: &'a [UserMacroTemplateGeneratedImport],
    quoted: Option<(NodeId, Option<&'a QuotedPublicRecipe>)>,
}

struct UserMacroReplayResult {
    expression: UncheckedPrimeExpr,
    primitives: Option<std::sync::Arc<crate::normalization::EvalPrimitiveEnv>>,
    computation: bool,
}

fn user_macro_template_to_elaboration(
    template: &UserMacroTemplateResult,
    inputs: UserMacroReplayInputs<'_>,
    span: Span,
    replay: &mut UserMacroReplayEnv<'_>,
) -> Result<UserMacroReplayResult, Error> {
    let UserMacroReplayInputs {
        values,
        value_adapter,
        residual_eta,
        ambient_type_names,
        residual_reflection_bindings,
        capture_imports,
        quoted,
    } = inputs;
    let replay_start = crate::timing::user_macro_frontend_enabled().then(Instant::now);
    let mut emitted_computation = false;
    let result = match template {
        Ok(template) => {
            for value in values {
                rec_quote::finish_source_expansions(value, replay)?;
            }
            let quoted = quoted.and_then(|(node, public)| {
                replay
                    .elaborations
                    .rec_quote_call(node)
                    .map(|(source, expansion)| (source, expansion.runtime_type.clone(), public))
            });
            let mut source_computations = None;
            let mut suspended = None;
            let mut runtime_type = None;
            let mut public_output_type = None;
            let mut terminal_adapted = false;
            if let Some((source, runtime, public)) = quoted {
                let runtime = rec_quote_source::public_type(&runtime, ambient_type_names, replay);
                let output = replay
                    .elaborations
                    .rec_quote_source_type(source)
                    .expect("quoted macro has a closed public result")
                    .clone();
                public_output_type = Some(rec_quote_source::public_type(
                    &output,
                    ambient_type_names,
                    replay,
                ));
                let computations = values
                    .iter()
                    .map(|value| {
                        rec_quote_source::compose(value, &runtime, ambient_type_names, replay)
                    })
                    .collect::<Result<Vec<_>, _>>()?;
                let mask: Vec<_> = computations.iter().map(Option::is_some).collect();
                terminal_adapted = public.is_some_and(|public| public.terminal_adapted);
                if mask.iter().any(|suspended| *suspended) {
                    let slots: Vec<_> = value_adapter
                        .map(|adapter| {
                            adapter
                                .slots
                                .iter()
                                .map(|slot| {
                                    slot.pieces.iter().any(|piece| mask[piece.source_index])
                                })
                                .collect()
                        })
                        .unwrap_or_else(|| mask.clone());
                    let original = public
                        .map(|public| public.checked.as_ref())
                        .unwrap_or(&template.checked);
                    original
                        .validate_recursive_template_scope(
                            &slots,
                            residual_eta.is_some_and(|eta| !eta.layers.is_empty()),
                        )
                        .map_err(|message| Error::type_(span, message))?;
                    source_computations = Some(computations);
                    suspended = Some(mask);
                    runtime_type = Some(runtime);
                } else if terminal_adapted {
                    runtime_type = Some(runtime);
                } else {
                    public_output_type = None;
                }
            }
            let mut checked = value_adapter
                .map(|adapter| template.checked.adapt_template_values(adapter))
                .unwrap_or_else(|| template.checked.clone());
            let mut recipe_computation = false;
            if let (Some(suspended), Some(runtime)) = (&suspended, &runtime_type) {
                checked
                    .validate_recursive_template_scope(
                        suspended,
                        residual_eta.is_some_and(|eta| !eta.layers.is_empty()),
                    )
                    .map_err(|message| Error::type_(span, message))?;
                let runtime =
                    crate::ast::convert_type::<substitute::PrePrime, UncheckedPrime>(runtime);
                if let Some(computation) = checked
                    .adapt_recursive_template_values(suspended, &runtime)
                    .map_err(|message| Error::type_(span, message))?
                {
                    checked = computation;
                    recipe_computation = true;
                }
            }
            let mut capture_requalifier = None;
            let mut replay_aliases = HashMap::new();
            let mut generated_imports = Vec::new();
            for import in capture_imports {
                if import.module_path == replay.module_path {
                    replay_aliases.insert(import.alias.clone(), None);
                    continue;
                }
                let alias = capture_requalifier
                    .get_or_insert_with(|| user_macro_replay_requalifier(replay))
                    .ensure_module_import(&import.module_path);
                replay_aliases.insert(import.alias.clone(), Some(alias.clone()));
                generated_imports.push(UserMacroTemplateGeneratedImport {
                    module_path: import.module_path.clone(),
                    alias,
                });
            }
            replay
                .elaborations
                .record_generated_imports(replay.module_path, &generated_imports);
            let checked = checked.align_for_export(residual_reflection_bindings);
            let mut serialization_type_binders = checked.serialization_type_binders();
            serialization_type_binders.extend(ambient_type_names.iter().cloned());
            if let Some(residual_eta) = residual_eta {
                serialization_type_binders.extend(
                    residual_eta
                        .layers
                        .iter()
                        .flat_map(|layer| layer.type_params.iter().map(|param| param.name.clone())),
                );
            }
            let mut pre_prime_values = Vec::with_capacity(values.len());
            for (index, value) in values.iter().enumerate() {
                if let Some(computation) = source_computations
                    .as_mut()
                    .and_then(|sources| sources[index].take())
                {
                    pre_prime_values.push(computation);
                    continue;
                }
                pre_prime_values.push(substitute::substitute_expr_for_replayed_elaboration(
                    value,
                    ambient_type_names,
                    replay.elaborations,
                    replay.module_path,
                    replay.package,
                    replay.module,
                ));
            }
            let mut type_requalifier = user_macro_replay_requalifier(replay);
            let mut raw_to_pre_prime = |expr: &crate::ast::Expr<UncheckedPrime>,
                                        call_span: Span| {
                let mut expr = expr.clone();
                if let crate::ast::Expr::Path { segments, .. } = &mut expr
                    && segments.len() > 1
                    && let Some(replay_alias) = replay_aliases.get(segments[0].as_str())
                {
                    match replay_alias {
                        Some(alias) => segments[0].name.clone_from(alias),
                        None => {
                            segments.remove(0);
                        }
                    }
                }
                let expr = crate::ast::convert_expr::<UncheckedPrime, substitute::PrePrime>(&expr);
                crate::pass::macro_registry::reanchor_macro_template_pre_prime(&expr, call_span)
            };
            let mut type_to_pre_prime = |ty: &crate::ast::Type<UncheckedPrime>| {
                crate::normalization::replay_type_to_pre_prime(
                    ty,
                    Some((&mut type_requalifier, &serialization_type_binders)),
                )
            };
            let expr = checked.instantiate_template_pre_prime(
                &pre_prime_values,
                span,
                &mut raw_to_pre_prime,
                &mut type_to_pre_prime,
            );
            let expr = match residual_eta {
                Some(residual_eta) if !residual_eta.layers.is_empty() => {
                    let plan =
                        substitute::map_eta_plan_to_pre_prime(residual_eta, &mut type_to_pre_prime);
                    substitute::eta_materialize_pre_prime(
                        &plan,
                        substitute::EtaTerminal::Body(expr),
                        span,
                    )
                }
                Some(_) | None => expr,
            };
            let expr = if let (Some(runtime), Some(public)) = (runtime_type, public_output_type)
                && (recipe_computation || terminal_adapted)
            {
                emitted_computation = true;
                let continuation_name = rec_quote_source::fresh_name();
                let continuation = rec_quote_source::local(continuation_name.clone(), span);
                let body = if recipe_computation {
                    let continuation = if terminal_adapted {
                        let name = rec_quote_source::fresh_name();
                        rec_quote_source::lambda(
                            name.clone(),
                            runtime.clone(),
                            runtime.clone(),
                            rec_quote_source::local(name, span),
                            span,
                        )
                    } else {
                        continuation
                    };
                    rec_quote_source::call(expr, continuation, span)
                } else if terminal_adapted {
                    expr
                } else {
                    rec_quote_source::call(continuation, expr, span)
                };
                rec_quote_source::lambda(
                    continuation_name,
                    rec_quote_source::arrow(public, runtime.clone(), span),
                    runtime,
                    body,
                    span,
                )
            } else {
                expr
            };
            let imports = type_requalifier
                .take_imports()
                .into_iter()
                .map(|import_| {
                    let ImportKind::Qualified { path, alias } = import_.kind else {
                        unreachable!("Prime type requalification emits only qualified imports")
                    };
                    UserMacroTemplateGeneratedImport {
                        module_path: module_import_path(&path),
                        alias,
                    }
                })
                .collect::<Vec<_>>();
            let aliases = type_requalifier.take_local_aliases();
            replay
                .elaborations
                .record_prime_requalification_imports(replay.module_path, &imports);
            replay
                .elaborations
                .record_generated_type_aliases(replay.module_path, &aliases);
            let mut expr = expr;
            let primitives = substitute::primitive_env_for_replayed_expr(
                &mut expr,
                replay.module,
                replay.module_path,
                replay.elaborations,
            );
            Ok(UserMacroReplayResult {
                expression: substitute::finish_replayed_elaboration(expr, ambient_type_names),
                primitives,
                computation: emitted_computation,
            })
        }
        Err(message) => Err(Error::macro_error(span, message.clone())),
    };
    if let Some(replay_start) = replay_start {
        replay
            .memo
            .record_user_macro_template_replay(replay_start.elapsed());
    }
    result
}

fn trusted_user_macro_template(
    checked: crate::normalization::CheckedTerm,
    preferred: &[(String, crate::normalization::ReflectedVariable)],
) -> UserMacroTemplate {
    UserMacroTemplate {
        checked: checked.align_for_export(preferred),
    }
}

fn user_macro_result_type_verification_key(
    ty: &crate::ast::Type<UncheckedPrime>,
) -> (TypeMemoKey, Vec<usize>) {
    fn collect_abi_arities(ty: &crate::ast::Type<UncheckedPrime>, arities: &mut Vec<usize>) {
        match ty {
            crate::ast::Type::Path { args, .. } => {
                for arg in args {
                    collect_abi_arities(arg, arities);
                }
            }
            crate::ast::Type::Unit { .. } | crate::ast::Type::Bottom { .. } => {}
            crate::ast::Type::Function {
                param,
                ret,
                abi_arity,
                ..
            } => {
                arities.push(*abi_arity);
                collect_abi_arities(param, arities);
                collect_abi_arities(ret, arities);
            }
            crate::ast::Type::Product { left, right, .. }
            | crate::ast::Type::Sum { left, right, .. } => {
                collect_abi_arities(left, arities);
                collect_abi_arities(right, arities);
            }
            crate::ast::Type::Forall { body, .. } => collect_abi_arities(body, arities),
            crate::ast::Type::Infer { ext, .. } => match *ext {},
            crate::ast::Type::Goal { ext, .. } => match *ext {},
        }
    }

    let mut abi_arities = Vec::new();
    collect_abi_arities(ty, &mut abi_arities);
    (TypeMemoKey::from_type(ty), abi_arities)
}

fn verify_user_macro_template_memo<'m>(
    cached: &UserMacroTemplateResult,
    fresh: &UserMacroTemplateResult,
    obligation: &DeferredUserMacroElaboration,
    macro_module: Option<&'m Module>,
    env: &crate::pass::typecheck_core::ModuleEnv<'m, Lowered>,
) {
    match (cached, fresh) {
        (Ok(cached), Ok(fresh)) => {
            assert_eq!(
                user_macro_result_type_verification_key(cached.result_ty()),
                user_macro_result_type_verification_key(fresh.result_ty()),
                "KIO_DEBUG_MEMO_VERIFY=1: user macro memo returned a different result type"
            );
            let artifact = user_macro_eval_artifact(
                env,
                &obligation.capture_imports,
                &obligation.name,
                obligation.span,
                macro_module,
            )
            .unwrap_or_else(|error| {
                panic!(
                    "KIO_DEBUG_MEMO_VERIFY=1: evaluator artifact validation failed: {}",
                    error.diagnostic().message
                )
            });
            let ctx = user_macro_eval_ctx_from_artifact(&artifact);
            let cached_expr = user_macro_template_verification_expr(cached);
            let fresh_expr = user_macro_template_verification_expr(fresh);
            let cached_value = crate::normalization::eval_authenticated(
                &cached_expr,
                &crate::normalization::Env::new(),
                &ctx,
            );
            let fresh_value = crate::normalization::eval_authenticated(
                &fresh_expr,
                &crate::normalization::Env::new(),
                &ctx,
            );
            match crate::normalization::nf_eq_checked(&cached_value, &fresh_value, &ctx) {
                Ok(equal) => assert!(
                    equal,
                    "KIO_DEBUG_MEMO_VERIFY=1: user macro memo returned a different elaboration"
                ),
                Err(fault) => panic!(
                    "KIO_DEBUG_MEMO_VERIFY=1: user macro memo verification triggered {}",
                    crate::normalization::comptime_fault_message(&fault, &ctx)
                        .expect("checked NF equality returns an evaluation fault")
                ),
            }
        }
        (Err(cached), Err(fresh)) => {
            assert_eq!(
                cached, fresh,
                "KIO_DEBUG_MEMO_VERIFY=1: user macro memo returned a different diagnostic"
            );
        }
        _ => {
            panic!("KIO_DEBUG_MEMO_VERIFY=1: user macro memo changed success/failure");
        }
    }
}

fn user_macro_template_verification_expr(
    template: &UserMacroTemplate,
) -> crate::ast::Expr<UncheckedPrime> {
    let span = Span::new(0, 0);
    let values = (0..template.checked.template_value_arity())
        .map(|index| crate::ast::Expr::<substitute::PrePrime>::Path {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            segments: vec![PathSegment::new(
                format!("__kio_memo_verify_value{index}"),
                span,
            )],
            meta: Meta::new(span),
            ext: (),
        })
        .collect::<Vec<_>>();
    let mut raw_to_pre_prime = |expr: &crate::ast::Expr<UncheckedPrime>, call_span: Span| {
        let expr = crate::ast::convert_expr::<UncheckedPrime, substitute::PrePrime>(expr);
        crate::pass::macro_registry::reanchor_macro_template_pre_prime(&expr, call_span)
    };
    let mut type_to_pre_prime = |ty: &crate::ast::Type<UncheckedPrime>| {
        crate::normalization::replay_type_to_pre_prime(ty, None)
    };
    let expr = template.checked.instantiate_template_pre_prime(
        &values,
        span,
        &mut raw_to_pre_prime,
        &mut type_to_pre_prime,
    );
    substitute::finish_replayed_elaboration(expr, &HashSet::new())
}

enum UserMacroDecodeError {
    Diagnostic(String),
    Type(String),
    Evaluation(crate::normalization::ComptimeFault),
}

fn decode_user_macro_result(
    value: crate::normalization::Value,
    ctx: &crate::normalization::EvalCtx<'_>,
) -> Result<crate::normalization::CheckedTerm, UserMacroDecodeError> {
    use crate::normalization::Value;
    if let Some(fault) = crate::normalization::comptime_fault(&value, ctx) {
        return Err(UserMacroDecodeError::Evaluation(fault));
    }
    match value {
        Value::CheckedTerm(term) => {
            if let Some((kind, message)) = term.checked_error() {
                match kind {
                    crate::normalization::CheckedTermErrorKind::Macro => {
                        Err(UserMacroDecodeError::Diagnostic(message.to_owned()))
                    }
                    crate::normalization::CheckedTermErrorKind::Type => {
                        Err(UserMacroDecodeError::Type(message.to_owned()))
                    }
                }
            } else {
                Ok(term.canonicalize_template(ctx))
            }
        }
        other => Err(UserMacroDecodeError::Diagnostic(format!(
            "user macro returned `{}` instead of `__Checked_term__`",
            crate::normalization::value_to_string(&other)
        ))),
    }
}

// =========================================================================
// Type substitution
// =========================================================================

// `subst_type` lives in `crate::pass::typecheck_core`. Imported via the
// use clause at the top of this module.

// =========================================================================
// Type equivalence (structural, with visible local and cross-module alias unfolding)
// =========================================================================
//
// `unfold_top`, `type_equiv`, and `require_type_equiv` live in
// `crate::pass::typecheck_core`. They take an [`AliasCtx`] view of the
// environment's local and selectively imported aliases plus package context
// for qualified visible aliases; the typer threads it through
// `env.alias_ctx()` at every call site. Imported via the use clause at the top
// of this module.

// =========================================================================
// Intrinsic and newtype-member schemes
// =========================================================================
//
// `intrinsic_scheme` lives in `crate::pass::typecheck_core`. Imported via
// the use clause at the top of this module.

// `synth_env_fn_def`,
// `newtype_member_scheme`, `ty_nominal_segments`,
// `clone_with_span`, and the tiny scheme constructors (`tp` /
// `vp` / `ty_path` / `ty_sum` / `ty_product` / `ty_func`) all
// live in `crate::pass::typecheck_core`. The standalone Kio'-only walker
// in `crate::prime::typer` reuses them at `P = Prime` without a
// duplicate copy. Imported via the use clause at the top of this
// module.

// =========================================================================
// Type pretty-printing for diagnostics
// =========================================================================

// `display_type` and the underlying `write_type` walker live in
// `crate::pass::typecheck_core`. Imported at the top of this module.

