    #[test]
    fn rec_escape_inner_closure_in_residual_outer_callback_keeps_ordinary_semantics() {
        let source = "module main;
            import __intrinsics__;
            import __comptime__;
            host fn drive[S][R](step: ((S -> R) & S) -> (S | R), state: S) -> R;
            host type Later;
            host fn later() -> Later;
            pure fn invoke_then_impl(ct: __Comptime__, fills: __Fill_ctx__,
                _s: __Type__, _r: __Type__, callback: __Checked_term__, _later: __Checked_term__
            ) -> (__Checked_term__ & __Fill_ctx__) {
                let unit = __reflect_type__(ct)[.];
                let thunk = __type_arrow__(ct, unit, unit);
                let callback_type = __type_arrow__(ct, unit, thunk);
                (__term_call__(ct, callback_type, callback, __term_unit__(ct)), fills)
            }
            macro invoke_then : [S][R] (S -> R) -> Later -> R { impl(fills) invoke_then_impl; };
            rec(drive) fn repeat() -> Later -> . -> . {
                invoke_then(.(_unit: .) { .() { (recur(escape) repeat())(later())() } })
            }";
        check_package_sources(&[source])
            .expect("the outer callback needs no structural-tail permission");
    }

    #[test]
    fn rec_escape_deferred_boundary_fixes_keep_comments_and_recheck() {
        let source = "module main;
            import __intrinsics__;
            import __comptime__;
            host fn drive[S][R](step: ((S -> R) & S) -> (S | R), state: S) -> R;
            host fn retain(callback: . -> .) -> .;
            pure fn ignore_impl(ct: __Comptime__, fills: __Fill_ctx__, _a: __Type__, _value: __Checked_term__) -> (__Checked_term__ & __Fill_ctx__) {
                (__term_unit__(ct), fills)
            }
            macro ignore : [A] A -> . { impl(fills) ignore_impl; };
            rec(drive) {
                fn spin(value: .) -> . { ignore[. -> .]( .x. { recur // keep\n spin(x1) }) };
                fn saved(value: .) -> . { retain(.() { recur(escape) saved(value) }) }
            }";
        let error = check_package_sources(&[source])
            .expect_err("unused opaque callback still crosses its closure boundary");
        assert_eq!(
            &source[error.diag().0.start as usize..error.diag().0.end as usize],
            "recur // keep\n spin(x1)"
        );
        let mut repaired = source.to_owned();
        let mut edits = error.diagnostic().fixes()[0].edits.clone();
        edits.sort_by_key(|edit| std::cmp::Reverse(edit.span.start));
        for edit in edits {
            repaired.replace_range(
                edit.span.start as usize..edit.span.end as usize,
                &edit.replacement,
            );
        }
        assert!(repaired.contains("recur(escape) // keep\n spin(x1)"));
        check_package_sources(&[&repaired])
            .expect("the deferred source-owned escape repair rechecks");

        let source = "module main; import control(Bool, macro if);

            host fn drive[S][R](step: ((S -> R) & S) -> (S | R), state: S) -> R;
            host fn retain(callback: . -> Bool) -> Bool;
            rec(drive) {
                fn spin(go: Bool) -> Bool { if (go) { recur(// keep\n escape) spin(go) } else { go } };
                fn saved(go: Bool) -> Bool { retain(.() { recur(escape) saved(go) }) }
            }";
        let error = check_package_sources(&[source])
            .expect_err("a structural callback needs no escape permission");
        assert!(error.diag().1.contains("unnecessary"), "{error:?}");
        let mut repaired = source.to_owned();
        let mut edits = error.diagnostic().fixes()[0].edits.clone();
        edits.sort_by_key(|edit| std::cmp::Reverse(edit.span.start));
        for edit in edits {
            repaired.replace_range(
                edit.span.start as usize..edit.span.end as usize,
                &edit.replacement,
            );
        }
        assert!(repaired.contains("// keep"));
        check_package_sources(&[&repaired])
            .expect("the unnecessary-escape repair keeps the other re-entry call");
    }

    #[test]
    fn rec_escape_removal_fixes_recheck_continuation_and_poly_obligations() {
        for call in [
            "recur(cont, escape) spin(value)",
            "after(recur(escape) spin(value))",
            "after(recur(escape) spin[.](()))",
            "recur(poly, cont, escape) spin(value)",
        ] {
            let source = format!(
                "module main;
                host fn drive[S][R](step: ((S -> R) & S) -> (S | R), state: S) -> R;
                host fn retain(callback: . -> .) -> .;
                host fn after(value: .) -> .;
                rec(drive) {{
                    fn spin[A](value: A) -> . {{ {call} }};
                    fn saved[A](value: A) -> . {{ retain(.() {{ recur(escape) saved(value) }}) }}
                }}"
            );
            let error = check_package_sources(&[&source])
                .expect_err("escape is unnecessary inside the current step");
            assert!(error.diag().1.contains("unnecessary"), "{call}: {error:?}");
            let repaired = error.diagnostic().fixes().iter().find_map(|fix| {
                let mut repaired = source.clone();
                let mut edits = fix.edits.clone();
                edits.sort_by_key(|edit| std::cmp::Reverse(edit.span.start));
                for edit in edits {
                    repaired.replace_range(
                        edit.span.start as usize..edit.span.end as usize,
                        &edit.replacement,
                    );
                }
                check_package_sources(&[&repaired]).ok().map(|_| repaired)
            });
            assert!(
                repaired.is_some(),
                "no atomic repair rechecked for {call}: {error:?}"
            );
        }
    }

    #[test]
    fn rec_escape_simple_loop_error_owns_selected_path_and_escape_site() {
        let source = "module main; host fn drive[S][R](step: S -> (S | R), state: S) -> R;
            host fn retain(callback: . -> .) -> .;
            rec(drive) fn again(value: .) -> . { retain(.() { recur(escape) again(value) }) }";
        let error =
            check_package_sources(&[source]).expect_err("a simple provider cannot re-enter");
        let selected = source.find("rec(drive)").unwrap() as u32 + 4;
        assert_eq!(error.diag().0, Span::new(selected, selected + 5));
        assert!(
            error.diag().1.contains("cannot provide recursive re-entry"),
            "{error:?}"
        );
        assert!(
            error.diagnostic().secondary().iter().any(|label| source
                [label.span.start as usize..label.span.end as usize]
                .starts_with("recur(escape)")),
            "{error:?}"
        );
        assert!(!format!("{error:?}").contains("__rec_"), "{error:?}");
    }

    #[test]
    fn rec_loop_diagnostic_terminal_modes_keep_body_goals_distinct_and_drain_scratch() {
        let valid = "module main; host fn drive[S][R](step: S -> (S | R), state: S) -> R; ";
        let wrong =
            "module main; host fn drive[S][R](step: S -> (S | R), state: S, extra: .) -> R; ";
        for (prefix, body, is_loop_error) in [
            (
                valid,
                "host fn phantom[T](x: .) -> .; rec(drive) fn again(x: .) { phantom(x) }",
                false,
            ),
            (wrong, "rec(drive) fn again(x: .) { recur again(x) }", true),
        ] {
            let source = format!("{prefix}{body}");
            let package = lowered_package(&[("main.kio", &source)]);
            for preflight in [false, true] {
                let (elaborations, _, result) =
                    check_retained_function_at_terminal_mode(&package, "main", "again", preflight);
                let error = result.expect_err("the isolated typing defect must fail");
                assert_eq!(
                    error.diag().1.contains("the selected `rec` loop"),
                    is_loop_error,
                    "{error:?}"
                );
                assert_eq!(error.exit_code(), crate::exit_code::ExitCode::Type);
                assert!(error.type_failure_origin().is_none());
                assert_eq!(elaborations.rec_loop_diagnostic_checkpoint(), 0);
            }
        }
    }

    #[test]
    fn rec_loop_diagnostic_hints_erase_to_identical_validated_prime() {
        use crate::pass::visit_mut::{TypecheckVisitMut, walk_expr};
        struct Erase {
            count: usize,
        }
        impl TypecheckVisitMut<Lowered> for Erase {
            fn visit_expr(&mut self, expression: &mut Expr) {
                if let Expr::Call { diagnostic, .. } = expression {
                    if !matches!(diagnostic, crate::ast::RecLoopDiagnostic::None) {
                        self.count += 1;
                    }
                    *diagnostic = crate::ast::RecLoopDiagnostic::None;
                }
                walk_expr(self, expression);
            }
        }
        let package = lowered_package(&[(
            "main.kio",
            "module main; \
            host fn drive[S][R](step: S -> (S | R), state: S) -> R; \
            rec(drive) { fn first(x: .) { recur second(x) }; fn second(x: .) { recur first(x) } }",
        )]);
        let mut plain = package.clone();
        let mut erase = Erase { count: 0 };
        for entry in plain.modules_mut() {
            for item in &mut entry.module.items {
                if let Item::FnDef(definition) = item {
                    erase.visit_expr(&mut definition.body);
                }
            }
        }
        assert!(erase.count >= 4);
        let marked = check_package_preserving_normalization(&package).expect("marked program");
        assert_eq!(marked.elaborations().rec_loop_diagnostic_checkpoint(), 0);
        let marked =
            validate_substituted_package(marked.substituted()).expect("validate marked Prime");
        let plain = check_package(&plain).expect("validate plain Prime");
        for (path, entry) in marked.modules() {
            assert_eq!(
                postcard::to_allocvec(&entry.module()).unwrap(),
                postcard::to_allocvec(&plain.module(path).unwrap().module()).unwrap(),
                "diagnostic hints must not change the phase artifact",
            );
        }
    }

    #[test]
    fn projected_value_slot_ranges_follow_the_frozen_call_layer() {
        let span = Span::new(3, 9);
        let symbolic = InternedType::fresh(Type::synth_path(
            vec!["Packet".to_owned()],
            Vec::new(),
            span,
        ));
        let unit = || Type::Unit {
            meta: Meta::new(span),
        };
        let mut substitutions = HashMap::new();
        substitutions.insert(
            "Packet".to_owned(),
            Type::Product {
                left: Box::new(unit()),
                right: Box::new(unit()),
                meta: Meta::new(span),
            },
        );

        let (inferred, inferred_start, inferred_width) =
            projected_user_macro_value_slot(&symbolic, &substitutions, 0, 1, Some(1));
        let (explicit, explicit_start, explicit_width) =
            projected_user_macro_value_slot(&symbolic, &substitutions, 0, 1, Some(2));

        assert!(matches!(inferred.as_type(), Type::Product { .. }));
        assert!(matches!(explicit.as_type(), Type::Product { .. }));
        assert_eq!((inferred_start, inferred_width), (0, 1));
        assert_eq!((explicit_start, explicit_width), (0, 2));
    }

    #[test]
    fn projected_value_slot_ranges_keep_nested_left_nonfinal_abi_slots_atomic() {
        let span = Span::new(3, 9);
        let symbolic = InternedType::fresh(Type::synth_path(
            vec!["Packet".to_owned()],
            Vec::new(),
            span,
        ));
        let unit = || Type::Unit {
            meta: Meta::new(span),
        };
        let mut substitutions = HashMap::new();
        substitutions.insert(
            "Packet".to_owned(),
            Type::Product {
                left: Box::new(Type::Product {
                    left: Box::new(unit()),
                    right: Box::new(unit()),
                    meta: Meta::new(span),
                }),
                right: Box::new(unit()),
                meta: Meta::new(span),
            },
        );

        let (first, first_start, first_width) =
            projected_user_macro_value_slot(&symbolic, &substitutions, 0, 1, None);
        let (_, final_start, final_width) =
            projected_user_macro_value_slot(&symbolic, &substitutions, 1, 1, Some(3));

        assert!(matches!(
            first.as_type(),
            Type::Product { left, .. } if matches!(left.as_ref(), Type::Product { .. })
        ));
        assert_eq!((first_start, first_width), (0, 1));
        assert_eq!((final_start, final_width), (1, 2));
    }

