    #[cfg(feature = "prime")]
    #[test]
    fn generated_macro_type_binders_use_only_the_callers_type_namespace() {
        use crate::backends::kio_prime::emit_module;
        use crate::pipeline::Pipeline;
        use crate::prime::pipeline::PrimePipeline;

        fn emit_and_recheck(sources: &[(&str, &str)]) -> String {
            let package = lowered_package(sources);
            let checked = check_package(&package).expect("typecheck residual macro");
            let emitted = emit_module(checked.module("main").expect("caller module"));
            let reparsed = checked
                .modules()
                .map(|(path, entry)| {
                    let source = emit_module(entry);
                    (
                        PathBuf::from(format!("{path}.kio")),
                        parse(&source).expect("reparse emitted Prime"),
                    )
                })
                .collect();
            let (modules, _) = PrimePipeline::lower_package(reparsed, None)
                .expect("emitted residual is ordinary Prime syntax");
            let fresh = Package::build(Path::new(""), modules, None)
                .expect("assemble fresh residual package");
            fresh.resolve_imports().expect("fresh imports resolve");
            fresh
                .check_binding_origins()
                .expect("fresh bindings retain their origins");
            fresh
                .check_no_value_cycles()
                .expect("fresh residual has no value cycle");
            fresh
                .check_in_body_resolution()
                .expect("fresh residual bodies resolve");
            PrimePipeline::typecheck(&fresh).expect("fresh residual typechecks");
            emitted
        }

        for (implementation, declaration) in [
            (
                "pure fn phantom_impl( \
                   _ct: __Comptime__, _source: __Type__, value: __Checked_term__, \
                   _a: __Type__, _b: __Type__ \
                 ) -> __Checked_term__ { value }",
                "impl phantom_impl",
            ),
            (
                "pure fn phantom_impl( \
                   _ct: __Comptime__, fills: __Fill_ctx__, \
                   _source: __Type__, value: __Checked_term__, \
                   _a: __Type__, _b: __Type__ \
                 ) -> (__Checked_term__ & __Fill_ctx__) { (value, fills) }",
                "impl(fills) phantom_impl",
            ),
        ] {
            let macro_def = format!(
                "module macros; import __comptime__; {implementation} \
                 pub macro phantom : [Source] Source -> [A] [B] A {{ {declaration}; }};"
            );
            let main = "module main; import macros(macro phantom); \
                pub fn residual() -> [B] . { phantom(())[.] }";
            let baseline = emit_and_recheck(&[
                ("macros.kio", &macro_def),
                ("main.kio", main),
                ("unrelated.kio", "module unrelated;"),
            ]);
            assert!(baseline.contains(".[B_n2]"), "{baseline}");
            let grown = emit_and_recheck(&[
                ("macros.kio", &macro_def),
                ("main.kio", main),
                ("unrelated.kio", "module unrelated; type B_n2 = .;"),
            ]);
            assert_eq!(
                baseline, grown,
                "an unimported provider declaration cannot renumber a caller's residual binder"
            );

            for caller in [
                "module main; import macros(macro phantom); type B_n2 = .; \
                 pub fn residual() -> [B] . { phantom(())[.] }",
                "module main; import macros(macro phantom); import provider(B_n2); \
                 pub fn residual() -> [B] . { phantom(())[.] }",
                "module main; import macros(macro phantom); \
                 pub fn residual[B_n2]() -> [B] . { phantom(())[.] }",
                "module main; import macros(macro phantom); rec { \
                   type B_n2 = Wrap; \
                   type { Wrap: B_n2 { mk; get; }; }; \
                 } pub fn residual() -> [B] . { phantom(())[.] }",
            ] {
                let emitted = emit_and_recheck(&[
                    ("macros.kio", &macro_def),
                    ("main.kio", caller),
                    ("provider.kio", "module provider; pub type B_n2 = .;"),
                ]);
                assert!(
                    emitted.contains(".[B_n3]"),
                    "a visible type binding must remain reserved: {emitted}"
                );
            }
        }
    }

    fn lowered_package(sources: &[(&str, &str)]) -> Package {
        if sources
            .iter()
            .any(|(_, source)| source_imports_control_support(source))
        {
            return lowered_control_package(sources);
        }
        let package = Package::build(
            Path::new(""),
            sources
                .iter()
                .map(|(path, source)| (PathBuf::from(path), lowered_module(source)))
                .collect(),
            None,
        )
        .expect("package builds");
        package.resolve_imports().expect("uses resolve");
        package
    }

    fn call_sites_at(
        package: &crate::pass::resolve::Package<Lowered>,
        module: &str,
        span: Span,
    ) -> Vec<crate::ast::ExpressionSite> {
        use crate::pass::visit_mut::{TypecheckVisitMut, walk_expr};
        struct Sites {
            span: Span,
            found: Vec<crate::ast::ExpressionSite>,
        }
        impl TypecheckVisitMut<Lowered> for Sites {
            fn visit_expr(&mut self, expr: &mut Expr) {
                if expr.span() == self.span
                    && matches!(
                        expr,
                        Expr::Call { .. } | Expr::UserMacro { .. } | Expr::Ufcs { .. }
                    )
                {
                    self.found.push(expr.site());
                }
                walk_expr(self, expr);
            }
        }
        let mut sites = Sites {
            span,
            found: Vec::new(),
        };
        sites.visit_module(
            &mut package
                .module(module)
                .expect("source module")
                .module
                .clone(),
        );
        assert!(
            !sites.found.is_empty(),
            "source call must have at least one checked occurrence"
        );
        sites.found
    }

    #[test]
    fn filtered_eval_package_reestablishes_alpha_normalization() {
        let package = lowered_package(&[(
            "main.kio",
            "module main;
             fn keep[A](seed: A) -> . {
                 let inner = .[A](value: A) { value };
                 ()
             }
             fn drop() -> . { () }",
        )]);
        let selected = std::collections::BTreeSet::from([EvalFnIdentity {
            module_path: "main".to_owned(),
            name: "keep".to_owned(),
        }]);
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let typecheck_scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let filtered = typecheck_scope
            .try_renormalize_checked_for(normalized.package(), |package| {
                filtered_eval_package(package, &selected, "main", 1)
            })
            .expect("filter package");
        let filtered_module = filtered
            .package()
            .module("main")
            .expect("main module")
            .module
            .clone();
        let [Item::FnDef(keep)] = filtered_module.items.as_slice() else {
            panic!("expected only selected function");
        };
        let Expr::Let { value, .. } = &keep.body else {
            panic!("expected let body");
        };
        let Expr::FnExpr { sig, .. } = value.as_ref() else {
            panic!("expected inner function");
        };
        let [crate::ast::SignatureParam::Type(inner), ..] = sig.params.as_slice() else {
            panic!("expected inner type binder");
        };
        assert_eq!(inner.name, "A_n2");

        let repeated = filtered.renormalize_after(|package| package);
        assert_eq!(
            repeated
                .package()
                .module("main")
                .expect("main module")
                .module,
            filtered_module
        );
    }

    #[test]
    fn filtered_checked_package_preserves_occurrence_fact_correspondence() {
        let package = lowered_package(&[(
            "main.kio",
            "module main;
             fn id[A](value: A) -> A { value }
             fn keep() -> . { id(()) }
             fn drop() -> . { () }",
        )]);
        let checked = check_package_preserving_normalization(&package).expect("package checks");
        let normalized = checked.normalized();
        let keep_body = |package: &crate::pass::resolve::Package<Lowered>| {
            let module = &package.module("main").expect("main module").module;
            module
                .items
                .iter()
                .find_map(|item| match item {
                    Item::FnDef(def) if def.name == "keep" => Some(def.body.clone()),
                    _ => None,
                })
                .expect("keep function")
        };
        let original_id = keep_body(normalized.package()).site().id;
        let fact = checked
            .elaborations()
            .type_resolution_for("main", original_id, 0)
            .expect("checked generic call publishes its inferred unit type");
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let selected = std::collections::BTreeSet::from([
            EvalFnIdentity {
                module_path: "main".to_owned(),
                name: "id".to_owned(),
            },
            EvalFnIdentity {
                module_path: "main".to_owned(),
                name: "keep".to_owned(),
            },
        ]);
        let filtered = scope
            .try_renormalize_checked_for(normalized.package(), |package| {
                filtered_eval_package(package, &selected, "main", 2)
            })
            .expect("filter checked package");
        let retained_id = keep_body(filtered.package()).site().id;
        assert_eq!(original_id, retained_id);
        assert_eq!(
            checked
                .elaborations()
                .type_resolution_for("main", retained_id, 0)
                .expect("retained call still finds its checked fact")
                .resolved,
            fact.resolved,
        );
        let independent = crate::pass::alpha_normalize::normalize_package(filtered.package());
        let independent_id = keep_body(independent.package()).site().id;
        assert_ne!(retained_id, independent_id);
        assert!(
            checked
                .elaborations()
                .type_resolution_for("main", independent_id, 0)
                .is_none()
        );
        substitute::substitute_package_for_eval(&filtered, checked.elaborations())
            .expect("retained checked bodies consume the unchanged elaborations");
    }

