    #[test]
    fn artifact_source_diagnostic_survives_package_module_and_aux_collectors() {
        let caller =
            "module a;\nimport control(macro scope);\npub fn unrelated() -> . { scope { () } }";
        let declaration = "module z;\nimport a as unrelated;\ntype Hidden = .;\npub type { Exposed: Hidden { pub mk; get; }; }";
        let package = lowered_control_package(&[("a.kio", caller), ("z.kio", declaration)]);
        let assert_origin = |error: &LocatedError| {
            let start = declaration.rfind("Hidden").expect("payload") as u32;
            assert_eq!(error.file_path, PathBuf::from("z.kio"));
            assert_eq!(error.error.diag().0, Span::new(start, start + 6));
            assert_eq!(error.error.exit_code(), crate::exit_code::ExitCode::Type);
            assert!(error.error.diagnostic().help().is_some());
        };
        let package_error = check_package(&package).expect_err("private payload");
        assert_origin(&package_error);

        let errors = crate::pass::full::typecheck_module_collect_elaborations(
            "a",
            package.module("a").expect("caller"),
            &package,
        )
        .err()
        .expect("focused caller checking finds the artifact declaration error");
        assert_origin(&errors[0]);
        let call = caller.find("scope {").expect("call") as u32;
        let context = errors[0]
            .error
            .diagnostic()
            .secondary()
            .last()
            .expect("call context");
        assert_eq!(context.file.as_deref(), Some(Path::new("a.kio")));
        assert_eq!(context.span.start, call);

        let carrier_package = lowered_control_package(&[(
            "carrier.kio",
            "module carrier; import control(macro scope); fn inspect() -> . { scope { () } }",
        )]);
        let carrier = &carrier_package.module("carrier").expect("carrier").module;
        let error = FullPipeline::typecheck_aux_module(carrier, &package, None)
            .expect_err("auxiliary checking retains the source declaration");
        assert_origin(&error);
    }

    #[test]
    fn artifact_source_diagnostic_in_callers_file_keeps_its_declaration_span() {
        let source = "module a;\nimport control(macro scope);\ntype Hidden = .;\npub type { Exposed: Hidden { pub mk; get; }; }\nfn unrelated() -> . { scope { () } }";
        let package = lowered_control_package(&[("a.kio", source)]);
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let typecheck_scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(crate::pass::typecheck_core::TypeInterner::default()),
            );
        let package = normalized.package();
        let env = eval_module_env(
            &package.module("a").expect("caller").module,
            Some(package),
            typecheck_scope,
        )
        .expect("caller environment");
        let call = source.find("scope {").expect("call") as u32;
        let error = user_macro_eval_artifact(
            &env,
            &[],
            "scope",
            Span::new(call, call + 6),
            Some(&package.module("control").expect("macro").module),
        )
        .expect_err("private payload found during artifact validation");
        let error = LocatedError::new(PathBuf::from("a.kio"), error);
        let start = source.rfind("Hidden").expect("payload") as u32;
        assert_eq!(error.file_path, PathBuf::from("a.kio"));
        assert_eq!(error.error.diag().0, Span::new(start, start + 6));
        assert!(error.error.diagnostic().help().is_some());
        let context = error
            .error
            .diagnostic()
            .secondary()
            .last()
            .expect("the error crossed artifact validation at the invocation");
        assert_eq!(context.file.as_deref(), Some(Path::new("a.kio")));
        assert_eq!(context.span.start, call);
    }

    #[test]
    fn generated_artifact_expression_error_has_no_source_owned_origin() {
        let package = lowered_package(&[("main.kio", "module main; pure fn valid() -> . { () }")]);
        let package = crate::pass::alpha_normalize::normalize_package(&package);
        let artifact = substitute::substitute_package_for_eval(&package, &Elaborations::new())
            .expect("source artifact");
        let implementation = UncheckedPrimeExpr::Path {
            occurrence: crate::ast::ExpressionOccurrenceCarrier::fresh(),
            segments: vec![PathSegment::new("missing".to_owned(), Span::new(9, 16))],
            meta: Meta::new(Span::new(9, 16)),
            ext: (),
        };
        let error = validate_user_macro_eval_artifact(&artifact, &implementation, "main")
            .expect_err("generated expression references an absent value");
        assert_eq!(error.exit_code(), crate::exit_code::ExitCode::NameRes);
        assert!(error.source_file().is_none());
    }

