    fn package_file(src: &str) -> PackageFile {
        let e = crate::pass::parser::parse_package_file(&format!("package pkg;\n{src}"), None)
            .expect("parse package file");
        let e = crate::pass::desugar::desugar_package_file(e).expect("desugar");
        let (_, lowered) =
            crate::pass::label_elab::elaborate_package(Vec::new(), Some(e)).expect("elaborate");
        lowered.expect("package file")
    }

    fn ok(src: &str) {
        let result = if source_imports_control_support(src) {
            check_package_sources(&[src])
        } else if source_uses_imported_macro(src) {
            check_macro_src(src)
        } else {
            check_module(&module(src))
        };
        result.unwrap_or_else(|e| panic!("expected ok, got {e:?}"));
    }

