    #[test]
    fn unchecked_prime_recorded_elaboration_substitutes_to_prime() {
        let span = test_span();
        let node_id = NodeId(42);
        let original = Expr::UserMacro {
            occurrence: crate::ast::ExpressionOccurrence::fresh(),
            form: crate::ast::UserMacroCallForm::Ordinary,
            name: "demo".to_owned(),
            stages: Vec::new(),
            meta: Meta::new(span),
            ext: node_id,
        };
        let replay = crate::ast::Expr::<UncheckedPrime>::Unit {
            source_trivia: Default::default(),
            occurrence: Default::default(),
            meta: Meta::new(span),
        };
        let mut module = module("module x; fn replay() -> . { () }");
        let def = module
            .items
            .iter_mut()
            .find_map(|item| match item {
                crate::ast::Item::FnDef(def) if def.name == "replay" => Some(def),
                _ => None,
            })
            .expect("replay fn");
        def.body = original;
        let mut elaborations = Elaborations::new();
        elaborations.record_unchecked_prime_elaboration("x", node_id, replay, None);

        let prime = crate::pass::substitute::substitute_module(&module, &elaborations);

        let body = prime
            .items
            .iter()
            .find_map(|item| match item {
                crate::ast::Item::FnDef(def) if def.name == "replay" => Some(&def.body),
                _ => None,
            })
            .expect("replay fn");
        assert!(matches!(body, crate::ast::Expr::Unit { .. }));
    }

    fn err_totality(src: &str) -> String {
        match check_module(&module(src)) {
            Err(Error::Totality(Diagnostic { message, .. })) => message,
            Err(other) => panic!("expected Error::Totality, got {other:?}"),
            Ok(()) => panic!("expected totality error"),
        }
    }

