        control_ok(
            "module main; import control(Bool, macro if); \
             \
            host type I32; \
            host fn make[A]() -> A; \
            host fn concrete() -> I32; \
            fn generic_first(c: Bool) -> I32 { \
              let result = if (c) { make() } else { concrete() }; \
              result \
            } \
            fn generic_last(c: Bool) -> I32 { \
              let result = if (c) { concrete() } else { make() }; \
              result \
            }",
        );
