    #[test]
    fn user_macro_generated_dependency_rebuilds_artifact_type_scope() {
        let package = lowered_package(&[
            (
                "provider/types.kio",
                "module provider/types; pub type Shared = .;",
            ),
            (
                "macros.kio",
                "module macros; \
                 import __comptime__; \
                 pure fn demo_impl(ct: __Comptime__) -> __Checked_term__ { __term_unit__(ct) } \
                 macro demo : . -> . { impl demo_impl; };",
            ),
        ]);
        let normalized = crate::pass::alpha_normalize::normalize_package(&package);
        let typecheck_scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let package = normalized.package();
        let module = &package.module("macros").expect("macro module").module;
        let env = ModuleEnv::build_with_typecheck_scope(
            module,
            None,
            None,
            Some(package),
            typecheck_scope,
        )
        .expect("environment");
        let dependency = UserMacroTemplateGeneratedImport {
            module_path: "provider/types".to_owned(),
            alias: "_q0".to_owned(),
        };

        let prepared = user_macro_eval_artifact(
            &env,
            std::slice::from_ref(&dependency),
            "demo",
            test_span(),
            None,
        )
        .expect("evaluator artifact");
        let artifact = prepared.artifact();
        let entry = artifact
            .package()
            .module("macros")
            .expect("artifact module");
        assert!(entry.module.imports.iter().any(|import_| {
            matches!(
                &import_.kind,
                ImportKind::Qualified { path, alias }
                    if module_import_path(path) == dependency.module_path
                        && alias == &dependency.alias
            )
        }));

        let segments = [
            PathSegment::new(dependency.alias, test_span()),
            PathSegment::new("Shared".to_owned(), test_span()),
        ];
        let expanded = crate::pass::resolve::expand_type_import_segments_in_entry(&segments, entry);
        assert_eq!(
            expanded.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["provider", "types", "Shared"],
            "the artifact's indexed type scope must include generated dependencies"
        );
    }

    #[test]
    fn completed_source_preserves_both_consuming_exits() {
        let package = lowered_package(&[(
            "main.kio",
            "module main; pure fn id[T](value: T) -> T { value } \
             fn main() -> . { id(()) }",
        )]);
        let complete = check_package_preserving_normalization(&package)
            .expect("check source")
            .complete()
            .expect("complete source");
        assert!(
            complete
                .source()
                .checked()
                .normalized()
                .module("main")
                .is_some()
        );
        let expected = postcard::to_allocvec(
            complete
                .runtime()
                .module("main")
                .expect("runtime module")
                .module(),
        )
        .expect("runtime module bytes");
        let source = complete.into_source();
        let artifact = source
            .eval_artifact()
            .expect("completed evaluator artifact");
        let module = artifact.module("main").expect("evaluator module");
        let body = module
            .module
            .items
            .iter()
            .find_map(|item| match item {
                Item::FnDef(def) if def.name == "main" => Some(&def.body),
                _ => None,
            })
            .expect("main body");
        let ctx = crate::normalization::AuthenticatedEvalCtx::for_module(
            artifact.prepare_module("main").expect("module preparation"),
        );
        assert!(matches!(
            crate::normalization::eval_authenticated(body, &crate::normalization::Env::new(), &ctx),
            crate::normalization::Value::Unit,
        ));
        let runtime = check_package_preserving_normalization(&package)
            .expect("check compile source")
            .complete()
            .expect("complete compile source")
            .into_runtime();
        assert_eq!(
            expected,
            postcard::to_allocvec(
                runtime
                    .module("main")
                    .expect("compile-only runtime module")
                    .module(),
            )
            .expect("compile-only runtime module bytes")
        );
    }

