    #[test]
    fn widen_prod_check_against_return_works() {
        // `widen_prod` extends a source product with `.` slots — a
        // unit-only widening so we don't need to bring in duplication.
        // Source is `.`; target is `(. & .)`. The engine synthesizes
        // the extra slot from the source's identity unit.
        ok("module x; \
            fn pad(x: .) -> (. & .) { widen_prod(x) }");
    }

    #[test]
    fn widen_sum_check_against_return_works() {
        // `widen_sum` extends a source sum with an unreachable arm.
        // Source is `.`; target is `(. | Bool)`. The engine
        // synthesizes the extra arm as unreachable (the source flows
        // into the `.` arm).
        ok("module x; host type Bool; \
            fn extend(x: .) -> (. | Bool) { widen_sum(x) }");
    }

    #[test]
    fn recursive_instances_each_publish_their_residual_plan() {
        let source = "module x; \
            host type I32; \
            host fn nil[A]() -> A; \
            host fn loop[S][R](step: S -> (S | R), seed: S) -> R; \
            rec(loop) { \
              pub fn keep(value: .) -> I32 { recur walk(value) }; \
              fn walk(_value: .) -> I32 { let saved = nil[I32]; saved() } \
            }";
        let package = lowered_package(&[("x.kio", source)]);
        let checked = check_package_preserving_normalization(&package)
            .expect("recursive clones merge one final residual plan per source call");
        let spelling = "nil[I32]";
        let start = source.find(spelling).expect("type-only call spelling") as u32;
        let span = Span::new(start, start + spelling.len() as u32);
        let sites = call_sites_at(checked.normalized().package(), "x", span);
        assert!(
            !sites.is_empty(),
            "type-only source occurrence keeps a call-site fact"
        );
        for site in sites {
            let residual = checked
                .elaborations()
                .call_residual_eta_type_for("x", site.id)
                .expect("type-only call retains its final residual plan");
            assert!(
                residual.identity_canonical,
                "the final residual plan must carry canonical identity"
            );
        }
    }

