    fn assert_terminal_public_layer_work(
        reserved_slots: usize,
        child_opens: usize,
        expected_children: usize,
        synthesized_children: usize,
        marker_finishes: usize,
        open_body_observations: usize,
    ) {
        let work = crate::pass::typecheck_core::apply::terminal_public_layer_work();
        assert_eq!(work.reserved_slots, reserved_slots, "terminal slot count");
        assert_eq!(
            work.parent_goal_growth, reserved_slots,
            "every omitted terminal binder must add one current-parent goal"
        );
        assert_eq!(work.child_opens, child_opens, "terminal child count");
        assert_eq!(
            work.child_goal_count, 0,
            "terminal children must own no inferred binder goals"
        );
        assert_eq!(
            work.expected_children, expected_children,
            "expected terminal child count"
        );
        assert_eq!(
            work.synthesized_children, synthesized_children,
            "synthesized terminal child count"
        );
        assert_eq!(
            work.marker_finishes, marker_finishes,
            "terminal marker completion count"
        );
        assert_eq!(
            work.open_body_observations, open_body_observations,
            "mixed open terminal header count"
        );
        if child_opens == 0 {
            assert!(work.last_parent.is_none() && work.last_child.is_none());
        } else {
            assert_ne!(
                work.last_parent, work.last_child,
                "the terminal child must be distinct from its action parent"
            );
        }
    }

    fn assert_final_macro_successor_work(
        terminal_continues: usize,
        migrated_descents: usize,
        earlier_terminal_yields: usize,
        earlier_nonterminal_yields: usize,
    ) {
        let work = crate::pass::typecheck_core::apply::final_macro_successor_work();
        assert_eq!(
            work.terminal_continues, terminal_continues,
            "Final successor work: {work:?}"
        );
        assert_eq!(
            work.migrated_descents, migrated_descents,
            "Final successor work: {work:?}"
        );
        assert_eq!(
            work.earlier_terminal_yields, earlier_terminal_yields,
            "Final successor work: {work:?}"
        );
        assert_eq!(
            work.earlier_nonterminal_yields, earlier_nonterminal_yields,
            "Final successor work: {work:?}"
        );
    }

    const CALL_SHAPE_PARITY_PROVIDER: &str = "module provider; \
        import __comptime__; \
        pub fn ordinary[Source](_source: Source)[A](value: A) -> A { value } \
        pure fn required_impl( \
            _ct: __Comptime__, \
            _source: __Type__, \
            _ignored: __Checked_term__, \
            _a: __Type__, \
            value: __Checked_term__ \
          ) -> __Checked_term__ { value } \
        pub macro required : [Source] Source -> [A] A -> A { impl required_impl; }; \
        pub fn ordinary_phantom[Left][Right][Phantom](left: Left, right: Right) \
          -> Left & Right { (left, right) } \
        pure fn required_phantom_impl( \
            _ct: __Comptime__, \
            _left: __Type__, \
            _right: __Type__, \
            _phantom: __Type__, \
            value: __Checked_term__ \
          ) -> __Checked_term__ { value } \
        pub macro required_phantom : [Left] [Right] [Phantom] (Left & Right) -> (Left & Right) { impl required_phantom_impl; };";

    fn source_span(source: &str, needle: &str) -> Span {
        let start = source.find(needle).expect("test expression is present");
        Span::new(
            u32::try_from(start).expect("test source fits in a span"),
            u32::try_from(start + needle.len()).expect("test source fits in a span"),
        )
    }

    fn retained_call_at(package: &Package, module_path: &str, span: Span) -> Expr {
        struct Finder {
            span: Span,
            found: Vec<Expr>,
        }

        impl crate::pass::visit_mut::TypecheckVisitMut<Lowered> for Finder {
            fn visit_expr(&mut self, expr: &mut Expr) {
                let is_call = matches!(expr, Expr::UserMacro { .. })
                    || matches!(
                        expr,
                        Expr::Ufcs {
                            macro_call: Some(_),
                            ..
                        }
                    );
                if is_call && expr.span() == self.span {
                    self.found.push(expr.clone());
                }
                crate::pass::visit_mut::walk_expr(self, expr);
            }
        }

        let mut module = package
            .module(module_path)
            .expect("test module exists")
            .module
            .clone();
        let mut finder = Finder {
            span,
            found: Vec::new(),
        };
        crate::pass::visit_mut::TypecheckVisitMut::visit_module(&mut finder, &mut module);
        assert_eq!(
            finder.found.len(),
            1,
            "expected one retained call at {span:?}, found {:#?}",
            finder.found
        );
        finder.found.pop().expect("one retained call")
    }

    fn retained_staged_literal_call_within(
        package: &Package,
        written: Span,
        expected_name: &str,
    ) -> Expr {
        struct Finder {
            written: Span,
            found: Vec<Expr>,
        }
        impl crate::pass::visit_mut::TypecheckVisitMut<Lowered> for Finder {
            fn visit_expr(&mut self, expr: &mut Expr) {
                if matches!(expr, Expr::UserMacro { .. })
                    && self.written.start <= expr.span().start
                    && expr.span().end <= self.written.end
                {
                    self.found.push(expr.clone());
                }
                crate::pass::visit_mut::walk_expr(self, expr);
            }
        }
        let mut finder = Finder {
            written,
            found: Vec::new(),
        };
        crate::pass::visit_mut::TypecheckVisitMut::visit_module(
            &mut finder,
            &mut package
                .module("main")
                .expect("caller module")
                .module
                .clone(),
        );
        assert_eq!(finder.found.len(), 1, "one macro in the written call");
        let original = finder.found.pop().expect("one retained call");
        let Expr::UserMacro { name, stages, .. } = &original else {
            unreachable!("the finder selected only UserMacro expressions")
        };
        assert_eq!(name, expected_name);
        let [value_stage, type_stage] = stages.as_slice() else {
            panic!("one value stage followed by one explicit type stage")
        };
        let [
            CallArg::Value(Expr::IntLit {
                digits,
                annotation: Some(Type::Path { segments, args, .. }),
                ..
            }),
        ] = value_stage.args.as_slice()
        else {
            panic!("the single literal operand retains its written annotation")
        };
        assert_eq!(digits, "0");
        assert!(args.is_empty());
        let [carrier] = segments.as_slice() else {
            panic!("the literal carrier is one local type name")
        };
        assert_eq!(carrier.as_str(), "I32");
        assert!(matches!(
            type_stage.args.as_slice(),
            [CallArg::Type(Type::Infer { .. })]
        ));
        original
    }

    fn check_retained_success(
        package: &Package,
    ) -> (
        CheckedLoweredPackage,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let checked = check_normalized_package_with_scope_and_execution(
            normalized,
            scope.clone(),
            crate::pass::typecheck_core::TypecheckExecution::Sequential,
        )
        .expect("retained action closes");
        (checked, scope)
    }

    fn check_retained_error_with_scope(
        package: &Package,
    ) -> (
        Error,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        match check_normalized_package_with_scope_and_execution(
            normalized,
            scope.clone(),
            crate::pass::typecheck_core::TypecheckExecution::Sequential,
        ) {
            Ok(_) => panic!("the retained package unexpectedly typechecked"),
            Err(errors) => {
                let error = errors
                    .into_iter()
                    .next()
                    .expect("the retained package returned an empty error set")
                    .error;
                (error, scope)
            }
        }
    }

    fn check_retained_error(package: &Package) -> Error {
        check_retained_error_with_scope(package).0
    }

    fn check_retained_function_at_final(
        package: &Package,
        module_path: &str,
        function_name: &str,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Result<(), Error>,
    ) {
        check_retained_function_at_terminal_mode(package, module_path, function_name, false)
    }

    fn check_retained_function_from_final_preflight(
        package: &Package,
        module_path: &str,
        function_name: &str,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Result<(), Error>,
    ) {
        check_retained_function_at_terminal_mode(package, module_path, function_name, true)
    }

    fn check_retained_function_at_terminal_mode(
        package: &Package,
        module_path: &str,
        function_name: &str,
        preflight: bool,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Result<(), Error>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let package = normalized.package();
        let module = &package
            .module(module_path)
            .expect("test module exists")
            .module;
        let (item_index, function) = module
            .items
            .iter()
            .enumerate()
            .find_map(|(index, item)| match item {
                Item::FnDef(function) if function.name == function_name => Some((index, function)),
                _ => None,
            })
            .unwrap_or_else(|| panic!("test module has no `{function_name}` function"));
        let env = crate::pass::typecheck_core::ModuleEnv::build_with_typecheck_scope(
            module,
            None,
            None,
            Some(package),
            scope.clone(),
        )
        .expect("Final-mode test module environment");
        let mut elaborations = Elaborations::new();
        let result = {
            let mut tcx = TypeCtx::new(&env, &mut elaborations).at_item(item_index);
            for parameter in function.sig.value_params() {
                tcx.push_value(
                    parameter.name.clone(),
                    parameter
                        .ty
                        .clone()
                        .expect("Final-mode test parameter annotation"),
                );
            }
            let expected = InternedType::fresh(function.ret.clone());
            if preflight {
                crate::pass::typecheck_core::apply::run_general_ordinary_value_from_final_preflight_for_test(
                    &function.body,
                    Some(&expected),
                    &mut tcx,
                )
                .map(|_| ())
            } else {
                crate::pass::typecheck_core::apply::run_general_ordinary_value_at_final_for_test(
                    &function.body,
                    Some(&expected),
                    &mut tcx,
                )
                .map(|_| ())
            }
        };
        let result = result.and_then(|()| {
            elaborations.discharge_deferred_with_execution(
                &env,
                crate::pass::typecheck_core::TypecheckExecution::Sequential,
            )
        });
        (elaborations, scope, result)
    }

    fn check_retained_module(
        package: &Package,
        module_path: &str,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Result<(), Vec<Error>>,
    ) {
        let normalized = crate::pass::alpha_normalize::normalize_package(package);
        let scope =
            crate::pass::typecheck_core::PackageTypecheckScope::fresh_for_normalized_package(
                &normalized,
                std::sync::Arc::new(
                    crate::pass::typecheck_core::TypeInterner::<Lowered>::default(),
                ),
            );
        let mut elaborations = Elaborations::new();
        // These causal oracles use thread-local observations, like the full-package helper.
        let result = crate::pass::typecheck_core::check_module_sequential_for_test(
            normalized.package(),
            module_path,
            &mut elaborations,
            scope.clone(),
        );
        (elaborations, scope, result)
    }

    fn check_retained_module_error(
        package: &Package,
        module_path: &str,
    ) -> (
        Elaborations,
        std::sync::Arc<crate::pass::typecheck_core::PackageTypecheckScope<Lowered>>,
        Vec<Error>,
    ) {
        let (elaborations, scope, result) = check_retained_module(package, module_path);
        (
            elaborations,
            scope,
            result.expect_err("retained module is rejected"),
        )
    }

    fn assert_retained_call_unpublished(
        elaborations: &Elaborations,
        module_path: &str,
        original: &Expr,
    ) {
        let node_id = elaboration_node_id(original).expect("retained call has a node id");
        assert!(
            elaborations
                .elaboration_for(module_path, original)
                .is_none(),
            "failed retained call published its replacement"
        );
        assert!(
            elaborations
                .position_index()
                .type_at(module_path, original.span())
                .is_none(),
            "failed retained call published its position type"
        );
        assert!(
            elaborations.deferred.iter().all(|deferred| match deferred {
                DeferredElaboration::UserMacro(obligation) => obligation.node_id != node_id,
            }),
            "failed retained call escaped in the deferred queue"
        );
    }

    fn assert_retained_call_published(
        elaborations: &Elaborations,
        module_path: &str,
        original: &Expr,
    ) {
        assert!(
            elaborations
                .elaboration_for(module_path, original)
                .is_some(),
            "successful retained call did not publish its replacement"
        );
        assert!(
            elaborations
                .position_index()
                .type_at(module_path, original.span())
                .is_some(),
            "successful retained call did not publish its position type"
        );
    }

    fn assert_marked_polymorphic_return_error(errors: &[Error], span: Span) {
        assert_eq!(
            errors.len(),
            1,
            "the missing result anchor must be the only diagnostic: {errors:#?}"
        );
        let Error::Type(diagnostic) = &errors[0] else {
            panic!("the missing result anchor must be a type error: {errors:#?}")
        };
        assert_eq!(diagnostic.span, span);
        assert_eq!(
            diagnostic.message,
            "this polymorphic `fn` needs an independently known result type before its body is checked"
        );
        assert_eq!(
            diagnostic.help(),
            Some("write a concrete return annotation or provide an enclosing expected result")
        );
    }

    #[test]
    fn retained_fixed_result_macro_closes_and_evaluates_once() {
        check_package_sources(&["module main; \
            host type I32; \
            host fn witness() -> I32; \
            fn identity[T](value: T) -> T { value } \
            fn consume[T](_f: T -> T, _value: T) -> . { () } \
            fn run() -> . { consume(.(value) { identity(value) }, witness()) }"])
        .expect("ordinary identity call closes in the surrounding retained frontier");

        let main = "module main; \
            import macros(macro same); \
            host type I32; \
            host fn witness() -> I32; \
            fn consume[T](_f: T -> T, _value: T) -> . { () } \
            fn run() -> . { consume(.(value) { same(value) }, witness()) }";
        let package =
            lowered_package(&[("macros.kio", RETAINED_ACTION_MACROS), ("main.kio", main)]);
        let original = retained_call_at(&package, "main", source_span(main, "same(value)"));
        let (checked, scope) = check_retained_success(&package);

        assert!(
            checked
                .elaborations()
                .elaboration_for("main", &original)
                .is_some(),
            "closed fixed-result action publishes its replacement"
        );
        assert_eq!(scope.memo().user_macro_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("closed fixed-result action survives standalone Prime validation");
    }

    #[test]
    fn retained_multi_goal_type_producing_macro_closes_and_evaluates_once() {
        let main = "module main; \
            import macros(macro infer_pair); \
            host type I32 role(i32); \
            host type String role(str); \
            fn run() -> I32 & String { \
              let pair = infer_pair((0[I32], \"closed\"[String])); \
              pair \
            }";
        let package =
            lowered_package(&[("macros.kio", RETAINED_ACTION_MACROS), ("main.kio", main)]);
        let original = retained_call_at(
            &package,
            "main",
            source_span(main, "infer_pair((0[I32], \"closed\"[String]))"),
        );
        let (checked, scope) = check_retained_success(&package);

        assert!(
            checked
                .elaborations()
                .elaboration_for("main", &original)
                .is_some(),
            "closed type-producing action publishes its replacement"
        );
        let Some(Type::Product { left, right, .. }) = checked
            .elaborations()
            .position_index()
            .type_at("main", original.span())
        else {
            panic!("the type-producing call must publish its concrete product result")
        };
        let path_ends_in = |ty: &Type, expected: &str| {
            matches!(
                ty,
                Type::Path { segments, .. }
                    if segments.last().is_some_and(|segment| segment.as_str() == expected)
            )
        };
        assert!(
            path_ends_in(left, "I32")
                && path_ends_in(right, "String")
                && !crate::pass::typecheck_core::type_contains_goal(left)
                && !crate::pass::typecheck_core::type_contains_goal(right),
            "the type-producing call published a residual result: {left:?} & {right:?}"
        );
        assert_eq!(scope.memo().user_macro_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("closed multi-goal action survives standalone Prime validation");
    }

    #[test]
    fn retained_initial_layer_natural_result_evaluates_once_and_closes_its_goal() {
        let macro_def = "module macros; \
            import __comptime__; \
            pure fn infer_unit_impl(ct: __Comptime__, _a: .) -> __Checked_term__ { \
              __term_unit__(ct) \
            } \
            pub macro infer_unit : [A] . -> A { impl infer_unit_impl; };";
        let main = "module main; \
            import macros(macro infer_unit); \
            fn run() -> . { let _inferred = infer_unit(); () }";
        let package = lowered_package(&[("macros.kio", macro_def), ("main.kio", main)]);
        let original = retained_call_at(&package, "main", source_span(main, "infer_unit()"));
        let (checked, scope) = check_retained_success(&package);

        assert!(
            matches!(
                checked
                    .elaborations()
                    .position_index()
                    .type_at("main", original.span()),
                Some(Type::Unit { .. })
            ),
            "the evaluator-returned Unit type must close the initial A occurrence"
        );
        assert_eq!(scope.memo().user_macro_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("the initial-owner type-producing action survives Prime validation");
    }

    #[test]
    fn natural_result_does_not_erase_an_unrelated_phantom_binder() {
        let macro_def = "module macros; \
            import __comptime__; \
            pure fn infer_unit_impl( \
                ct: __Comptime__, \
                _phantom: __Type__, \
                _result: . \
              ) -> __Checked_term__ { __term_unit__(ct) } \
            pub macro infer_unit : [Phantom][Result] . -> Result { impl infer_unit_impl; };";
        let main = "module main; \
            import macros(macro infer_unit); \
            fn run() -> . { let _inferred = infer_unit[_][_]; () }";
        let package = lowered_package(&[("macros.kio", macro_def), ("main.kio", main)]);
        let original = retained_call_at(&package, "main", source_span(main, "infer_unit[_][_]"));
        let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

        assert!(
            errors.iter().any(|error| {
                let message = &error.diagnostic().message;
                message.contains("cannot infer type argument") && message.contains("Phantom")
            }),
            "the phantom binder must be rejected before result inference: {errors:#?}"
        );
        assert_retained_call_unpublished(&elaborations, "main", &original);
        assert_eq!(
            scope.memo().user_macro_template_executions(),
            0,
            "an unresolved required phantom slot must block evaluator execution"
        );
    }

    #[test]
    fn natural_result_does_not_erase_a_shadowed_binder() {
        let macro_def = "module macros; \
            import __comptime__; \
            pure fn infer_unit_impl( \
                ct: __Comptime__, \
                _outer: __Type__, \
                _inner: . \
              ) -> __Checked_term__ { __term_unit__(ct) } \
            pub macro infer_unit : [Shadowed] . -> [Shadowed] Shadowed { impl infer_unit_impl; };";
        let main = "module main; \
            import macros(macro infer_unit); \
            fn run() -> . { let _inferred = infer_unit[_](())[ _]; () }";
        let package = lowered_package(&[("macros.kio", macro_def), ("main.kio", main)]);
        let original =
            retained_call_at(&package, "main", source_span(main, "infer_unit[_](())[ _]"));
        let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

        assert_eq!(
            scope.memo().user_macro_template_executions(),
            0,
            "an unresolved required slot shadowed before the result must block evaluator execution"
        );
        assert!(
            errors.iter().any(|error| {
                let message = &error.diagnostic().message;
                message.contains("cannot infer type argument") && message.contains("Shadowed")
            }),
            "the outer shadowed binder must be rejected before result inference: {errors:#?}"
        );
        assert_retained_call_unpublished(&elaborations, "main", &original);
    }

    #[test]
    fn phantom_type_binders_follow_public_inference_across_call_forms() {
        // The product domain makes first/last receiver placement observably
        // distinct; `Phantom` remains unconstrained in every spelling.
        for (form, ordinary_call, macro_call) in [
            (
                "prefix",
                "ordinary_phantom[_][_][_](0, \"right\")",
                "MACRO[_][_][_](0, \"right\")",
            ),
            (
                "fully-elided prefix",
                "ordinary_phantom(0, \"right\")",
                "MACRO(0, \"right\")",
            ),
            (
                "receiver-first UFCS",
                "0.>ordinary_phantom[_][_][_](\"right\")",
                "0.>MACRO[_][_][_](\"right\")",
            ),
            (
                "fully-elided receiver-first UFCS",
                "0.>ordinary_phantom(\"right\")",
                "0.>MACRO(\"right\")",
            ),
            (
                "receiver-last UFCS",
                "\"right\".>>ordinary_phantom[_][_][_](0)",
                "\"right\".>>MACRO[_][_][_](0)",
            ),
            (
                "fully-elided receiver-last UFCS",
                "\"right\".>>ordinary_phantom(0)",
                "\"right\".>>MACRO(0)",
            ),
            (
                "argument-first UFCS",
                "ordinary_phantom[_][_][_](\"right\").<<0",
                "MACRO[_][_][_](\"right\").<<0",
            ),
            (
                "fully-elided argument-first UFCS",
                "ordinary_phantom(\"right\").<<0",
                "MACRO(\"right\").<<0",
            ),
            (
                "argument-last UFCS",
                "ordinary_phantom[_][_][_](0).<\"right\"",
                "MACRO[_][_][_](0).<\"right\"",
            ),
            (
                "fully-elided argument-last UFCS",
                "ordinary_phantom(0).<\"right\"",
                "MACRO(0).<\"right\"",
            ),
        ] {
            for (callable, call, retained) in [
                ("ordinary", ordinary_call.to_owned(), false),
                (
                    "Required",
                    macro_call.replace("MACRO", "required_phantom"),
                    true,
                ),
            ] {
                let case = format!("{callable} {form}");
                let main = format!(
                    "module main; \
                 import provider(ordinary_phantom, macro required_phantom); \
                 host type I32 role(i32); \
                 host type String role(str); \
                 fn run() -> I32 & String {{ {call} }}"
                );
                let package = lowered_package(&[
                    ("provider.kio", CALL_SHAPE_PARITY_PROVIDER),
                    ("main.kio", main.as_str()),
                ]);
                let original = retained
                    .then(|| retained_call_at(&package, "main", source_span(main.as_str(), &call)));
                let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

                assert!(
                    errors.iter().any(|error| {
                        let message = &error.diagnostic().message;
                        message.contains("cannot infer type argument")
                            && message.contains("Phantom")
                    }),
                    "{case} changed the public phantom-binder result: {errors:#?}"
                );
                if let Some(original) = original {
                    assert_retained_call_unpublished(&elaborations, "main", &original);
                }
                assert_eq!(
                    scope.memo().user_macro_template_executions(),
                    0,
                    "{case} evaluated a macro with an unsolved public phantom binder"
                );
            }
        }
    }

    #[test]
    fn macro_abi_cannot_generalize_an_unsolved_public_call() {
        for (case, call, retained) in [
            ("ordinary prefix", "ordinary(0[I32])[_]", false),
            ("Required prefix", "required(0[I32])[_]", true),
            ("ordinary UFCS", "(0[I32].>ordinary)[_]", false),
            ("Required UFCS", "(0[I32].>required)[_]", true),
        ] {
            let main = format!(
                "module main; \
                 import provider(ordinary, macro required); \
                 host type I32 role(i32); \
                 fn run() -> . {{ let _residual = {call}; () }}"
            );
            let package = lowered_package(&[
                ("provider.kio", CALL_SHAPE_PARITY_PROVIDER),
                ("main.kio", main.as_str()),
            ]);
            let original = retained.then(|| {
                retained_staged_literal_call_within(
                    &package,
                    source_span(main.as_str(), call),
                    "required",
                )
            });
            let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

            assert!(
                errors.iter().any(|error| {
                    let message = &error.diagnostic().message;
                    message.contains("cannot infer type argument") && message.contains('A')
                }),
                "{case} changed the public call's unsolved-type result: {errors:#?}"
            );
            if let Some(original) = original {
                assert_retained_call_unpublished(&elaborations, "main", &original);
            }
            assert_eq!(
                scope.memo().user_macro_template_executions(),
                0,
                "{case} evaluated a macro before its public call was selected"
            );
        }
    }

