    #[test]
    fn match_pair_transparency_causal_matrix() {
        let result = std::thread::Builder::new()
            .name("match-pair-causal-matrix".to_owned())
            // The real match support package overflows libtest's default
            // debug stack; 8 MiB is the smallest measured passing bound.
            .stack_size(8 * 1024 * 1024)
            .spawn(run_match_pair_transparency_causal_matrix)
            .expect("spawn match pair causal matrix")
            .join();
        if let Err(payload) = result {
            std::panic::resume_unwind(payload);
        }
    }

    fn run_match_pair_transparency_causal_matrix() {
        use crate::pass::typecheck_core::apply::fills::ProjectedLeafObservation as Leaf;

        fn reset_observations(span: Span) {
            crate::pass::typecheck_core::apply::reset_lambda_body_entries("main");
            crate::pass::typecheck_core::apply::fills::reset_projected_source_observations(
                "main", span,
            );
            crate::pass::typecheck_core::apply::fills::reset_pair_wrapper_finalizations();
        }

        fn leaf(path: &[u8], template_index: u32, producer: Option<u32>) -> Leaf {
            Leaf {
                path: path.to_vec(),
                template_index,
                producer,
            }
        }

        fn lambda_spans(source: &str, needles: &[&str]) -> Vec<Span> {
            let mut spans = Vec::new();
            for needle in needles {
                let matches = source.match_indices(needle).collect::<Vec<_>>();
                assert_eq!(
                    matches.len(),
                    1,
                    "the causal source must contain one exact `{needle}` lambda"
                );
                let (start, _) = matches[0];
                spans.push(Span::new(
                    u32::try_from(start).expect("test source fits in a span"),
                    u32::try_from(start + needle.len()).expect("test source fits in a span"),
                ));
            }
            spans
        }

        fn retained_match_packet_spans(call: &Expr) -> (Span, Span) {
            let Expr::UserMacro { stages, .. } = call else {
                panic!("the causal match call lost its retained macro form")
            };
            let [stage] = stages.as_slice() else {
                panic!("the causal match call must have one written packet stage")
            };
            let [crate::ast::CallArg::Value(packet)] = stage.args.as_slice() else {
                panic!("the causal match call must retain one whole value packet")
            };
            let Expr::Call { callee, args, .. } = packet else {
                panic!("the causal match packet must be an ordinary pair")
            };
            assert!(matches!(callee.as_ref(), Expr::Path { segments, .. }
                if matches!(segments.as_slice(), [name] if name.as_str() == "__pair__")));
            let values = args
                .iter()
                .filter_map(|arg| match arg {
                    crate::ast::CallArg::Value(value) => Some(value),
                    crate::ast::CallArg::Type(_) => None,
                })
                .collect::<Vec<_>>();
            let [_source, clauses] = values.as_slice() else {
                panic!("the causal match packet must keep source and whole clauses distinct")
            };
            (packet.span(), clauses.span())
        }

        fn assert_lambda_entries(
            label: &str,
            source: &str,
            needles: &[&str],
            expected_executions: &[usize],
        ) {
            let expected_spans = lambda_spans(source, needles);
            let entries = crate::pass::typecheck_core::apply::take_lambda_body_entries();
            assert_eq!(
                entries.iter().map(|entry| entry.span).collect::<Vec<_>>(),
                expected_spans,
                "{label} must enter each target lambda body exactly once"
            );
            assert_eq!(
                entries
                    .iter()
                    .map(|entry| entry.macro_executions)
                    .collect::<Vec<_>>(),
                expected_executions,
                "{label} entered its lambda bodies on the wrong side of match evaluation"
            );
        }

        fn assert_source_topology(label: &str, span: Span, expected_leaves: Vec<Leaf>) {
            let observations =
                crate::pass::typecheck_core::apply::fills::take_projected_source_observations();
            assert_eq!(
                observations.len(),
                1,
                "{label} must reserve exactly one target source at {span:?}: {observations:#?}"
            );
            assert_eq!(
                observations[0], expected_leaves,
                "{label} changed the reserved pair recipe or producer topology"
            );
        }

        #[allow(clippy::too_many_arguments)] // The causal matrix keeps independent oracle dimensions explicit.
        fn assert_success(
            label: &str,
            package: &Package,
            source: &str,
            call: &str,
            lambda_needles: &[&str],
            expected_body_executions: &[usize],
            expected_leaves: Vec<Leaf>,
            expected_pair_closes: usize,
        ) {
            let spanned_source = add_macro_imports(source);
            let original = retained_call_at(package, "main", source_span(&spanned_source, call));
            let (projected_span, _) = retained_match_packet_spans(&original);
            reset_observations(projected_span);
            let (elaborations, scope, result) = check_retained_module(package, "main");
            result.expect("the caller closes independently of support-library body checks");

            assert_eq!(
                scope.memo().user_macro_template_executions(),
                1,
                "{label} must evaluate match exactly once"
            );
            assert_retained_call_published(&elaborations, "main", &original);
            assert_source_topology(label, projected_span, expected_leaves);
            assert_eq!(
                crate::pass::typecheck_core::apply::fills::pair_wrapper_finalizations(),
                expected_pair_closes,
                "{label} finalized the wrong number of certified pair wrappers"
            );
            assert_lambda_entries(
                label,
                &spanned_source,
                lambda_needles,
                expected_body_executions,
            );
            let (checked, _) = check_retained_success(package);
            validate_substituted_package(checked.substituted()).unwrap_or_else(|error| {
                panic!("{label} must survive Prime validation: {error:#?}")
            });
        }

        let left = ".(_left: Left) { identity_i32 }";
        let right = ".(_right: Right) { identity_i32 }";
        let common = "host type Left; host type Right; host type I32 role(i32); \
            fn identity_i32(value: I32) -> I32 { value }";

        let canonical_source = format!(
            "module main; {common} \
             fn run(source: Left | Right) -> I32 -> I32 {{ \
               match(source) {{ ({left}, {right}) }} \
             }}"
        );
        let canonical_clauses = format!("({left}, {right})");
        let canonical_call = format!("match(source) {{ {canonical_clauses} }}");
        let canonical_package =
            lowered_macro_package(&canonical_source).expect("lower canonical match package");

        assert_success(
            "canonical pending pair",
            &canonical_package,
            &canonical_source,
            &canonical_call,
            &[left, right],
            &[1, 1],
            vec![
                leaf(&[0], 0, None),
                leaf(&[1, 0], 1, Some(0)),
                leaf(&[1, 1], 2, Some(1)),
            ],
            2,
        );

        let bypass_spanned_source = add_macro_imports(&canonical_source);
        let bypass_original = retained_call_at(
            &canonical_package,
            "main",
            source_span(&bypass_spanned_source, &canonical_call),
        );
        let (bypass_projected_span, bypass_clauses_span) =
            retained_match_packet_spans(&bypass_original);

        reset_observations(bypass_projected_span);
        let (baseline_elaborations, baseline_scope, baseline_result) =
            check_retained_function_from_final_preflight(&canonical_package, "main", "run");
        baseline_result.expect("the certified pair must complete from FinalPreflight");
        assert_eq!(baseline_scope.memo().user_macro_template_executions(), 1);
        assert_retained_call_published(&baseline_elaborations, "main", &bypass_original);
        assert_source_topology(
            "certified canonical pair from FinalPreflight",
            bypass_projected_span,
            vec![
                leaf(&[0], 0, None),
                leaf(&[1, 0], 1, Some(0)),
                leaf(&[1, 1], 2, Some(1)),
            ],
        );
        assert_eq!(
            crate::pass::typecheck_core::apply::fills::pair_wrapper_finalizations(),
            2
        );
        assert_lambda_entries(
            "certified canonical pair from FinalPreflight",
            &bypass_spanned_source,
            &[left, right],
            &[1, 1],
        );

        reset_observations(bypass_projected_span);
        let bypass = crate::pass::typecheck_core::apply::fills::disable_pair_transparency_at(
            "main",
            bypass_clauses_span,
        );
        let (bypass_elaborations, bypass_scope, bypass_result) =
            check_retained_function_from_final_preflight(&canonical_package, "main", "run");
        bypass_result.expect("the independent opaque clause pair must complete before match");
        assert_eq!(bypass_scope.memo().user_macro_template_executions(), 1);
        assert_retained_call_published(&bypass_elaborations, "main", &bypass_original);
        assert_source_topology(
            "certificate-bypassed independent pair",
            bypass_projected_span,
            vec![leaf(&[0], 0, None), leaf(&[1], 1, Some(0))],
        );
        assert_eq!(
            crate::pass::typecheck_core::apply::fills::pair_wrapper_finalizations(),
            1,
            "only the enclosing public packet retains a pair certificate"
        );
        assert_lambda_entries(
            "certificate-bypassed independent pair",
            &bypass_spanned_source,
            &[left, right],
            &[0, 0],
        );
        assert_eq!(
            bypass.hits(),
            1,
            "nested operand staging must bypass the exact canonical clause pair once"
        );
        drop(bypass);

        let ordinary_source_expr = format!("exact({left}, {right})");
        let ordinary_call = format!("match(source) {{ {ordinary_source_expr} }}");
        let ordinary_source = format!(
            "module main; {common} \
             fn exact[A][B](left: A, right: B) -> A & B {{ (left, right) }} \
             fn run(source: Left | Right) -> I32 -> I32 {{ {ordinary_call} }}"
        );
        let ordinary_package =
            lowered_macro_package(&ordinary_source).expect("lower ordinary-wrapper match package");
        assert_success(
            "independently typed ordinary exact-scheme wrapper",
            &ordinary_package,
            &ordinary_source,
            &ordinary_call,
            &[left, right],
            &[0, 0],
            vec![leaf(&[0], 0, None), leaf(&[1], 1, Some(0))],
            1,
        );

        let contextual_left = ".(_left: Left) { make() }";
        let contextual_right = ".(_right: Right) { make() }";
        let contextual_call =
            format!("match(source) {{ ({contextual_left}, {contextual_right}) }}");
        let contextual_source = format!(
            "module main; {common} host fn make[A]() -> A; \
             fn run(source: Left | Right) -> I32 {{ {contextual_call} }}"
        );
        let contextual_package =
            lowered_macro_package(&contextual_source).expect("lower context-dependent clause pair");
        assert_success(
            "certified context-dependent pair",
            &contextual_package,
            &contextual_source,
            &contextual_call,
            &[contextual_left, contextual_right],
            &[1, 1],
            vec![
                leaf(&[0], 0, None),
                leaf(&[1, 0], 1, Some(0)),
                leaf(&[1, 1], 2, Some(1)),
            ],
            2,
        );

        let contextual_spanned_source = add_macro_imports(&contextual_source);
        let contextual_original = retained_call_at(
            &contextual_package,
            "main",
            source_span(&contextual_spanned_source, &contextual_call),
        );
        let (contextual_packet_span, contextual_clauses_span) =
            retained_match_packet_spans(&contextual_original);
        reset_observations(contextual_packet_span);
        let (contextual_baseline_elaborations, contextual_baseline_scope, contextual_baseline) =
            check_retained_function_from_final_preflight(&contextual_package, "main", "run");
        contextual_baseline
            .expect("the certified contextual pair must complete from FinalPreflight");
        assert_eq!(
            contextual_baseline_scope
                .memo()
                .user_macro_template_executions(),
            1
        );
        assert_retained_call_published(
            &contextual_baseline_elaborations,
            "main",
            &contextual_original,
        );
        assert_source_topology(
            "certified contextual pair from FinalPreflight",
            contextual_packet_span,
            vec![
                leaf(&[0], 0, None),
                leaf(&[1, 0], 1, Some(0)),
                leaf(&[1, 1], 2, Some(1)),
            ],
        );
        assert_eq!(
            crate::pass::typecheck_core::apply::fills::pair_wrapper_finalizations(),
            2
        );
        assert_lambda_entries(
            "certified contextual pair from FinalPreflight",
            &contextual_spanned_source,
            &[contextual_left, contextual_right],
            &[1, 1],
        );

        reset_observations(contextual_packet_span);
        let bypass = crate::pass::typecheck_core::apply::fills::disable_pair_transparency_at(
            "main",
            contextual_clauses_span,
        );
        let (contextual_elaborations, contextual_scope, contextual_result) =
            check_retained_function_from_final_preflight(&contextual_package, "main", "run");
        let error = contextual_result
            .expect_err("an opaque pair cannot infer make's result before the outer fill");
        assert!(
            matches!(&error, Error::Type(diagnostic) if diagnostic.message.contains("cannot infer")),
            "ordinary pre-input inference must reject the unresolved result: {error:#?}"
        );
        let error_span = error.diagnostic().span;
        assert!(
            error_span.start >= contextual_clauses_span.start
                && error_span.end <= contextual_clauses_span.end,
            "the missing result must be diagnosed inside the opaque clauses: {error:#?}"
        );
        assert_eq!(contextual_scope.memo().user_macro_template_executions(), 0);
        assert_retained_call_unpublished(&contextual_elaborations, "main", &contextual_original);
        assert_source_topology(
            "certificate-bypassed context-dependent pair",
            contextual_packet_span,
            vec![leaf(&[0], 0, None), leaf(&[1], 1, Some(0))],
        );
        assert_eq!(
            crate::pass::typecheck_core::apply::fills::pair_wrapper_finalizations(),
            0
        );
        assert_lambda_entries(
            "certificate-bypassed context-dependent pair",
            &contextual_spanned_source,
            &[contextual_left],
            &[0],
        );
        assert_eq!(bypass.hits(), 1);
        drop(bypass);

        let opaque_source_expr = format!("complete_product({left}, {right})");
        let opaque_call = format!("match(source) {{ {opaque_source_expr} }}");
        let opaque_source = format!(
            "module main; {common} \
             type Result_fn = I32 -> I32; \
             type Left_clause = Left -> Result_fn; \
             type Right_clause = Right -> Result_fn; \
             fn complete_product(left: Left_clause, right: Right_clause) \
               -> Left_clause & Right_clause {{ (left, right) }} \
             fn run(source: Left | Right) -> Result_fn {{ {opaque_call} }}"
        );
        let opaque_package =
            lowered_macro_package(&opaque_source).expect("lower opaque-wrapper match package");
        assert_success(
            "opaque complete-product wrapper",
            &opaque_package,
            &opaque_source,
            &opaque_call,
            &[left, right],
            &[1, 1],
            vec![leaf(&[0], 0, None), leaf(&[1], 1, Some(0))],
            1,
        );

        let middle = ".(_middle: Middle) { identity_i32 }";
        let nested_clauses = format!("({left}, {middle}, {right})");
        let nested_call = format!("match(source) {{ {nested_clauses} }}");
        let nested_source = format!(
            "module main; host type Middle; {common} \
             fn run(source: Left | Middle | Right) -> I32 -> I32 {{ {nested_call} }}"
        );
        let nested_package =
            lowered_macro_package(&nested_source).expect("lower nested-pair match package");
        assert_success(
            "nested canonical pair",
            &nested_package,
            &nested_source,
            &nested_call,
            &[left, middle, right],
            &[1, 1, 1],
            vec![
                leaf(&[0], 0, None),
                leaf(&[1, 0], 1, Some(0)),
                leaf(&[1, 1, 0], 2, Some(1)),
                leaf(&[1, 1, 1], 3, Some(2)),
            ],
            3,
        );

        let closed_clauses = "(left_clause, right_clause)";
        let closed_call = format!("match(source) {{ {closed_clauses} }}");
        let closed_source = format!(
            "module main; \
             host type Left; host type Right; host type I32 role(i32); \
             type Result_fn = I32 -> I32; \
             fn identity_i32(value: I32) -> I32 {{ value }} \
             fn run(source: Left | Right) -> Result_fn {{ \
               let .(left_clause: Left -> Result_fn) = {left}; \
               let .(right_clause: Right -> Result_fn) = {right}; \
               {closed_call} \
             }}"
        );
        let closed_package =
            lowered_macro_package(&closed_source).expect("lower closed-pair match package");
        assert_success(
            "closed canonical pair",
            &closed_package,
            &closed_source,
            &closed_call,
            &[left, right],
            &[0, 0],
            vec![
                leaf(&[0], 0, None),
                leaf(&[1, 0], 1, None),
                leaf(&[1, 1], 2, None),
            ],
            2,
        );
    }

    #[test]
    fn match_authored_relation_order_causal_matrix() {
        let result = std::thread::Builder::new()
            .name("match-authored-relation-order".to_owned())
            // The real match support package overflows libtest's default
            // debug stack; 8 MiB is the smallest measured passing bound.
            .stack_size(8 * 1024 * 1024)
            .spawn(run_match_authored_relation_order_causal_matrix)
            .expect("spawn match authored-relation matrix")
            .join();
        if let Err(payload) = result {
            std::panic::resume_unwind(payload);
        }
    }

    fn run_match_authored_relation_order_causal_matrix() {
        fn observed_call(
            package: &Package,
            source: &str,
            call: &str,
        ) -> (
            Expr,
            crate::pass::typecheck_core::apply::fills::ReturnedFillRelationObserver,
        ) {
            let spanned_source = add_macro_imports(source);
            let original = retained_call_at(package, "main", source_span(&spanned_source, call));
            let observer =
                crate::pass::typecheck_core::apply::fills::observe_returned_fill_relations_at(
                    "main",
                    original.span(),
                );
            (original, observer)
        }

        fn assert_transcript(
            label: &str,
            observations: Vec<
                Vec<crate::pass::typecheck_core::apply::fills::ReturnedFillRelationObservation>,
            >,
            expected_candidates: &[&str],
            destination_closed: bool,
        ) {
            assert_eq!(
                observations.len(),
                1,
                "{label} must evaluate and return one fill transcript: {observations:#?}"
            );
            let relations = &observations[0];
            assert_eq!(
                relations.len(),
                expected_candidates.len(),
                "{label} returned the wrong relation count: {relations:#?}"
            );
            let destination_root = relations
                .first()
                .expect("the match transcript is nonempty")
                .destination_root;
            assert!(
                relations.iter().all(|relation| {
                    relation.destination_root == destination_root
                        && relation.destination_path.is_empty()
                        && relation.destination_closed == destination_closed
                }),
                "{label} must relate every occurrence to the same whole Target: {relations:#?}"
            );
            assert_eq!(
                relations
                    .iter()
                    .map(|relation| relation.candidate_display.as_str())
                    .collect::<Vec<_>>(),
                expected_candidates,
                "{label} changed the authenticated result occurrences"
            );
        }

        let success_call = r#"match(source) {
              (
                .(_boxed_i32: Box[I32]) -> String { make_string() },
                .(_other: Other) -> String { make_string() },
                .[A](_boxed: Box[A]) -> String { make_string() }
              )
            }"#;
        let success_source = format!(
            r#"module main;
            host type Other;
            host type I32;
            host type String;
            host fn make_string() -> String;
            type {{ Box[A]: A {{ mk; get; }}; }};
            fn consume(_value: String) -> . {{ () }}
            fn run(source: Box[I32] | Other | Box[String]) -> . {{
              let selected = {success_call};
              consume(selected)
            }}"#
        );
        let success_package =
            lowered_macro_package(&success_source).expect("lower authored-order success package");
        let (success_original, success_observer) =
            observed_call(&success_package, &success_source, success_call);
        let (elaborations, scope, result) = check_retained_module(&success_package, "main");
        result.expect("the authored-order caller closes");
        assert_eq!(scope.memo().user_macro_template_executions(), 1);
        assert_retained_call_published(&elaborations, "main", &success_original);
        assert_transcript(
            "permuted three-branch match",
            success_observer.take(),
            &["main.String", "main.String", "main.String", "main.String"],
            false,
        );
        let (checked, _) = check_retained_success(&success_package);
        validate_substituted_package(checked.substituted())
            .expect("the authored-order match survives standalone Prime validation");

        let error_call = r#"match(source) {
              (
                .(_boxed_i32: Box[I32]) -> String { make_string() },
                .(_other: Other) -> String { make_string() },
                .[A](boxed: Box[A]) -> A { Box.get[A](boxed) }
              )
            }"#;
        let error_source = format!(
            r#"module main;
            host type Other;
            host type I32;
            host type String;
            host fn make_string() -> String;
            type {{ Box[A]: A {{ mk; get; }}; }};
            fn run(source: Box[I32] | Other | Box[String]) -> . {{
              let .(_selected: String) = {error_call};
              ()
            }}"#
        );
        let error_package =
            lowered_macro_package(&error_source).expect("lower shadowed-result error package");
        let (error_original, error_observer) =
            observed_call(&error_package, &error_source, error_call);
        let (elaborations, scope, errors) = check_retained_module_error(&error_package, "main");
        assert!(
            errors.iter().any(|error| matches!(
                error,
                Error::Type(diagnostic) if diagnostic.message.contains("type mismatch")
            )),
            "the shadowed polymorphic I32 result must disagree with preclosed String: {errors:#?}"
        );
        assert_eq!(scope.memo().user_macro_template_executions(), 1);
        assert_retained_call_unpublished(&elaborations, "main", &error_original);
        assert_transcript(
            "shadowed polymorphic result mismatch",
            error_observer.take(),
            &["main.String", "main.String", "main.I32", "main.String"],
            true,
        );
    }

    #[test]
    fn retained_type_producing_result_mismatch_evaluates_once_without_publication() {
        let macro_def = "module macros; \
            import __comptime__; \
            pub host type I32; \
            pure fn wrong_shape_impl( \
                _ct: __Comptime__, \
                _source: __Type__, \
                value: __Checked_term__, \
                _a: . \
              ) -> __Checked_term__ { value } \
            pub macro wrong_shape : [Source] Source -> [A] I32 & A { impl wrong_shape_impl; };";
        let main = "module main; \
            import macros(I32, macro wrong_shape); \
            host type String role(str); \
            fn run() -> . { \
              let _wrong = wrong_shape(\"not a product\"[String]); \
              () \
            }";
        let package = lowered_package(&[("macros.kio", macro_def), ("main.kio", main)]);
        let original = retained_call_at(
            &package,
            "main",
            source_span(main, "wrong_shape(\"not a product\"[String])"),
        );
        let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

        assert!(
            errors
                .iter()
                .any(|error| error.diagnostic().message.contains("type mismatch")),
            "the evaluator's exact String result must reject the declared product: {errors:#?}"
        );
        assert_retained_call_unpublished(&elaborations, "main", &original);
        assert_eq!(scope.memo().user_macro_template_executions(), 1);
    }

    #[test]
    fn retained_type_producing_macro_solves_a_partial_contextual_result() {
        let main = "module main; \
            import macros(macro infer_pair); \
            host type I32 role(i32); \
            host type String role(str); \
            host fn take[H](pair: I32 & H) -> H; \
            fn run() -> String { take(infer_pair((0[I32], \"closed\"[String]))) }";
        let package =
            lowered_package(&[("macros.kio", RETAINED_ACTION_MACROS), ("main.kio", main)]);
        let original = retained_call_at(
            &package,
            "main",
            source_span(main, "infer_pair((0[I32], \"closed\"[String]))"),
        );
        let (checked, scope) = check_retained_success(&package);

        assert!(
            checked
                .elaborations()
                .elaboration_for("main", &original)
                .is_some(),
            "the returned `I32 & String` term must close `A & B` against `I32 & H`"
        );
        assert_eq!(scope.memo().user_macro_template_executions(), 1);
        validate_substituted_package(checked.substituted())
            .expect("the contextual result survives standalone Prime validation");
    }

    #[test]
    fn unresolved_required_macro_dependency_prevents_evaluation() {
        let macro_def = "module macros; \
            import __comptime__; \
            pure fn require_type_impl( \
                ct: __Comptime__, \
                required: __Type__ \
              ) -> __Checked_term__ { \
                __macro_error__(ct, __type_display__(ct, required)) \
              } \
            pub macro require_type : [Required] . -> . { impl require_type_impl; };";
        let main = "module main; \
            import macros(macro require_type); \
            fn run() -> . { require_type() }";
        let package = lowered_package(&[("macros.kio", macro_def), ("main.kio", main)]);
        let original = retained_call_at(&package, "main", source_span(main, "require_type()"));
        let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

        assert!(
            errors.iter().any(|error| {
                error
                    .diagnostic()
                    .message
                    .contains("cannot infer type argument `[Required]`")
            }),
            "the required reflected source type must close before evaluation: {errors:#?}"
        );
        assert_retained_call_unpublished(&elaborations, "main", &original);
        assert_eq!(scope.memo().user_macro_template_executions(), 0);
    }

    #[test]
    fn retained_macro_ufcs_places_each_receiver_once() {
        for (case, call, return_ty) in [
            ("receiver_first", "(receiver.>first)(other)", "I32"),
            ("receiver_last", "first(other)[_].<receiver", "I32"),
        ] {
            let (receiver_ty, other_ty) = if case == "receiver_first" {
                ("I32", "String")
            } else {
                ("String", "I32")
            };
            let main = format!(
                "module main; \
                 import macros(macro first); \
                 host type I32 role(i32); \
                 host type String role(str); \
                 fn run(receiver: {receiver_ty}, other: {other_ty}) -> {return_ty} {{ {call} }}"
            );
            let package =
                lowered_package(&[("macros.kio", RETAINED_ACTION_MACROS), ("main.kio", &main)]);
            let original = package
                .module("main")
                .expect("caller module")
                .module
                .items
                .iter()
                .find_map(|item| match item {
                    Item::FnDef(def) if def.name == "run" => Some(def.body.clone()),
                    _ => None,
                })
                .expect("the caller body is the one staged macro invocation");
            let Expr::UserMacro { name, stages, .. } = &original else {
                panic!("UFCS lowers to one ordinary staged macro invocation")
            };
            assert_eq!(name, "first");
            let values = stages
                .iter()
                .flat_map(|stage| stage.args.iter())
                .filter_map(|argument| match argument {
                    CallArg::Value(Expr::Path { segments, .. }) => {
                        let [segment] = segments.as_slice() else {
                            panic!("each written operand is one lexical parameter")
                        };
                        Some(segment.as_str())
                    }
                    CallArg::Value(_) => panic!("the receiver or other operand changed shape"),
                    CallArg::Type(_) => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(
                values,
                if case == "receiver_first" {
                    vec!["receiver", "other"]
                } else {
                    vec!["other", "receiver"]
                },
                "the two public value stages retain each written parameter exactly once"
            );
            let (checked, scope) = check_retained_success(&package);

            assert!(
                checked
                    .elaborations()
                    .elaboration_for("main", &original)
                    .is_some(),
                "{case} publishes its exact-arity elaboration"
            );
            assert_eq!(
                scope.memo().user_macro_template_executions(),
                1,
                "{case} evaluates its single receiver splice once"
            );
            validate_substituted_package(checked.substituted())
                .unwrap_or_else(|error| panic!("{case} survives Prime validation: {error:?}"));
        }
    }

    #[test]
    fn failed_later_sibling_rolls_back_macro_actions_without_evaluation() {
        let cases = [
            ("ordinary", "infer_pair((0[I32], \"closed\"[String]))"),
            ("receiver_first", "(0[I32], \"closed\"[String]).>infer_pair"),
            ("receiver_last", "(0[I32], \"closed\"[String]).>>infer_pair"),
        ];
        let mut premature_evaluations = Vec::new();

        for (case, call) in cases {
            let run_call = format!("consume({call}, bad())");
            let main = format!(
                "module main; \
                 import macros(macro infer_pair); \
                 host type I32 role(i32); \
                 host type String role(str); \
                 host fn good_i32() -> I32; \
                 host fn bad() -> String; \
                 fn consume[T](_value: T, _must_i32: I32) -> . {{ () }} \
                 fn run() -> . {{ {run_call} }}"
            );
            let package =
                lowered_package(&[("macros.kio", RETAINED_ACTION_MACROS), ("main.kio", &main)]);
            let original = retained_call_at(&package, "main", source_span(&main, call));
            let (elaborations, scope, errors) = check_retained_module_error(&package, "main");
            assert!(
                errors.iter().any(|error| {
                    error.diagnostic().span.start > original.span().end
                        && error.diagnostic().message
                            == "type mismatch: expected `I32`, found `String`"
                }),
                "{case} must reach the independent later mismatch, got: {errors:#?}"
            );
            assert_retained_call_unpublished(&elaborations, "main", &original);
            let executions = scope.memo().user_macro_template_executions();
            if executions != 0 {
                premature_evaluations.push((case, executions));
            }

            let success_call = format!("consume({call}, good_i32())");
            let success_main = main.replacen(&run_call, &success_call, 1);
            let success_package = lowered_package(&[
                ("macros.kio", RETAINED_ACTION_MACROS),
                ("main.kio", &success_main),
            ]);
            let success_original =
                retained_call_at(&success_package, "main", source_span(&success_main, call));
            let (checked, success_scope) = check_retained_success(&success_package);
            assert!(
                checked
                    .elaborations()
                    .elaboration_for("main", &success_original)
                    .is_some(),
                "{case} success must publish the prepared action"
            );
            assert_eq!(
                success_scope.memo().user_macro_template_executions(),
                1,
                "{case} success must evaluate the type-producing action once"
            );
            validate_substituted_package(checked.substituted()).unwrap_or_else(|error| {
                panic!("{case} success survives Prime validation: {error:?}")
            });
        }
        assert!(
            premature_evaluations.is_empty(),
            "prepared actions evaluated before an independent later mismatch: \
             {premature_evaluations:?}"
        );
    }

    #[test]
    fn failed_later_retained_action_preflights_before_type_producing_evaluation() {
        let macro_def = "module macros; \
            import __comptime__; \
            pure fn infer_pair_impl( \
                _ct: __Comptime__, \
                _source: __Type__, \
                value: __Checked_term__, \
                _a: ., \
                _b: . \
              ) -> __Checked_term__ { value } \
            pub macro infer_pair : [Source] Source -> [A] [B] A & B { impl infer_pair_impl; }; \
            pure fn require_type_impl( \
                ct: __Comptime__, \
                required: __Type__ \
              ) -> __Checked_term__ { \
                __macro_error__(ct, __type_display__(ct, required)) \
              } \
            pub macro require_type : [Required] . -> . { impl require_type_impl; };";
        let main = "module main; \
            import macros(macro infer_pair, macro require_type); \
            host type I32 role(i32); \
            host type String role(str); \
            fn consume[T](_first: T, _second: .) -> . { () } \
            fn run() -> . { \
              consume(infer_pair((0[I32], \"closed\"[String])), require_type()) \
            }";
        let package = lowered_package(&[("macros.kio", macro_def), ("main.kio", main)]);
        let first = retained_call_at(
            &package,
            "main",
            source_span(main, "infer_pair((0[I32], \"closed\"[String]))"),
        );
        let second = retained_call_at(&package, "main", source_span(main, "require_type()"));
        let (elaborations, scope, errors) = check_retained_module_error(&package, "main");

        assert!(
            errors.iter().any(|error| error
                .diagnostic()
                .message
                .contains("cannot infer type argument `[Required]`")),
            "the later retained Required action must reject at Final: {errors:#?}"
        );
        assert_retained_call_unpublished(&elaborations, "main", &first);
        assert_retained_call_unpublished(&elaborations, "main", &second);
        assert_eq!(
            scope.memo().user_macro_template_executions(),
            0,
            "no ready sibling action may execute before every retained sibling preflights"
        );
    }

    #[test]
    fn retained_capture_inputs_close_in_the_macro_definition_environment() {
        let same_module = "module main; \
            import __comptime__; \
            type { Local: . { mk; get; }; }; \
            pure fn reveal_capture_impl( \
              ct: __Comptime__, \
              captured: __Type__, \
              _source: __Type__, \
              _value: __Checked_term__ \
            ) -> __Checked_term__ { \
              __macro_error__(ct, __type_display__(ct, captured)) \
            } \
            macro reveal_capture : [T] T -> . { \
              captures Local; \
              impl reveal_capture_impl; \
            }; \
            host type I32; \
            host fn witness() -> I32; \
            fn consume[T](_f: T -> ., _value: T) -> . { () } \
            fn run() -> . { \
              consume(.(value) { reveal_capture(value) }, witness()) \
            }";
        let same_package = lowered_package(&[("main.kio", same_module)]);
        let (_, same_scope, same_errors) = check_retained_module_error(&same_package, "main");
        let same_message = same_errors
            .iter()
            .find_map(|error| match error {
                Error::Macro(diagnostic) => Some(diagnostic.message.as_str()),
                _ => None,
            })
            .unwrap_or_else(|| {
                panic!("same-module macro reports its captured type: {same_errors:#?}")
            });
        assert_eq!(same_message, "main.Local");
        assert_eq!(same_scope.memo().user_macro_template_executions(), 1);

        let owner_types = "module owner/types; \
            pub type { Owner: . { pub mk; pub get; }; };";
        let other_types = "module other/types; \
            pub type { Owner: . { pub mk; pub get; }; };";
        let owner_macro = "module owner/macros; \
            import __comptime__; \
            import owner/types(Owner); \
            pure fn reveal_capture_impl( \
              ct: __Comptime__, \
              captured: __Type__, \
              _source: __Type__, \
              _value: __Checked_term__ \
            ) -> __Checked_term__ { \
              __macro_error__(ct, __type_display__(ct, captured)) \
            } \
            pub macro reveal_capture : [T] T -> . { \
              captures Owner; \
              impl reveal_capture_impl; \
            };";
        let imported_main = "module main; \
            import owner/macros(macro reveal_capture); \
            import other/types(Owner); \
            host type I32; \
            host fn witness() -> I32; \
            fn consume[T](_f: T -> ., _value: T) -> . { () } \
            fn run() -> . { \
              consume(.(value) { reveal_capture(value) }, witness()) \
            }";
        let imported_package = lowered_package(&[
            ("owner/types.kio", owner_types),
            ("other/types.kio", other_types),
            ("owner/macros.kio", owner_macro),
            ("main.kio", imported_main),
        ]);
        let (_, imported_scope, imported_errors) =
            check_retained_module_error(&imported_package, "main");
        let imported_message = imported_errors
            .iter()
            .find_map(|error| match error {
                Error::Macro(diagnostic) => Some(diagnostic.message.as_str()),
                _ => None,
            })
            .unwrap_or_else(|| {
                panic!("imported macro reports its captured type: {imported_errors:#?}")
            });
        assert_eq!(imported_message, "owner/types.Owner");
        assert!(!imported_message.contains("other/types"));
        assert_eq!(imported_scope.memo().user_macro_template_executions(), 1);
    }

    #[test]
    fn retained_macro_preparation_ignores_caller_local_shadows() {
        let same_module = "module main; \
            import __comptime__; \
            host type I32; \
            host type Shadow; \
            host fn shadow() -> Shadow; \
            pure fn helper(value: I32) -> I32 { value } \
            pure fn capture_impl( \
              ct: __Comptime__, \
              captured: __Checked_term__, \
              _source: __Type__, \
              _value: __Checked_term__ \
            ) -> __Checked_term__ { \
              __macro_error__(ct, __type_display__(ct, __term_type__(ct, captured))) \
            } \
            macro expose : [T] T -> . { \
              captures helper; \
              impl capture_impl; \
            }; \
            fn consume[T]( \
              _f: (T & T) -> ., \
              _value: T \
            ) -> . { () } \
            fn run() -> . { \
              consume(.(helper, capture_impl) { expose(helper) }, shadow()) \
            }";
        let same_package = lowered_package(&[("main.kio", same_module)]);
        let (_, same_scope, same_errors) = check_retained_module_error(&same_package, "main");
        let same_message = same_errors
            .iter()
            .find_map(|error| match error {
                Error::Macro(diagnostic) => Some(diagnostic.message.as_str()),
                _ => None,
            })
            .unwrap_or_else(|| {
                panic!("same-module macro reports the captured function type: {same_errors:#?}")
            });
        assert_eq!(same_message, "main.I32 -> main.I32");
        assert_eq!(same_scope.memo().user_macro_template_executions(), 1);

        let owner = "module owner/macros; \
            import __comptime__; \
            pub host type I32; \
            pub pure fn helper(value: I32) -> I32 { value } \
            pure fn capture_impl( \
              ct: __Comptime__, \
              captured: __Checked_term__, \
              _source: __Type__, \
              _value: __Checked_term__ \
            ) -> __Checked_term__ { \
              __macro_error__(ct, __type_display__(ct, __term_type__(ct, captured))) \
            } \
            pub macro expose : [T] T -> . { \
              captures helper; \
              impl capture_impl; \
            };";
        let imported_main = "module main; \
            import owner/macros(I32, macro expose); \
            host type Shadow; \
            host fn shadow() -> Shadow; \
            fn consume[T]( \
              _f: (T & T) -> ., \
              _value: T \
            ) -> . { () } \
            fn run() -> . { \
              consume(.(helper, capture_impl) { expose(helper) }, shadow()) \
            }";
        let imported_package =
            lowered_package(&[("owner/macros.kio", owner), ("main.kio", imported_main)]);
        let (_, imported_scope, imported_errors) =
            check_retained_module_error(&imported_package, "main");
        let imported_message = imported_errors
            .iter()
            .find_map(|error| match error {
                Error::Macro(diagnostic) => Some(diagnostic.message.as_str()),
                _ => None,
            })
            .unwrap_or_else(|| {
                panic!("imported macro reports the captured function type: {imported_errors:#?}")
            });
        assert_eq!(imported_message, "owner/macros.I32 -> owner/macros.I32");
        assert_eq!(imported_scope.memo().user_macro_template_executions(), 1);
    }

